import {
  Component,
  Input,
  OnChanges,
  SimpleChanges,
  AfterViewInit,
  ViewChild,
  ElementRef
} from '@angular/core';

import {
  Chart,
  RadarController,
  RadialLinearScale,
  PointElement,
  LineElement,
  Filler,
  Tooltip,
  Title,
  SubTitle,
  Legend
} from 'chart.js';

Chart.register(RadarController, RadialLinearScale, PointElement, LineElement, Filler, Tooltip, Title, SubTitle, Legend);

Chart.defaults.font.size = 20;

interface RadarDataset {
  label: string;
  data: number[];
  backgroundColor?: string;
  borderColor?: string;
  borderWidth?: number;
  fill?: boolean;
}

@Component({
    selector: 'app-radar-chart',
    imports: [],
    template: `
    <div class="chart-container">
      <canvas #radarCanvas></canvas>
    </div>
  `,
    styles: [`
    .chart-container {
      position: relative;
      width: 100%;
      height: 100%;
    }
    canvas {
      width: 100% ;
      height: 100% ;
    }
  `]
})
export class RadarChartComponent implements OnChanges, AfterViewInit {
  @ViewChild('radarCanvas') radarCanvas!: ElementRef<HTMLCanvasElement>;

  @Input() labels: string[] = [];
  @Input() datasets: RadarDataset[] = [];
  @Input() title: string = '';
  @Input() subtitle: string = '';

  private chart: Chart | undefined;

  ngAfterViewInit(): void {
    this.renderChart();
  }

  ngOnChanges(changes: SimpleChanges): void {
    if (this.chart) {
      this.updateChart();
    }
  }

  private renderChart() {
    const ctx = this.radarCanvas.nativeElement.getContext('2d');
    if (!ctx) return;

    this.chart = new Chart(ctx, {
      type: 'radar',
      data: {
        labels: this.labels,
        datasets: this.datasets.map(ds => ({
          label: ds.label,
          data: ds.data,
          backgroundColor: ds.backgroundColor ?? 'rgba(106, 28, 50, 0.3)',
          borderColor: ds.borderColor ?? '#6A1C32',
          borderWidth: ds.borderWidth ?? 2,
          fill: ds.fill ?? true
        }))
      },
      options: {
        responsive: true,
        plugins: {
          legend: {
            position: 'top'
          },
          title: {
            display: !!this.title,
            text: this.title,
            font: { size: 25 },
            padding: { top: 10, bottom: 5 }
          },
          subtitle: {
            display: !!this.subtitle,
            text: this.subtitle,
            font: { size: 20 },
            color: '#6b7280',
            padding: { bottom: 10 }
          },
          tooltip: {
            bodyFont: {
              size: 16
            },
            titleFont: {
              size: 16
            },
            footerFont: {
              size: 18
            },
            padding: 8
          }
        },
        scales: {
          r: {
            pointLabels: {
              font: {
                size: 14
              },
              color: '#374151'
            },
            ticks: {
              font: {
                size: 16
              }
            }
          }
        },
        elements: {
          line: {
            tension: 0.1
          }
        },
        onClick: (event, elements, chart) => {
          const points = chart.getElementsAtEventForMode(event as unknown as Event, 'nearest', { intersect: true }, true);
          if (points.length) {
            const firstPoint = points[0];
            const datasetIndex = firstPoint.datasetIndex;
            const dataIndex = firstPoint.index;

            const dataset = chart.data.datasets[datasetIndex];
            const label = chart.data.labels?.[dataIndex];
            const value = dataset.data[dataIndex];

            alert(`Clicked on:\nLabel: ${label}\nDataset: ${dataset.label}\nValue: ${value}`);
          }
        }
      }
    });
  }

  private updateChart() {
    if (!this.chart) return;

    this.chart.data.labels = this.labels;
    this.chart.data.datasets = this.datasets.map(ds => ({
      label: ds.label,
      data: ds.data,
      backgroundColor: ds.backgroundColor ?? 'rgba(106, 28, 50, 0.3)',
      borderColor: ds.borderColor ?? '#6A1C32',
      borderWidth: ds.borderWidth ?? 2,
      fill: ds.fill ?? true
    }));

    this.chart.options.plugins!.title!.text = this.title;
    this.chart.update();
  }
}
