import { Component, Input, OnChanges, SimpleChanges } from '@angular/core';
import { Row, Table } from '../../interfaces/table';
import { TableGuardService } from '../../guards/tabla-guard.service';

@Component({
  selector: 'app-tabla-dinamica',
  imports: [],
  templateUrl: './tabla-dinamica.component.html',
  styleUrl: './tabla-dinamica.component.css'
})
export class TablaDinamicaComponent implements OnChanges {
  @Input() table?: Table;
  @Input() tableClass: string = 'table table-striped table-hover table-bordered';
  @Input() headerClass: string = 'table-light';
  @Input() footerClass: string = 'table-secondary';

  constructor(public tableGuard: TableGuardService) {}

  ngOnChanges(changes: SimpleChanges): void {
    if (changes['table'] && changes['table'].currentValue) {
      this.validateTable();
    }
  }

  private validateTable(): void {
    if (!this.table) {
      console.warn('TablaDinamicaComponent: No se proporcionó una tabla');
      return;
    }

    if (!this.tableGuard.isValidTable(this.table)) {
      console.error('TablaDinamicaComponent: La estructura de la tabla no es válida', this.table);
      return;
    }

    // Validación detallada para encontrar undefineds
    try {
      this.tableGuard.validateTableStructure(this.table);
      console.log('✅ TablaDinamicaComponent: Estructura de tabla validada correctamente');
    } catch (error) {
      console.error('🚨 TablaDinamicaComponent: Error en la estructura de la tabla:', error);
      // No lanzamos el error para no romper la aplicación, pero lo registramos
      console.table(this.table);
    }
  }

  // Métodos para el template - delegando al servicio
  getCellText(cell: any): string {
    return this.tableGuard.getCellText(cell);
  }

  getCellStyle(cell: any): string {
    return this.tableGuard.getCellStyle(cell);
  }

  getCellColspan(cell: any): number {
    return this.tableGuard.getCellColspan(cell);
  }

  getRowCells(row: any): any[] {
    return this.tableGuard.getRowCells(row);
  }

  getRowStyle(row: Row): string {
    return this.tableGuard.getRowStyle(row);
  }

  getHeaderRows(header: any): any[] {
    return this.tableGuard.getHeaderRows(header);
  }

  getHeaderStyle(header: any): string {
    return this.tableGuard.getHeaderStyle(header);
  }

  getFooterRows(footer: any): Row[] {
    return this.tableGuard.getFooterRows(footer);
  }

  getFooterStyle(footer: any): string {
    return this.tableGuard.getFooterStyle(footer);
  }

  // Métodos para verificar si la tabla tiene footer y body
  hasFooter(): boolean {
    return this.table ? this.tableGuard.hasFooter(this.table) : false;
  }

  hasBody(): boolean {
    return this.table ? this.tableGuard.hasBody(this.table) : false;
  }

  // Métodos para obtener el body
  getBodyRows(): any[] {
    if (!this.hasBody()) {
      return [];
    }
    return this.tableGuard.getBodyRows(this.table!.body);
  }
}
