import { Component, EventEmitter, Input, Output } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { ColumnConfig, FinalView, CurrentView } from '../informe-tabla-dinamica-local.component';
import { GeneradorExcelService } from '../../../reportes/services/generador-excel.service';
import { CrossTabUtilsService, TotalsData } from '../services/cross-tab-utils.service';
import { TablaDinamicaComponent } from "../shared/tabla-dinamica/tabla-dinamica.component";
import { Table } from '../interfaces/table';
import { TableToGraphConverterService } from '../services/table-to-graph-converter.service';
import { GraphType } from '../graphs-view/graphs-view.component';
import {
  CrossTabConfigFormComponent,
  TotalsConfigComponent,
  MetricsConfigComponent,
  GraphsConfigComponent,
  CrossTabListPreviewComponent
} from './components';

export interface SelectItem {
  label: string;
  value: string;
}

// Re-exportar tipos para uso en subcomponentes
export type { ColumnConfig } from '../informe-tabla-dinamica-local.component';

export interface MetricConfig {
  calculation: MetricConfigCalculation;
  valueField?: string; // para sum/average/cross/percent
  crossField?: string; // para cross: campo adicional para cruzar (ej: 'genero')
  label?: string; // nombre amigable para mostrar (ej: "No. Proyectos", "Monto", "Porcentaje"). Para cross, se usa el valor del campo cruzado
  pipe?: MetricPipeOptions;
  minFractionDigits?: number;
  maxFractionDigits?: number;
  // Filtros específicos de la métrica aplicados antes del cálculo
  metricFilters?: Record<string, string>;
  // Base para cálculo de porcentajes (solo aplica para calculation === 'count')
  percentageBase?: 'filtered' | 'unfiltered'; // 'filtered': datos filtrados, 'unfiltered': datos originales
}

export type MetricConfigCalculation = 'count' | 'sum' | 'average' | 'cross' | 'percent';

export type MetricPipeOptions = 'currency' | 'number' | 'percent'

export interface GraphConfig {
  id: string;
  title: string;
  graphType: GraphType;
  labelColumn: string; // Columna para labels
  valueColumn: string; // Columna para valores (opcional para count)
  operation: 'count' | 'sum';
  pipe?: MetricPipeOptions; // Para formato
  chartMaxValue?:number;

  // Nuevas propiedades para soporte de datos basados en columnas
  dataSourceType?: 'row-based' | 'column-based'; // Por defecto 'row-based' para compatibilidad
  selectedColumns?: string[]; // Columnas específicas a incluir (para column-based)
  excludeColumns?: string[]; // Columnas a excluir del cálculo
  usePercentage?: boolean; // Para gráficas de pastel, calcular porcentajes automáticamente
}

export interface CrossTabConfig {
  id: string;
  rowDimension: string;
  columnDimension?: string; // opcional para totales generales
  columnLabel?: string; // etiqueta personalizada cuando no hay columnDimension
  metrics: MetricConfig[]; // múltiples métricas
  showInTable: boolean;
  totales: {
    sum?: boolean;
    percent?: boolean;
  };
  graphs?: GraphConfig[]; // Configuraciones de gráficas
  // Filtros globales que se aplican a todas las métricas antes de sus filtros específicos
  globalFilters?: Record<string, string>;
}

/**
 * Componente para configuración y generación de vistas cruzadas (cross-tab) de datos.
 * Permite crear, configurar y gestionar vistas de datos agrupadas por diferentes dimensiones
 * con soporte para múltiples cálculos (conteo, suma, promedio).
 * 
 * Este componente es standalone y puede ser usado en cualquier parte de la aplicación.
 */
@Component({
  selector: 'app-cross-tab-view-config',
  imports: [
    FormsModule,
    TablaDinamicaComponent,
    CrossTabConfigFormComponent,
    TotalsConfigComponent,
    MetricsConfigComponent,
    GraphsConfigComponent,
    CrossTabListPreviewComponent
  ],
  templateUrl: './cross-tab-view-config.component.html',
  styleUrl: './cross-tab-view-config.component.css'
})
export class CrossTabViewConfigComponent {
  //#region Inputs y Outputs

  /**
   * Lista de todas las columnas disponibles con su configuración
   * @type {ColumnConfig[]}
   */
  @Input() allColumns: ColumnConfig[] = [];

  /**
   * Datos crudos para generar las vistas cruzadas
   * @type {any[]}
   */
  @Input() data: any[] = [];

  /**
   * Vista actualmente activa (normal, cross o final)
   * @type {CurrentView}
   */
  @Input() currentView: CurrentView = 'normal';

  /**
   * Evento emitido cuando cambia la vista actual
   * @type {EventEmitter<CurrentView>}
   */
  @Output() currentViewChange = new EventEmitter<CurrentView>();

  /**
   * Lista de vistas finales configuradas
   */
  @Input() finalViews: FinalView[] = [];

  /**
   * Evento emitido cuando cambia la lista de vistas finales
   */
  @Output() finalViewsChange = new EventEmitter<FinalView[]>();

  /**
   * Indica si el configurador de vista cruzada debe mostrarse
   */
  @Input() showCrossTabConfig = false;

  /**
   * Evento emitido cuando cambia la visibilidad del configurador
   */
  @Output() showCrossTabConfigChange = new EventEmitter<boolean>();

  /**
   * Indica si el configurador de vista final debe mostrarse
   */
  @Input() showFinalViewConfig = false;

  /**
   * Evento emitido cuando cambia la visibilidad del configurador de vista final
   */
  @Output() showFinalViewConfigChange = new EventEmitter<boolean>();

  /**
   * Lista de configuraciones de vistas cruzadas
   */
  @Input() crossTabConfigs: CrossTabConfig[] = [];

  /**
   * Evento emitido cuando cambian las configuraciones
   */
  @Output() crossTabConfigsChange = new EventEmitter<CrossTabConfig[]>();

  // Estructura de encabezados para manejar métricas cross
  headerStructure: {
    firstRow: Array<{ text: string, colspan: number }>;
    secondRow: Array<{ text: string }>;
  } | null = null;

  /**
   * Configuración de vista cruzada actualmente seleccionada
   */
  @Input() currentCrossTab: CrossTabConfig | null = null;

  /**
   * Evento emitido cuando cambia la configuración actual
   */
  @Output() currentCrossTabChange = new EventEmitter<CrossTabConfig | null>();

  /**
   * Evento emitido para solicitar un reset de la vista
   */
  @Output() reset = new EventEmitter<void>();

  showCrossTable = false;

  table: Table | null = null;

  graphRawData: any[]=[]

  // Variables para gráficas
  currentGraph?: GraphConfig;
  showGraphPreview: boolean = false;
  availableColumns: Array<{ label: string; value: string }> = [];
  numericColumns: Array<{ label: string; value: string }> = [];

  // Property para two-way binding de graphs
  get graphs(): GraphConfig[] {
    return this.currentCrossTab?.graphs || [];
  }

  set graphs(value: GraphConfig[]) {
    if (this.currentCrossTab) {
      this.currentCrossTab.graphs = value;
      this.currentCrossTabChange.emit(this.currentCrossTab);
    }
  }

  //#endregion

  constructor(
    public excel: GeneradorExcelService,
    public crossTabUtils: CrossTabUtilsService,
    public tableToGraphConverter: TableToGraphConverterService,
  ) { }

  //#region Métodos públicos

  /**
   * Convierte las columnas disponibles en items para un componente SelectField
   * @param {string | 'number' | 'date' | 'boolean'} [type] - Filtra por tipo de columna (opcional)
   * @returns {SelectItem[]} Array de items para el select
   * 
   * @example
   * // Obtener todas las columnas
   * columnsToSelectItem();
   * 
   * // Obtener solo columnas numéricas
   * columnsToSelectItem('number');
   */
  public columnsToSelectItem(type?: 'string' | 'number' | 'date' | 'boolean'): SelectItem[] {
    if (!type) {
      return this.allColumns.map(c => ({
        label: c.name.toUpperCase().replaceAll('_', ''),
        value: c.name
      }));
    }
    return this.columnsByType(type).map(c => ({
      label: c.name.toUpperCase().replaceAll('_', ''),
      value: c.name
    }));
  }

  viewConfig(config: CrossTabConfig) {
    // Emitir cambios
    this.currentCrossTab = config
    this.currentCrossTabChange.emit(config)
    this.currentView = 'cross'
    this.currentViewChange.emit('cross');
  }

  /**
   * Genera una vista cruzada basada en la configuración proporcionada usando el servicio utils
   * @param {CrossTabConfig} config - Configuración para la vista cruzada
   *
   * @example
   * generateCrossTab({
   *   rowDimension: 'municipio',
   *   columnDimension: 'programa',
   *   calculation: 'sum',
   *   valueField: 'monto'
   * });
   */
  public generateCrossTab(config: CrossTabConfig) {
    if(this.showCrossTable){
      this.showCrossTable=false
      return
    }
    this.generateTable(config)

    // Emitir cambios
    this.currentCrossTab = config
    this.currentCrossTabChange.emit(config)
    this.currentView = 'cross'
    this.currentViewChange.emit('cross');
    this.showCrossTable = true
  }

  public generateTable(config: CrossTabConfig) {
    // Usar el servicio utils para generar los datos cruzados
    const crossData = this.crossTabUtils.generateCrossTab(config, this.data)

    // Actualizar propiedades del componente
    this.headerStructure = crossData.headerStructure

    this.table = this.crossTabUtils.generateTable(config, this.data)

    // Actualizar columnas disponibles para gráficas
    if (this.table) {
      this.availableColumns = this.tableToGraphConverter.getAvailableColumns(this.table);
      this.numericColumns = this.tableToGraphConverter.getNumericColumns(this.table);
    }
  }

  public addCrossTabConfig() {
    const newCrosstab: CrossTabConfig = {
      id: 'config-' + new Date().toISOString(),
      rowDimension: '',
      columnDimension: undefined,
      columnLabel: undefined,
      metrics: [],
      showInTable: false,
      totales: {
        sum: false,
        percent: false
      },
      graphs: [],
      globalFilters: {}
    }
    this.currentCrossTab = newCrosstab
    this.showCrossTabConfig = true
    // Ocultar tabla al crear nueva crosstab para evitar errores
    this.showCrossTable = false
    this.crossTabConfigs.push(newCrosstab)
  }

  public addMetric() {
    this.currentCrossTab!.metrics.push({
      calculation: 'count',
      label: 'Nueva métrica',
      percentageBase: 'filtered' // Default a datos filtrados
    });
  }

  public removeMetric(index: number) {
    this.currentCrossTab!.metrics.splice(index, 1);
  }

  public moveMetricUp(index: number) {
    if (index > 0 && this.currentCrossTab?.metrics) {
      const metrics = [...this.currentCrossTab.metrics];
      [metrics[index - 1], metrics[index]] = [metrics[index], metrics[index - 1]];
      this.currentCrossTab.metrics = metrics;
    }
  }

  public moveMetricDown(index: number) {
    if (index < this.currentCrossTab!.metrics.length - 1 && this.currentCrossTab?.metrics) {
      const metrics = [...this.currentCrossTab.metrics];
      [metrics[index], metrics[index + 1]] = [metrics[index + 1], metrics[index]];
      this.currentCrossTab.metrics = metrics;
    }
  }

  /**
   * Elimina una configuración de vista cruzada
   * @param {string} configId - ID de la configuración a eliminar
   * 
   * @example
   * removeCrossTab('config-12345');
   */
  public removeCrossTab(configId: string): void {
    this.crossTabConfigs = this.crossTabConfigs.filter(c => c.id !== configId);

    // Actualizar vistas finales que referencian esta configuración
    this.finalViews.forEach(view => {
      view.crossConfigs = view.crossConfigs.filter(id => id !== configId);
    });

    // Eliminar vistas finales vacías
    this.finalViews = this.finalViews.filter(view => view.crossConfigs.length > 0);

    this.showCrossTabConfig = false
    // Emitir cambios
    this.crossTabConfigsChange.emit(this.crossTabConfigs);
    this.finalViewsChange.emit(this.finalViews);
  }

  //#endregion

  //#region Métodos privados

  /**
   * Filtra columnas por tipo de dato
   * @private
   * @param {'string' | 'number' | 'date' | 'boolean'} type - Tipo de dato a filtrar
   * @returns {ColumnConfig[]} Columnas que coinciden con el tipo
   */
  private columnsByType(type: 'string' | 'number' | 'date' | 'boolean') {
    return this.allColumns.filter(c => c.dataType === type);
  }


  /**
  * Crea un objeto temporal para usar con el pipe metricvalue (delegado al servicio utils)
  * @param key Clave del objeto
  * @param value Valor del objeto
  * @returns Objeto temporal con la estructura esperada por el pipe
  */
  public createRowObject(key: string, value: number): Record<string, any> {
    return this.crossTabUtils.createRowObject(key, value);
  }

  /**
  * Determina si se deben mostrar los totales en la tabla (delegado al servicio utils)
  * @returns boolean - True si se habilitó totales de suma o percentajes
  */
  public shouldShowTotals(): boolean {
    return this.crossTabUtils.shouldShowTotales(this.currentCrossTab?.totales);
  }


  /**
  * Formatea el label de una métrica para usar como clave (delegado al servicio utils)
  * @param label Label de la métrica
  * @returns Label formateado
  */
  public formatMetricLabel(label: string): string {
    return this.crossTabUtils.formatMetricLabel(label);
  }

  /**
  * Edita una configuración de vista cruzada existente
  * @param config Configuración a editar
  */
  public editCrossTab(config: CrossTabConfig): void {
    this.currentCrossTab = config
    this.generateTable(config)
    this.currentCrossTabChange.emit(config)
    this.showCrossTabConfig = true
    this.showCrossTabConfigChange.emit(true)
    this.showFinalViewConfigChange.emit(false)
  }

  /**
   * Clona una configuración de vista cruzada existente
   * Crea una copia profunda con nuevo ID único y la agrega a la lista
   * @param config Configuración a clonar
   */
  public cloneCrossTabConfig(config: CrossTabConfig): void {
    // Crear una copia profunda de la configuración original
    const clonedConfig: CrossTabConfig = JSON.parse(JSON.stringify(config));

    // Generar nuevo ID único
    clonedConfig.id = 'config-' + new Date().toISOString();

    // Agregar la configuración clonada a la lista
    this.crossTabConfigs.push(clonedConfig);

    // Emitir cambios para actualizar el estado
    this.crossTabConfigsChange.emit(this.crossTabConfigs);

    // Opcionalmente, iniciar edición de la configuración clonada
    this.editCrossTab(clonedConfig);
  }

  //#endregion

  //#region Métodos para gráficas

  /**
   * Agrega una nueva configuración de gráfica
   */
  public addGraph(): void {
    if (!this.currentCrossTab) return;

    const newGraph: GraphConfig = {
      id: 'graph-' + new Date().toISOString(),
      title: '',
      graphType: 'bar',
      labelColumn: '',
      valueColumn: '',
      operation: 'count',
      pipe: undefined
    };

    if (!this.currentCrossTab.graphs) {
      this.currentCrossTab.graphs = [];
    }

    this.generateTable(this.currentCrossTab)

    this.currentCrossTab.graphs.push(newGraph);
    this.currentGraph = newGraph;
    this.showGraphPreview = false;
  }

  /**
   * Edita una configuración de gráfica existente
   * @param graph Gráfica a editar
   */
  public editGraph(graph: GraphConfig): void {
    this.currentGraph = graph;
    this.showGraphPreview = false;
  }

  /**
   * Elimina una configuración de gráfica
   * @param graphId ID de la gráfica a eliminar
   */
  public removeGraph(graphId: string): void {
    if (!this.currentCrossTab || !this.currentCrossTab.graphs) return;

    this.currentCrossTab.graphs = this.currentCrossTab.graphs.filter(g => g.id !== graphId);

    if (this.currentGraph?.id === graphId) {
      this.currentGraph = undefined;
      this.showGraphPreview = false;
    }
  }

  /**
   * Previsualiza la gráfica actual
   */
  public previewGraph(): void {
    if (!this.currentGraph || !this.table) return;

    // Generar título automático si está vacío
    if (!this.currentGraph.title) {
      this.currentGraph.title = this.tableToGraphConverter.generateGraphTitle(
        this.currentGraph.labelColumn,
        this.currentGraph.valueColumn
      );
    }

    this.graphRawData = this.tableToGraphConverter.convertTableToRawData(this.table)

    this.showGraphPreview = true;
  }

  /**
   * Cierra la previsualización de la gráfica
   */
  public closeGraphPreview(): void {
    this.showGraphPreview = false;
  }

  /**
   * Obtiene los tipos de gráficas disponibles
   */
  public get getGraphTypes(): Array<{ label: string; value: GraphType }> {
    return [
      { label: 'Barras', value: 'bar' },
      { label: 'Barras (Horizontal)', value: 'bar-horizontal' },
      { label: 'Circular (Pie)', value: 'pie' },
      { label: 'Donut', value: 'dougnut' },
      { label: 'Líneas', value: 'line' },
      { label: 'Polar', value: 'polar' },
      { label: 'Radar', value: 'radar' },
      { label: 'Barras Apiladas', value: 'stacked-bar' },
      { label: 'Barras Comparativas', value: 'comparison-bar' }
    ];
  }

  /**
   * Determina si el pipe selected es de tipo currency
   */
  public isCurrencyPipe(pipe?: string): boolean {
    return pipe === 'currency';
  }

  //#endregion
}
