import { Component, EventEmitter, inject, Input, Output, OnChanges, SimpleChanges } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { ColumnConfig, FinalView, CurrentView } from '../informe-tabla-dinamica-local.component';
import { GeneradorExcelService } from '../../../reportes/services/generador-excel.service';
import { TablaDinamicaComponent } from "../shared/tabla-dinamica/tabla-dinamica.component";
import { Table } from '../interfaces/table';
import { TableToGraphConverterService } from '../services/table-to-graph-converter.service';
import { GraphType } from '../graphs-view/graphs-view.component';
import { MetricConfig } from '../cross-tab-view-config/components/metrics-config/metrics-config.component';
import {
  FilterBasedConfigFormComponent,
  FilterBasedRowConfigComponent,
  FilterBasedColumnConfigComponent,
  FilterBasedListPreviewComponent
} from './components';
import { FilterBasedUtilsService } from './services/filter-based-utils.service';
import { GraphConfig } from '../types/graph.types';

export interface SelectItem {
  label: string;
  value: string;
}

export interface FilterBasedConfig {
  id: string;
  name: string;
  rows: FilterBasedRow[];
  columns: FilterBasedColumn[];
  showInTable: boolean;
  graphs?: GraphConfig[];
  globalFilters?: Record<string, string>;
}

export interface FilterBasedRow {
  id: string;
  label: string;
  filters: Record<string, string>; // Ej: periodo: '>2025-01-01&<2026-01-01'
}

export interface FilterBasedColumn {
  id: string;
  label: string;
  metrics: MetricConfig[];
  columnFilters?: Record<string, string>;
}

/**
 * Componente para configuración y generación de vistas basadas en filtros.
 * Permite crear configuraciones donde las filas se definen por condiciones de filtros
 * y las columnas contienen métricas calculadas sobre los datos filtrados.
 */
@Component({
  selector: 'app-filter-based-view-config',
  imports: [
    FormsModule,
    TablaDinamicaComponent,
    FilterBasedConfigFormComponent,
    FilterBasedRowConfigComponent,
    FilterBasedColumnConfigComponent,
    FilterBasedListPreviewComponent
  ],
  templateUrl: './filter-based-view-config.component.html',
  styleUrl: './filter-based-view-config.component.css'
})
export class FilterBasedViewConfigComponent implements OnChanges {
  //#region Inputs y Outputs

  @Input() allColumns: ColumnConfig[] = [];
  @Input() data: any[] = [];
  @Input() currentView: CurrentView = 'normal';
  @Output() currentViewChange = new EventEmitter<CurrentView>();

  @Input() finalViews: FinalView[] = [];
  @Output() finalViewsChange = new EventEmitter<FinalView[]>();

  @Input() showFilterBasedConfig = false;
  @Output() showFilterBasedConfigChange = new EventEmitter<boolean>();

  @Input() filterBasedConfigs: FilterBasedConfig[] = [];
  @Output() filterBasedConfigsChange = new EventEmitter<FilterBasedConfig[]>();

  @Input() currentFilterBasedConfig: FilterBasedConfig | null = null;
  @Output() currentFilterBasedConfigChange = new EventEmitter<FilterBasedConfig | null>();

  @Input() showFinalViewConfig = false;
  @Output() showFinalViewConfigChange = new EventEmitter<boolean>();

  @Output() reset = new EventEmitter<void>();

  //#endregion

  showFilterTable = false;
  table: Table | null = null;

  availableColumns: Array<{ label: string; value: string }> = [];
  numericColumns: Array<{ label: string; value: string }> = [];

  // Property para two-way binding de graphs
  get graphs(): GraphConfig[] {
    return this.currentFilterBasedConfig?.graphs || [];
  }

  set graphs(value: GraphConfig[]) {
    if (this.currentFilterBasedConfig) {
      this.currentFilterBasedConfig.graphs = value;
      this.currentFilterBasedConfigChange.emit(this.currentFilterBasedConfig);
    }
  }

  private filterBasedUtils: FilterBasedUtilsService = inject(FilterBasedUtilsService);
  public excel = inject(GeneradorExcelService)
  public tableToGraphConverter = inject(TableToGraphConverterService)

  ngOnChanges(changes: SimpleChanges): void {
    if (changes['filterBasedConfigs']) {
      // Actualizar configs locales cuando cambian desde el padre
      this.filterBasedConfigs = [...changes['filterBasedConfigs'].currentValue];
    }
  }

  //#region Métodos públicos

  public columnsToSelectItem(type?: 'string' | 'number' | 'date' | 'boolean'): SelectItem[] {
    if (!type) {
      return this.allColumns.map(c => ({
        label: c.name.toUpperCase().replaceAll('_', ''),
        value: c.name
      }));
    }
    return this.columnsByType(type).map(c => ({
      label: c.name.toUpperCase().replaceAll('_', ''),
      value: c.name
    }));
  }

  public viewConfig(config: FilterBasedConfig) {
    this.currentFilterBasedConfig = config;
    this.currentFilterBasedConfigChange.emit(config);
    this.currentView = 'filter-based';
    this.currentViewChange.emit('filter-based');
  }

  public generateFilterBased(config: FilterBasedConfig) {
    if (this.showFilterTable) {
      this.showFilterTable = false;
      return;
    }

    this.table = this.filterBasedUtils.generateFilterBasedTable(config, this.data);

    // Actualizar columnas disponibles para gráficas
    if (this.table) {
      this.availableColumns = this.tableToGraphConverter.getAvailableColumns(this.table);
      this.numericColumns = this.tableToGraphConverter.getNumericColumns(this.table);
    }

    this.currentFilterBasedConfig = config;
    this.currentFilterBasedConfigChange.emit(config);
    this.currentView = 'filter-based';
    this.currentViewChange.emit('filter-based');
    this.showFilterTable = true;
  }

  public addFilterBasedConfig() {
    const newConfig: FilterBasedConfig = {
      id: 'filter-config-' + new Date().toISOString(),
      name: '',
      rows: [],
      columns: [],
      showInTable: true,
      graphs: [],
      globalFilters: {}
    };

    this.currentFilterBasedConfig = newConfig;
    this.showFilterBasedConfig = true;
    this.showFilterTable = false;
    this.filterBasedConfigs.push(newConfig);

    // Emitir cambios al componente padre
    this.filterBasedConfigsChange.emit([...this.filterBasedConfigs]);
  }

  public removeFilterBasedConfig(configId: string): void {
    this.filterBasedConfigs = this.filterBasedConfigs.filter(c => c.id !== configId);

    // Actualizar vistas finales que referencian esta configuración
    this.finalViews.forEach(view => {
      view.crossConfigs = view.crossConfigs.filter(id => id !== configId);
    });

    // Eliminar vistas finales vacías
    this.finalViews = this.finalViews.filter(view => view.crossConfigs.length > 0);

    this.showFilterBasedConfig = false;
    this.filterBasedConfigsChange.emit([...this.filterBasedConfigs]);
    this.finalViewsChange.emit([...this.finalViews]);
  }

  public cloneFilterBasedConfig(config: FilterBasedConfig): void {
    const clonedConfig: FilterBasedConfig = JSON.parse(JSON.stringify(config));
    clonedConfig.id = 'filter-config-' + new Date().toISOString();
    clonedConfig.name = `${config.name} (copia)`;

    this.filterBasedConfigs.push(clonedConfig);
    this.filterBasedConfigsChange.emit([...this.filterBasedConfigs]);

    this.editFilterBasedConfig(clonedConfig);
  }

  public editFilterBasedConfig(config: FilterBasedConfig): void {
    this.currentFilterBasedConfig = config;
    this.currentFilterBasedConfigChange.emit(config);
    this.showFilterBasedConfig = true;
    this.showFilterBasedConfigChange.emit(true);
    this.showFilterTable = false;
  }

  /**
   * Agrega una nueva fila a la configuración actual
   */
  public addNewRow(): void {
    if (this.currentFilterBasedConfig) {
      this.currentFilterBasedConfig.rows.push({
        id: 'row-' + new Date().toISOString(),
        label: '',
        filters: {}
      });
    }
  }

  /**
   * Agrega una nueva columna a la configuración actual
   */
  public addNewColumn(): void {
    if (this.currentFilterBasedConfig) {
      this.currentFilterBasedConfig.columns.push({
        id: 'column-' + new Date().toISOString(),
        label: '',
        metrics: []
      });
    }
  }

  //#endregion

  //#region Métodos privados

  private columnsByType(type: 'string' | 'number' | 'date' | 'boolean') {
    return this.allColumns.filter(c => c.dataType === type);
  }

  //#endregion

  //#region Métodos para gráficas

  public addGraph(): void {
    if (!this.currentFilterBasedConfig) return;

    const newGraph: GraphConfig = {
      id: 'graph-' + new Date().toISOString(),
      title: '',
      graphType: 'bar',
      labelColumn: '',
      valueColumn: '',
      operation: 'count',
      pipe: undefined
    };

    if (!this.currentFilterBasedConfig.graphs) {
      this.currentFilterBasedConfig.graphs = [];
    }

    this.currentFilterBasedConfig.graphs.push(newGraph);
  }

  public removeGraph(graphId: string): void {
    if (!this.currentFilterBasedConfig || !this.currentFilterBasedConfig.graphs) return;

    this.currentFilterBasedConfig.graphs = this.currentFilterBasedConfig.graphs.filter(g => g.id !== graphId);
  }

  public get getGraphTypes(): Array<{ label: string; value: GraphType }> {
    return [
      { label: 'Barras', value: 'bar' },
      { label: 'Barras (Horizontal)', value: 'bar-horizontal' },
      { label: 'Circular (Pie)', value: 'pie' },
      { label: 'Donut', value: 'dougnut' },
      { label: 'Líneas', value: 'line' },
      { label: 'Polar', value: 'polar' },
      { label: 'Radar', value: 'radar' },
      { label: 'Barras Apiladas', value: 'stacked-bar' },
      { label: 'Barras Comparativas', value: 'comparison-bar' }
    ];
  }

  //#endregion
}