import { Component, Input, Output, EventEmitter } from '@angular/core';
import { NgClass } from '@angular/common';
import { FilterBasedConfig } from '../../filter-based-view-config.component';

@Component({
  selector: 'app-filter-based-list-preview',
  standalone: true,
  imports: [
    NgClass
  ],
  templateUrl: './filter-based-list-preview.component.html',
  styleUrl: './filter-based-list-preview.component.css'
})
export class FilterBasedListPreviewComponent {
  @Input() filterBasedConfigs: FilterBasedConfig[] = [];
  @Input() currentFilterBasedConfig: FilterBasedConfig | null = null;

  @Output() edit = new EventEmitter<FilterBasedConfig>();
  @Output() remove = new EventEmitter<string>();
  @Output() generate = new EventEmitter<FilterBasedConfig>();
  @Output() add = new EventEmitter<void>();
  @Output() clone = new EventEmitter<FilterBasedConfig>();

  constructor() { }

  //#region Métodos de ayuda para templates

  hasGlobalFilters(config: FilterBasedConfig): boolean {
    const filters = config?.globalFilters;
    return filters ? Object.keys(filters).length > 0 : false;
  }

  //#endregion

  /**
   * Emite evento para editar una configuración
   */
  public onEdit(config: FilterBasedConfig): void {
    this.edit.emit(config);
  }

  /**
   * Emite evento para eliminar una configuración
   */
  public onRemove(configId: string): void {
    this.remove.emit(configId);
  }

  /**
   * Emite evento para generar/activar una configuración
   */
  public onGenerate(config: FilterBasedConfig): void {
    config.showInTable=!config.showInTable
    this.filterBasedConfigs.forEach( c => c.showInTable=false)
    this.generate.emit(config);
  }

  /**
   * Emite evento para agregar una nueva configuración
   */
  public onAdd(): void {
    this.add.emit();
  }

  /**
   * Emite evento para clonar una configuración
   */
  public onClone(config: FilterBasedConfig): void {
    this.clone.emit(config);
  }

  /**
   * Verifica si una configuración está activa actualmente
   */
  public isCurrentConfig(config: FilterBasedConfig): boolean {
    return this.currentFilterBasedConfig?.id === config.id;
  }

  /**
   * Obtiene descripción resumida de la configuración
   */
  public getConfigDescription(config: FilterBasedConfig): string {
    const rowsCount = config.rows.length;
    const columnsCount = config.columns.length;
    const metricsCount = config.columns.reduce((total, col) => total + col.metrics.length, 0);

    return `${rowsCount} fila(s) × ${columnsCount} columna(s) × ${metricsCount} métrica(s)`;
  }

  /**
   * Obtiene descripción de filtros de una fila
   */
  public getRowFiltersDescription(row: any): string {
    if (!row.filters || Object.keys(row.filters).length === 0) {
      return 'Sin filtros';
    }

    const filterCount = Object.keys(row.filters).length;
    const filterLabels = Object.keys(row.filters).slice(0, 2).map(key =>
      key.replace(/_/g, ' ').substring(0, 8)
    );

    if (filterCount <= 2) {
      return filterLabels.join(', ');
    } else {
      return `${filterLabels.join(', ')} +${filterCount - 2}`;
    }
  }

  /**
   * Obtiene descripción de métricas de una columna
   */
  public getMetricsDescription(column: any): string {
    if (!column.metrics || column.metrics.length === 0) {
      return 'Sin métricas';
    }

    const metricLabels = column.metrics.slice(0, 2).map((metric: any) =>
      metric.label || metric.calculation
    );

    if (column.metrics.length <= 2) {
      return metricLabels.join(', ');
    } else {
      return `${metricLabels.join(', ')} +${column.metrics.length - 2}`;
    }
  }
}