import { Injectable } from '@angular/core';
import { Table, Row, Cell, THeader } from '../interfaces/table';
import { TableGuardService } from '../guards/tabla-guard.service';

@Injectable({
  providedIn: 'root'
})
export class TableToGraphConverterService {

  constructor(private tableGuard: TableGuardService) { }

  /**
   * Convierte una tabla estructurada a datos planos para gráficas
   * @param table Tabla generada por CrossTabUtilsService
   * @returns Array de objetos planos con los datos de la tabla
   */
  convertTableToRawData(table: Table): any[] {
    if (!table || !table.body || table.body.length === 0) {
      return [];
    }

    const rawData: any[] = [];
    const headers = this.extractHeaders(table);

    // Procesar cada fila del body
    table.body.forEach(row => {
      const cells = this.tableGuard.getRowCells(row);
      const rowData: any = {};

      cells.forEach((cell, index) => {
        const headerName = headers[index] || `column_${index}`;
        rowData[headerName] = this.getCellValue(cell);
      });

      rawData.push(rowData);
    });

    return rawData;
  }

  /**
   * Extrae los nombres de columnas del header de la tabla
   * Importante: Solo el último row del header contiene los keys originales de los datos
   * Los primeros rows son labels o títulos de sección
   * @param table Tabla de la cual extraer headers
   * @returns Array de nombres de columnas (keys originales de los datos)
   */
  extractHeaders(table: Table): string[] {
    const headers: string[] = [];
    const rows = this.normalizeHeaderRows(table.header);
    if (rows.length === 0) return headers;

    const firstRow = rows[0];
    const lastRow = rows[rows.length - 1];

    const firstRowCells = this.tableGuard.getRowCells(firstRow);
    const lastRowCells = this.tableGuard.getRowCells(lastRow);

    const expandedFirst = this.expandCells(firstRowCells);
    const expandedLast = this.expandCells(lastRowCells);

    for (let i = 0; i < expandedLast.length; i++) {
      const cellValue = expandedLast[i];
      const upperCellValue = expandedFirst[i] || '';

      if (upperCellValue) {
        headers.push(`${cellValue} (${upperCellValue})`);
      } else {
        headers.push(cellValue);
      }
    }

    return headers;
  }

  /**
 * Expande las celdas considerando el colspan
 * Convierte cada celda en un array de strings donde:
 * - Si la celda tiene colspan: repite el texto 'colspan' veces
 * - Si es string o null: lo incluye directamente (null se convierte a '')
 * @param cells Celdas a expandir
 * @returns Array de strings con las celdas expandidas
 */
  private expandCells(cells: Cell[]): string[] {
    const expanded: string[] = [];

    for (const cell of cells) {
      if (typeof cell === 'string') {
        expanded.push(cell);
      } else if (cell === null) {
        expanded.push('');
      } else {
        // CellObject
        const text = cell.text ?? '';
        const colspan = cell.colspan ?? 1;

        for (let i = 0; i < colspan; i++) {
          expanded.push(text);
        }
      }
    }

    return expanded;
  }

  /**
   * Normaliza el header de la tabla a un array de rows
   * @param header El header de la tabla
   * @returns Array de rows
   */
  private normalizeHeaderRows(header: THeader): Row[] {
    if (this.tableGuard.isHeaderObject(header)) {
      return header.rows || [];
    } else if (Array.isArray(header)) {
      return header;
    }
    return [];
  }

  /**
   * Obtiene las columnas disponibles para seleccionar en gráficas
   * @param table Tabla de la cual extraer columnas
   * @returns Array de objetos con label y value para select
   */
  getAvailableColumns(table: Table): Array<{ label: string; value: string }> {
    const headers = this.extractHeaders(table);
    return headers.map(header => ({
      label: header.toUpperCase().replace(/_/g, ' '),
      value: header
    }));
  }

  /**
   * Obtiene solo las columnas numéricas disponibles
   * @param table Tabla de la cual extraer columnas numéricas
   * @returns Array de columnas que contienen datos numéricos
   */
  getNumericColumns(table: Table): Array<{ label: string; value: string }> {
    const allColumns = this.getAvailableColumns(table);
    const numericColumns: Array<{ label: string; value: string }> = [];

    // Muestrear algunas filas para determinar si una columna es numérica
    const sampleData = this.convertTableToRawData(table).slice(0, 5);

    allColumns.forEach(column => {
      const isNumeric = sampleData.some(row => {
        const value = row[column.value]?.replace('%', '')?.replaceAll(',','')?.replaceAll('$','')
        return value && !isNaN(Number(value));
      });

      if (isNumeric) {
        numericColumns.push(column);
      }
    });

    return numericColumns;
  }

  /**
   * Genera un título automático para la gráfica basado en las columnas seleccionadas
   * @param labelColumn Nombre de la columna de labels
   * @param valueColumn Nombre de la columna de valores
   * @returns Título generado automáticamente
   */
  generateGraphTitle(labelColumn: string, valueColumn?: string): string {
    const cleanLabel = labelColumn.replace(/_/g, ' ').toUpperCase();

    if (valueColumn) {
      const cleanValue = valueColumn.replace(/_/g, ' ').toUpperCase();
      return `${cleanLabel} X ${cleanValue}`;
    }

    return cleanLabel;
  }

  /**
   * Obtiene el valor de una celda como texto plano
   * @param cell Celda de la tabla
   * @returns Valor de la celda como texto
   */
  private getCellValue(cell: Cell | undefined): string {
    if (!cell) return '';
    if (this.tableGuard.isCellObject(cell)) {
      return cell.text || '';
    }
    return cell?.toString() || '';
  }

  /**
   * Convierte tabla a datos basados en columnas para gráficas de pastel/donut
   * Útil para casos como distribución porcentual de grupos de edad
   * @param table Tabla generada por CrossTabUtilsService
   * @param selectedColumns Columnas específicas a incluir
   * @param excludeColumns Columnas a excluir del cálculo
   * @param calculatePercentage Si debe calcular porcentajes automáticamente
   * @returns Array de objetos con datos para gráficas basadas en columnas
   */
  convertTableToColumnBasedData(
    table: Table,
    selectedColumns?: string[],
    excludeColumns?: string[],
    calculatePercentage: boolean = false
  ): any[] {
    if (!table || !table.body || table.body.length === 0) {
      return [];
    }

    const headers = this.extractHeaders(table);
    const rawData = this.convertTableToRawData(table);

    // Si hay una sola fila de datos (como en el caso de totales generales)
    if (rawData.length === 1) {
      const dataRow = rawData[0];
      const columnData: any[] = [];

      // Procesar cada columna
      headers.forEach(header => {
        // Verificar si debe incluirse esta columna
        if (selectedColumns && selectedColumns.length > 0) {
          if (!selectedColumns.includes(header)) return;
        }

        if (excludeColumns && excludeColumns.includes(header)) return;

        const value = dataRow[header];
        const numericValue = this.parseNumericValue(value);

        if (numericValue !== null) {
          columnData.push({
            label: this.cleanColumnLabel(header),
            value: numericValue,
            percentage: 0
          });
        }
      });

      // Calcular porcentajes si se solicita
      if (calculatePercentage && columnData.length > 0) {
        const total = columnData.reduce((sum, item) => sum + item.value, 0);
        columnData.forEach(item => {
          item.percentage = total > 0 ? (item.value / total) * 100 : 0;
        });
      }

      return columnData;
    }

    // Para múltiples filas, agregar por columna
    const columnAggregates: { [key: string]: number } = {};

    rawData.forEach(row => {
      headers.forEach(header => {
        // Verificar si debe incluirse esta columna
        if (selectedColumns && selectedColumns.length > 0) {
          if (!selectedColumns.includes(header)) return;
        }

        if (excludeColumns && excludeColumns.includes(header)) return;

        const value = this.parseNumericValue(row[header]);
        if (value !== null) {
          columnAggregates[header] = (columnAggregates[header] || 0) + value;
        }
      });
    });

    // Convertir a formato de array
    const columnData = Object.entries(columnAggregates).map(([header, value]) => ({
      label: this.cleanColumnLabel(header),
      value: value,
      percentage: 0
    }));

    // Calcular porcentajes si se solicita
    if (calculatePercentage && columnData.length > 0) {
      const total = columnData.reduce((sum, item) => sum + item.value, 0);
      columnData.forEach(item => {
        item.percentage = total > 0 ? (item.value / total) * 100 : 0;
      });
    }

    return columnData;
  }

  /**
   * Convierte un valor de celda a número
   * @param value Valor de la celda
   * @returns Valor numérico o null si no es numérico
   */
  private parseNumericValue(value: string): number | null {
    if (!value || value === '' || value === null) return null;

    // Limpiar el valor de caracteres no numéricos
    const cleanValue = value
      .toString()
      .replace('%', '')
      .replaceAll(',', '')
      .replaceAll('$', '')
      .trim();

    const parsed = parseFloat(cleanValue);
    return isNaN(parsed) ? null : parsed;
  }

  /**
   * Limpia y formatea el nombre de una columna para mostrarlo como etiqueta
   * @param columnName Nombre original de la columna
   * @returns Nombre limpio para etiqueta
   */
  private cleanColumnLabel(columnName: string): string {
    return columnName
      .replace(/\([^)]*\)/g, '') // Remover texto entre paréntesis
      .replace(/_/g, ' ') // Reemplazar guiones bajos con espacios
      .trim()
      .replace(/\s+/g, ' ') // Reducir múltiples espacios a uno
      .toUpperCase();
  }
}