import { Component, Input, Output, EventEmitter } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { TitleCasePipe } from '@angular/common';
import { TablaLocalService } from '../../../../../../services/tabla-local.service';
import { SelectFieldComponent } from '../../../../../../shared/generic-form/select-field/select-field.component';
import { SimpleFieldComponent } from '../../../../../../shared/generic-form/simple-field/simple-field.component';

export type MetricConfigCalculation = 'count' | 'sum' | 'average' | 'cross' | 'percent';

export interface MetricConfig {
  calculation: MetricConfigCalculation;
  valueField?: string;
  crossField?: string;
  label?: string;
  pipe?: 'currency' | 'number' | 'percent';
  minFractionDigits?: number;
  maxFractionDigits?: number;
  // Filtros específicos de la métrica aplicados antes del cálculo
  metricFilters?: Record<string, string>;
  // Base para cálculo de porcentajes (solo aplica para calculation === 'count')
  percentageBase?: 'filtered' | 'unfiltered'; // 'filtered': datos filtrados, 'unfiltered': datos originales
}

export interface ColumnConfig {
  name: string;
  dataType: 'string' | 'number' | 'date' | 'boolean';
}

export interface SelectItem {
  label: string;
  value: string;
}

@Component({
  selector: 'app-metrics-config',
  standalone: true,
  imports: [
    FormsModule,
    TitleCasePipe,
    SelectFieldComponent,
    SimpleFieldComponent
  ],
  templateUrl: './metrics-config.component.html',
  styleUrl: './metrics-config.component.css'
})
export class MetricsConfigComponent {
  @Input() metrics: MetricConfig[] = [];
  @Input() allColumns: ColumnConfig[] = [];

  @Output() metricsChange = new EventEmitter<MetricConfig[]>();

  constructor(private tablaLocalService: TablaLocalService) { }

  /**
   * Convierte las columnas disponibles en items para un componente SelectField
   */
  public columnsToSelectItem(type?: 'string' | 'number' | 'date' | 'boolean'): SelectItem[] {
    if (!type) {
      return this.allColumns.map(c => ({
        label: c.name.toUpperCase().replaceAll('_', ' '),
        value: c.name
      }));
    }
    return this.columnsByType(type).map(c => ({
      label: c.name.toUpperCase().replaceAll('_', ' '),
      value: c.name
    }));
  }

  /**
   * Agrega una nueva métrica
   */
  public addMetric(): void {
    const newMetric: MetricConfig = {
      calculation: 'count',
      label: 'Nueva métrica',
      percentageBase: 'filtered' // Default a datos filtrados
    };

    // Para métricas de cruce, no establecer etiqueta estática
    // para usar valores dinámicos del campo cruzado
    if (newMetric.calculation === 'cross') {
      newMetric.label = undefined;
    }

    const metricIndex = this.metrics.length;
    this.metrics.push(newMetric)
    this.initializeFilterVariables(metricIndex);
    this.expandMetric(metricIndex)
    this.emitChanges(this.metrics);
  }

  /**
   * Elimina una métrica por su índice
   */
  public removeMetric(index: number): void {
    const updatedMetrics = this.metrics.filter((_, i) => i !== index);
    this.emitChanges(updatedMetrics);
  }

  /**
   * Mueve una métrica hacia arriba en la lista
   */
  public moveMetricUp(index: number): void {
    if (index <= 0) return;

    const updatedMetrics = [...this.metrics];
    [updatedMetrics[index - 1], updatedMetrics[index]] = [updatedMetrics[index], updatedMetrics[index - 1]];
    this.emitChanges(updatedMetrics);
  }

  /**
   * Mueve una métrica hacia abajo en la lista
   */
  public moveMetricDown(index: number): void {
    if (index >= this.metrics.length - 1) return;

    const updatedMetrics = [...this.metrics];
    [updatedMetrics[index], updatedMetrics[index + 1]] = [updatedMetrics[index + 1], updatedMetrics[index]];
    this.emitChanges(updatedMetrics);
  }

  /**
   * Emite cambios cuando se modifica la lista de métricas
   */
  public emitChanges(metrics: MetricConfig[]): void {
    this.metricsChange.emit(metrics);
  }

  /**
   * Filtra columnas por tipo de dato
   */
  private columnsByType(type: 'string' | 'number' | 'date' | 'boolean') {
    return this.allColumns.filter(c => c.dataType === type);
  }

  // En tu componente TypeScript
  expandedMetrics: boolean[] = [];
  allExpanded = false;

  // Variables para manejar el estado de los inputs de filtros
  newFilterColumn: string[] = [];
  newFilterCondition: string[] = [];
  editingFilterKey: string[] = []; // Para edición de filtros existentes

  // Estructura para manejar expansión por métrica y filtro
  expandedFilters: { [metricIndex: number]: { [filterKey: string]: boolean } } = {};

  ngOnInit() {
    // Inicializar el estado expandido para cada métrica
    this.expandedMetrics = this.metrics.map(() => false);

    // Inicializar variables para filtros
    this.metrics.forEach((_, index) => {
      this.initializeFilterVariables(index);
    });
  }

  expandMetric(index: number) {
    this.expandedMetrics[index] = true;
  }

  collapseMetric(index: number) {
    this.expandedMetrics[index] = false;
  }

  toggleAllMetrics() {
    this.allExpanded = !this.allExpanded;
    this.expandedMetrics = this.metrics.map(() => this.allExpanded);
  }

  /**
   * Inicializa variables para una nueva métrica
   */
  private initializeFilterVariables(index: number): void {
    if (!this.newFilterColumn[index]) {
      this.newFilterColumn[index] = '';
    }
    if (!this.newFilterCondition[index]) {
      this.newFilterCondition[index] = '';
    }
    if (!this.editingFilterKey[index]) {
      this.editingFilterKey[index] = '';
    }
  }

  /**
   * Obtiene todas las claves de filtros aplicados a todas las métricas
   */
  getMetricFilterKeys(): string[] {
    const allKeys: string[] = [];
    this.metrics.forEach(metric => {
      if (metric.metricFilters) {
        allKeys.push(...Object.keys(metric.metricFilters));
      }
    });
    return [...new Set(allKeys)]; // Eliminar duplicados
  }

  getCalculationLabel(calculation: string): string {
    const labels: { [key: string]: string } = {
      'count': 'Conteo',
      'sum': 'Suma',
      'average': 'Promedio',
      'cross': 'Cruce',
      'percent': 'Porcentaje'
    };
    return labels[calculation] || calculation;
  }

  getFieldLabel(field: string): string {
    // Implementa según tu estructura de datos
    return field; // o la lógica para obtener un label legible
  }

  /**
   * Agrega un filtro a una métrica específica
   */
  addMetricFilter(metricIndex: number, column: string, condition: string): void {
    if (!column || !condition) return;

    const metric = this.metrics[metricIndex];
    if (!metric.metricFilters) {
      metric.metricFilters = {};
    }

    metric.metricFilters[column] = condition;
    this.emitChanges(this.metrics);

    // Reiniciar los inputs después de agregar el filtro
    this.resetFilterInputs(metricIndex);
  }

  /**
   * Elimina un filtro de una métrica específica
   */
  removeMetricFilter(metricIndex: number, column: string): void {
    const metric = this.metrics[metricIndex];
    if (metric.metricFilters && metric.metricFilters[column]) {
      delete metric.metricFilters[column];

      // Si no quedan filtros, eliminar el objeto
      if (Object.keys(metric.metricFilters).length === 0) {
        delete metric.metricFilters;
      }

      this.emitChanges(this.metrics);
    }
  }

  /**
   * Obtiene el resumen de filtros de una métrica para mostrar en tooltip
   */
  getMetricFiltersSummary(metric: MetricConfig): string {
    if (!metric.metricFilters || Object.keys(metric.metricFilters).length === 0) {
      return 'Sin filtros';
    }

    const summaries: string[] = [];
    Object.entries(metric.metricFilters).forEach(([column, condition]) => {
      summaries.push(`${column}: ${condition}`);
    });

    return summaries.join(' | ');
  }

  /**
   * Obtiene la cantidad de filtros aplicados a una métrica
   */
  getMetricFilterCount(metric: MetricConfig): number {
    return metric.metricFilters ? Object.keys(metric.metricFilters).length : 0;
  }

  /**
   * Formatea los filtros de una métrica para visualización
   */
  getFormattedMetricFilters(metric: MetricConfig): Array<{column: string, condition: string}> {
    if (!metric.metricFilters) return [];

    return Object.entries(metric.metricFilters).map(([column, condition]) => ({
      column,
      condition
    }));
  }

  /**
   * Expande/Contrae la sección de filtros de una métrica
   */
  expandedMetricFilters: boolean[] = [];

  toggleMetricFilters(index: number): void {
    this.expandedMetricFilters[index] = !this.expandedMetricFilters[index];
  }

  /**
   * Verifica si los filtros de una métrica están expandidos
   */
  isMetricFiltersExpanded(index: number): boolean {
    return this.expandedMetricFilters[index] || false;
  }

  /**
   * Alterna la expansión de un filtro específico
   */
  toggleFilterExpansion(metricIndex: number, filterKey: string): void {
    if (!this.expandedFilters[metricIndex]) {
      this.expandedFilters[metricIndex] = {};
    }
    this.expandedFilters[metricIndex][filterKey] = !this.expandedFilters[metricIndex][filterKey];
  }

  /**
   * Verifica si un filtro específico está expandido
   */
  isFilterExpanded(metricIndex: number, filterKey: string): boolean {
    return this.expandedFilters[metricIndex]?.[filterKey] || false;
  }

  /**
   * Prepara los filtros para una nueva métrica
   */
  private initializeMetricFilters(metric: MetricConfig): void {
    if (!metric.metricFilters) {
      metric.metricFilters = {};
    }
  }

  /**
   * Valida la sintaxis de un filtro
   */
  validateFilterSyntax(condition: string): boolean {
    if (!condition || !condition.trim()) return false;

    // Validaciones básicas de sintaxis
    const operators = this.tablaLocalService['operators'] as string[] || [];
    const hasValidOperator = operators.some((op: string) =>
      condition.includes(op)
    ) || !condition.match(/[<>=!]/);

    return hasValidOperator;
  }

  /**
   * Obtiene columnas disponibles para una métrica (excluye ya usadas)
   */
  getAvailableColumnsForMetric(metric: MetricConfig): string[] {
    const usedColumns = Object.keys(metric.metricFilters || {});
    return this.allColumns
      .map(col => col.name)
      .filter(col => !usedColumns.includes(col));
  }

  /**
   * Maneja cambios en el select de columna
   */
  onFilterColumnChange(metricIndex: number, value: string | number): void {
    this.newFilterColumn[metricIndex] = value.toString();
  }

  /**
   * Maneja cambios en el input de condición
   */
  onFilterConditionChange(metricIndex: number, value: string | number): void {
    this.newFilterCondition[metricIndex] = value.toString();
  }

  /**
   * Edita un filtro existente
   */
  editFilter(metricIndex: number, filterKey: string): void {
    const metric = this.metrics[metricIndex];
    this.editingFilterKey[metricIndex] = filterKey;
    this.newFilterColumn[metricIndex] = filterKey;
    this.newFilterCondition[metricIndex] = metric.metricFilters?.[filterKey] || '';
    this.toggleFilterExpansion(metricIndex, filterKey);
  }

  /**
   * Guarda cambios en un filtro editado
   */
  saveFilterEdit(metricIndex: number, originalFilterKey: string): void {
    const newColumn = this.newFilterColumn[metricIndex];
    const newCondition = this.newFilterCondition[metricIndex];

    if (!newColumn || !newCondition) return;

    const metric = this.metrics[metricIndex];

    // Si la columna cambió, eliminar la antigua
    if (originalFilterKey !== newColumn && metric.metricFilters?.[originalFilterKey]) {
      delete metric.metricFilters[originalFilterKey];
    }

    // Agregar/actualizar el filtro
    this.addMetricFilter(metricIndex, newColumn, newCondition);

    // Limpiar estado de edición
    this.editingFilterKey[metricIndex] = '';
    this.toggleFilterExpansion(metricIndex, originalFilterKey);
  }

  /**
   * Cancela edición de filtro
   */
  cancelFilterEdit(metricIndex: number, filterKey: string): void {
    this.editingFilterKey[metricIndex] = '';
    this.toggleFilterExpansion(metricIndex, filterKey);
  }

  /**
   * Reinicia los inputs de filtros para una métrica específica
   */
  private resetFilterInputs(metricIndex: number): void {
    this.newFilterColumn[metricIndex] = '';
    this.newFilterCondition[metricIndex] = '';
  }

  /**
   * Clona un filtro existente a los inputs de nuevo filtro
   */
  cloneFilter(metricIndex: number, column: string, condition: string): void {
    // Pegar los valores del filtro en los inputs de nuevo filtro
    this.newFilterColumn[metricIndex] = column;
    this.newFilterCondition[metricIndex] = condition;

    // Hacer scroll a la sección de agregar nuevo filtro para mejor UX
    setTimeout(() => {
      const addFilterSection = document.getElementById(`add-filter-section-${metricIndex}`);
      if (addFilterSection) {
        addFilterSection.scrollIntoView({ behavior: 'smooth', block: 'center' });
      }
    }, 100);
  }
}