import {
  Component,
  ElementRef,
  Input,
  OnChanges,
  OnDestroy,
  AfterViewInit,
  ViewChild,
  SimpleChanges,
} from '@angular/core';
import { Chart, ChartConfiguration, registerables, Title, SubTitle } from 'chart.js';

Chart.register(...registerables, Title, SubTitle);

Chart.defaults.font.size = 20;

@Component({
  selector: 'app-stacked-bar-chart',
  standalone: true,
  template: `<div class="chart-container"><canvas #chartCanvas></canvas></div>`,
  styles: [`
    .chart-container {
      position: relative;
      width: 100%;
      height: 100%;
    }
    canvas {
      width: 100% ;
      height: 100% ;
    }
  `]
})

export class StackedBarChartComponent implements AfterViewInit, OnChanges, OnDestroy {
  @ViewChild('chartCanvas') chartCanvas!: ElementRef<HTMLCanvasElement>;

  @Input() title: string = '';
  @Input() subtitle: string = '';
  @Input() labels: string[] = [];
  @Input() datasets: {
    label: string;
    data: number[];
    backgroundColor?: string;
  }[] = [];

  private chart: Chart | null = null;

  ngAfterViewInit(): void {
    this.createChart();
  }

  ngOnChanges(changes: SimpleChanges): void {
    if (this.chart && (changes['labels'] || changes['datasets'])) {
      this.updateChart();
    }
  }

  ngOnDestroy(): void {
    this.chart?.destroy();
  }

  private createChart() {
    if (!this.chartCanvas) return;

    const config: ChartConfiguration = {
      type: 'bar',
      data: {
        labels: this.labels,
        datasets: this.datasets,
      },
      options: {
        responsive: true,
        interaction: {
          mode: 'index',
          intersect: false,
        },
        scales: {
          x: {
            stacked: true,
            title: {
              display: true,
              text: 'Groups',
            },
          },
          y: {
            stacked: true,
            beginAtZero: true,
            title: {
              display: true,
              text: 'Value',
            },
          },
        },
        plugins: {
          legend: {
            position: 'top',
          },
          tooltip: {
            bodyFont: {
              size: 16
            },
            titleFont: {
              size: 16
            },
            footerFont: {
              size: 18
            },
            padding: 8
          },
          title: {
            display: !!this.title,
            text: this.title,
            font: { size: 25 },
            padding: { top: 10, bottom: 5 }
          },
          subtitle: {
            display: !!this.subtitle,
            text: this.subtitle,
            font: { size: 20 },
            color: '#6b7280',
            padding: { bottom: 10 }
          },
        },
        onClick: (event, elements, chart) => {
          const points = chart.getElementsAtEventForMode(event as unknown as Event, 'nearest', { intersect: true }, true);
          if (points.length) {
            const firstPoint = points[0];
            const datasetIndex = firstPoint.datasetIndex;
            const dataIndex = firstPoint.index;
            const datasetLabel = chart.data.datasets[datasetIndex].label;
            const label = chart.data.labels?.[dataIndex];
            const value = chart.data.datasets[datasetIndex].data[dataIndex];
            alert(`Clicked on:\nLabel: ${label}\nDataset: ${datasetLabel}\nValue: ${value}`);
          }
        },
      },
    };

    this.chart = new Chart(this.chartCanvas.nativeElement, config);
  }

  private updateChart() {
    if (!this.chart) return;

    this.chart.data.labels = this.labels;
    this.chart.data.datasets = this.datasets;
    this.chart.update();
  }
}
