import { Component, Input, SimpleChanges } from '@angular/core';
import { DougnutChartComponent } from "../../../../shared/statistics/dougnut-chart/dougnut-chart.component";
import { TimeChartComponent } from "../../../../shared/statistics/time-chart/time-chart.component";
import { PolarChartComponent } from "../../../../shared/statistics/polar-chart/polar-chart.component";
import { RadarChartComponent } from "../../../../shared/statistics/radar-chart/radar-chart.component";
import { ComparisonBarChartComponent } from "../../../../shared/statistics/comparison-bar-chart/comparison-bar-chart.component";
import { PieChartComponent } from '../../../../shared/statistics/pie-chart/pie-chart.component';
import { BarChartComponent } from '../../../../shared/statistics/bar-chart/bar-chart.component';
import { StackedBarChartComponent } from "../../../../shared/statistics/stacked-bar-chart/stacked-bar-chart.component";


export interface GenericGraphData {
  label: string;
  value: number;
  color?: string;
}

export interface GenericDataset {
  label: string;
  data: number[];
  backgroundColor?: string;
  borderColor?: string;
  borderWidth?: number;
  fill?: boolean;
}

export type GraphType = 'dougnut' | 'line' | 'polar' | 'radar' | 'pie' | 'comparison-bar' | 'bar' | 'bar-horizontal' | 'stacked-bar';


export interface GraphView {
  title: string;
  subtitle?: string;
  graphType: GraphType;
  currency?: boolean;
  data?: GenericDataset[];
  dataSet?: GenericDataset[];
}

@Component({
  selector: 'app-graphs-view',
  imports: [
    DougnutChartComponent,
    TimeChartComponent,
    PolarChartComponent,
    RadarChartComponent,
    ComparisonBarChartComponent,
    PieChartComponent,
    BarChartComponent,
    StackedBarChartComponent
  ],
  templateUrl: './graphs-view.component.html',
  styleUrl: './graphs-view.component.css'
})
export class GraphsViewComponent {
  @Input() title: string = ''
  @Input() subtitle: string = ''
  @Input() currentGraph: GraphType = 'dougnut'
  @Input() currency?: boolean = false
  @Input() data: GenericGraphData[] = []

  //variables para usar rawData
  @Input() rawData: any[] = []
  @Input() keyLabel: string = ''
  @Input() keyValue: string = ''
  @Input() operation: 'count' | 'sum' = 'count'

  @Input() labels: string[] = []
  @Input() dataSets: GenericDataset[] = []

  @Input() chartMaxValue?: number = 0;

  defaultChartMaxValue: number = 0;

  chartInterval: number = 0;

  ngOnChanges(changes: SimpleChanges) {
    if (changes['rawData']) {
      this.setData()
    }
  }

  private setData() {
    if (['radar', 'comparison-bar', 'stacked-bar'].includes(this.currentGraph)) {
      this.setDataSets()
    } else {
      this.setGenericData()
    }

    if (this.currentGraph.includes('bar')) {
      this.setDefaultMaxValue()
    }
  }

  private setGenericData() {
    if (!this.keyLabel) {
      throw new Error('Falta keyLabel para usar rawData');
    }
    this.labels = Array.from(new Set(this.rawData.map(r => r[this.keyLabel])))
    this.data = this.labels.map(label => {
      let value = this.valueWithOperation(label)
      return {
        label: label.toUpperCase(),
        value: value,
        color: ('#' + Math.floor(Math.random() * 16777215).toString(16))
      }
    })
  }

  private setDataSets() {

  }

  private valueWithOperation(label: string) {
    const dataFiltered = this.rawData.filter(r => r[this.keyLabel] == label)
    if (this.operation == 'count') {
      return dataFiltered.length
    }
    if (this.operation == 'sum' && this.keyValue) {
      return dataFiltered.reduce((acc, item) => acc + this.numericValue(item[this.keyValue]), 0)
    }
    return 0
  }

  numericValue(value: string | number | null | undefined) {
    if (!value) return 0;
    const parsed = Number(value.toString().replace('%', '').replaceAll(',', '').replaceAll('$', ''))
    if (isNaN(parsed)) {
      return 0;
    }

    return parsed;
  }

  setDefaultMaxValue() {
    let maxValue = 0;

    // Caso 1: Data en formato GenericGraphData[]
    if (this.data && this.data.length > 0) {
      maxValue = Math.max(...this.data.map(item => item.value || 0));
    }
    // Caso 2: DataSets en formato GenericDataset[]
    else if (this.dataSets && this.dataSets.length > 0) {
      this.dataSets.forEach(dataset => {
        if (dataset.data && dataset.data.length > 0) {
          const datasetMax = Math.max(...dataset.data.map(val => val || 0));
          if (datasetMax > maxValue) {
            maxValue = datasetMax;
          }
        }
      });
    }
    // Caso 3: RawData - procesar según la operación
    else if (this.rawData && this.rawData.length > 0 && this.keyLabel && this.keyValue) {
      const values: number[] = [];

      // Obtener valores únicos de las etiquetas
      const uniqueLabels = [...new Set(this.rawData.map(item => item[this.keyLabel]))];

      uniqueLabels.forEach(label => {
        const value = this.valueWithOperation(label as string);
        values.push(value);
      });

      if (values.length > 0) {
        maxValue = Math.max(...values);
      }
    }

    // Establecer valor por defecto con márgen
    this.defaultChartMaxValue = this.calculateChartMaxWithMargin(maxValue);
  }

  private calculateChartMaxWithMargin(maxValue: number): number {
    if (maxValue <= 0) return 100;

    // Calcular un margen del 15% para mejor visualización
    const margin = maxValue * 0.15;
    const valueWithMargin = maxValue + margin;

    // Redondear a un número "bonito" para el gráfico
    return this.roundToNiceNumber(valueWithMargin);
  }

  private roundToNiceNumber(value: number): number {
    const magnitude = Math.pow(10, Math.floor(Math.log10(value)));
    const normalized = value / magnitude;

    if (normalized <= 1) return magnitude;
    if (normalized <= 2) return 1.5 * magnitude;
    if (normalized <= 5) return 2.5 * magnitude;
    return 10 * magnitude;
  }
}
