import { Component, Input, OnChanges, SimpleChanges, inject } from '@angular/core';
import { CommonModule } from '@angular/common';
import { TableToGraphConverterService } from '../../services/table-to-graph-converter.service';
import { Table } from '../../interfaces/table';
import { GraphsViewComponent } from "../../graphs-view/graphs-view.component";
import { GraphConfig } from '../../types/graph.types';

@Component({
  selector: 'app-graph-preview',
  standalone: true,
  imports: [CommonModule, GraphsViewComponent],
  templateUrl: './graph-preview.component.html',
  styleUrl: './graph-preview.component.css'
})
export class GraphPreviewComponent implements OnChanges {
  @Input() graphConfig: GraphConfig | null = null;
  @Input() table: Table | null = null;

  rawData: any[] = [];

  private tableToGraphConverter = inject(TableToGraphConverterService);

  ngOnChanges(changes: SimpleChanges): void {
    if (changes['graphConfig'] || changes['table']) {
      this.updateGraphData();
    }
  }

  private updateGraphData(): void {
    if (!this.graphConfig || !this.table) {
      this.rawData = [];
      return;
    }

    // Verificar si es un gráfico basado en columnas
    if (this.graphConfig.dataSourceType === 'column-based') {
      // Usar el nuevo método para datos basados en columnas
      const columnData = this.tableToGraphConverter.convertTableToColumnBasedData(
        this.table,
        this.graphConfig.selectedColumns,
        this.graphConfig.excludeColumns,
        this.graphConfig.usePercentage
      );

      // Convertir al formato esperado por GraphsViewComponent
      this.rawData = columnData.map(item => ({
        label: item.label,
        value: item.value,
        percentage: item.percentage
      }));
    } else {
      // Mantener comportamiento original para row-based
      this.rawData = this.tableToGraphConverter.convertTableToRawData(this.table);
    }
  }


  isCurrencyPipe(){
    return this.graphConfig?.pipe ==='currency'
  }

  /**
   * Obtiene la clave para labels según el tipo de gráfica
   */
  getColumnBasedKeyLabel(): string {
    if (this.graphConfig?.dataSourceType === 'column-based') {
      return 'label';
    }
    return this.graphConfig?.labelColumn || '';
  }

  /**
   * Obtiene la clave para valores según el tipo de gráfica
   */
  getColumnBasedKeyValue(): string {
    if (this.graphConfig?.dataSourceType === 'column-based') {
      return 'value';
    }
    return this.graphConfig?.valueColumn || '';
  }
}