import { Component, Input, Output, EventEmitter } from '@angular/core';
import { FormsModule } from '@angular/forms';

export interface TotalesConfig {
  sum?: boolean;
  percent?: boolean;
}

@Component({
  selector: 'app-totals-config',
  standalone: true,
  imports: [
    FormsModule
  ],
  templateUrl: './totals-config.component.html',
  styleUrl: './totals-config.component.css'
})
export class TotalsConfigComponent {
  @Input() totales: TotalesConfig = {};
  @Output() totalesChange = new EventEmitter<TotalesConfig>();

  constructor() { }

  /**
   * Emite cambios cuando se modifica la configuración de totales
   */
  private emitChanges(): void {
    this.totalesChange.emit({ ...this.totales });
  }

  /**
   * Actualiza el valor de una propiedad específica de totales
   */
  public updateTotalProperty(property: keyof TotalesConfig, value: boolean): void {
    this.totales[property] = value;
    this.emitChanges();
  }
}