import {
  Component,
  Input,
  AfterViewInit,
  ViewChild,
  ElementRef,
  OnChanges,
  SimpleChanges,
} from '@angular/core';
import {
  Chart,
  PolarAreaController,
  RadialLinearScale,
  ArcElement,
  Tooltip,
  Legend,
  Title,
  SubTitle
} from 'chart.js';

Chart.register(PolarAreaController, RadialLinearScale, ArcElement, Tooltip, Legend, Title, SubTitle);

Chart.defaults.font.size = 20;

interface PolarChartDataItem {
  label: string;
  value: number;
  color?: string;
}

@Component({
  selector: 'app-polar-chart',
  standalone: true,
  templateUrl: './polar-chart.component.html',
  styles: [`
    .chart-container {
      position: relative;
      width: 100%;
      height: 100%;
    }
    canvas {
      width: 100% ;
      height: 100% ;
    }
  `]
})
export class PolarChartComponent implements AfterViewInit, OnChanges {
  @ViewChild('polarCanvas') polarCanvas!: ElementRef<HTMLCanvasElement>;

  @Input() title: string = '';
  @Input() subtitle: string = '';
  @Input() data: PolarChartDataItem[] = [];

  private chart!: Chart;

  ngAfterViewInit() {
    this.renderChart();
  }

  ngOnChanges(changes: SimpleChanges): void {
    if (this.chart) {
      this.updateChart();
    }
  }

  private renderChart() {
    const ctx = this.polarCanvas.nativeElement.getContext('2d');
    if (!ctx) return;

    this.chart = new Chart(ctx, {
      type: 'polarArea',
      data: {
        labels: this.data.map((d) => d.label),
        datasets: [
          {
            label: 'Polar Dataset',
            data: this.data.map((d) => d.value),
            backgroundColor: this.data.map((d) => d.color ?? '#60a5fa'),
          },
        ],
      },
      options: {
        responsive: true,
        plugins: {
          legend: {
            position: 'top',
          },
          tooltip: {
            bodyFont: {
              size: 16
            },
            titleFont: {
              size: 16
            },
            footerFont: {
              size: 18
            },
            padding: 8,
            callbacks: {
              label: (tooltipItem) => {
                const label = tooltipItem.label || '';
                const value = tooltipItem.raw as number;
                return `${label}: $${value.toLocaleString()}`;
              }
            }
          },
          title: {
            display: !!this.title,
            text: this.title,
            font: { size: 25 },
            padding: { top: 10, bottom: 5 }
          },
          subtitle: {
            display: !!this.subtitle,
            text: this.subtitle,
            font: { size: 20 },
            color: '#6b7280',
            padding: { bottom: 10 }
          }
        },
        onClick: (event, elements, chart) => {
          const points = chart.getElementsAtEventForMode(event as unknown as Event, 'nearest', { intersect: true }, true);
          if (points.length > 0) {
            const point = points[0];
            const label = chart.data.labels?.[point.index];
            const value = chart.data.datasets[point.datasetIndex].data[point.index];

            alert(`Clicked on:\nLabel: ${label}\nValue: ${value}`);
          }
        },
      },
    });
  }

  private updateChart() {
    this.chart.data.labels = this.data.map((d) => d.label);
    this.chart.data.datasets[0].data = this.data.map((d) => d.value);
    this.chart.data.datasets[0].backgroundColor = this.data.map(
      (d) => d.color ?? '#60a5fa'
    );
    this.chart.update();
  }
}
