import { ChangeDetectorRef, Component, EventEmitter, inject, Input, Output, ViewChild, } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { ControllerPrincipalesComponent } from './controller-principales/controller-principales.component';
import { ColumnSelectorComponent } from './column-selector/column-selector.component';
import { CrossTabConfig, CrossTabViewConfigComponent, MetricConfig } from './cross-tab-view-config/cross-tab-view-config.component';
import { FilterBasedConfig, FilterBasedViewConfigComponent } from './filter-based-view-config/filter-based-view-config.component';
import { FinalViewConfigComponent } from './final-view-config/final-view-config.component';
import { GeneradorExcelService } from '../../reportes/services/generador-excel.service';
import { CdkVirtualScrollViewport, ScrollingModule } from '@angular/cdk/scrolling';
import { ColumnIndexString } from './informe-tabla-dinamica-local-column-data';
import { NgClass, TitleCasePipe } from '@angular/common';
import { TablaLocalService } from '../../../services/tabla-local.service';

export interface ColumnStyle {
  thClass?: string;
  thWidth?: number;
  accordionClass?: string;
}

export interface ColumnConfig {
  name: string;
  cluster?: string;
  visible: boolean;
  dataType: 'string' | 'number' | 'date' | 'boolean';
}

export interface ColumnIndexGroup extends Omit<ColumnConfig, 'cluster' | 'dataType'> {
  name: string;
  visible: boolean;
  indices: ColumnConfig[];
  visibleColumns: string[];
  style?: ColumnStyle;
  indicesWidth?: Record<string, number>;
}

export interface FinalView {
  name: string;
  crossConfigs: string[]; // IDs de configuraciones cruzadas
  showInTable: boolean;
  visibleGraphs: string[]; // IDs de gráficas visibles
  displayMode: 'table' | 'graphs'; // Modo de visualización actual
}

export interface visibleColumn {
  name: string;
  width: number;
}

export type CurrentView = 'normal' | 'cross' | 'filter-based' | 'final';

@Component({
  selector: 'app-informe-tabla-dinamica-local',
  imports: [
    FormsModule,
    TitleCasePipe,
    ControllerPrincipalesComponent,
    ColumnSelectorComponent,
    CrossTabViewConfigComponent,
    FilterBasedViewConfigComponent,
    FinalViewConfigComponent,
    ScrollingModule,
    NgClass,
    FormsModule,
  ],
  templateUrl: './informe-tabla-dinamica-local.component.html',
  styleUrls: ['./informe-tabla-dinamica-local.component.css'],
})
export class InformeTablaDinamicaLocalComponent {
  @ViewChild(CdkVirtualScrollViewport) viewport!: CdkVirtualScrollViewport;

  @Input() title?: string
  @Input() data: any[] = [];
  @Input() itemSize: number = 50;
  @Input() fileName: string = 'informe_financiamiento';
  @Input() clusterColumns: ColumnIndexString[] = []
  @Input() useCheckBox = false
  @Input() tableHeight = 500

  //Virtual Pagination
  @Input() virtualChunkPaginate = 20;

  @Input() trackKey?: string
  paginatedNormalViewData: any[] = [];
  currentPage = 1;

  // Configuración
  allColumns: ColumnConfig[] = [];
  clusteredColumns: ColumnIndexGroup[] = [];
  visibleColumns: visibleColumn[] = [];

  @Input() showControllers = true

  // Vistas cruzadas
  private _crossTabConfigs: CrossTabConfig[] = []
  @Input()
  set crossTabConfigs(value: CrossTabConfig[]) {
    this._crossTabConfigs = value;
    this.crossTabConfigsChange.emit(value);
  }
  get crossTabConfigs(): CrossTabConfig[] {
    return this._crossTabConfigs;
  }

  currentCrossTab: CrossTabConfig | null = null;

  // Vistas basadas en filtros
  private _filterBasedConfigs: FilterBasedConfig[] = []
  @Input()
  set filterBasedConfigs(value: FilterBasedConfig[]) {
    this._filterBasedConfigs = value;
    this.filterBasedConfigsChange.emit(value);
  }
  get filterBasedConfigs(): FilterBasedConfig[] {
    return this._filterBasedConfigs;
  }

  currentFilterBasedConfig: FilterBasedConfig | null = null;

  private _finalViews: FinalView[] = [];
  @Input()
  set finalViews(value: FinalView[]) {
    this._finalViews = value;
    this.finalViewsChange.emit(value);
  }
  get finalViews(): FinalView[] {
    return this._finalViews;
  }
  currentFinalView: FinalView | null = null;

  // Estados del UI
  showColumnSelector = false;
  showCrossTabConfig = false;
  showFilterBasedConfig = false;
  showFinalViewConfig = false;
  private _currentView: CurrentView = 'normal';
  @Input()
  set currentView(value: CurrentView) {
    this._currentView = value;
    this.currentViewChange.emit(value);
  }
  get currentView(): CurrentView {
    return this._currentView;
  }

  // Datos
  normalViewData: any[] = [];
  filteredNormalViewData: any[] = [];

  viewPortWidth = 0

  private _filtradoMap: Record<string, string> = {}
  @Input()
  set filtradoMap(value: Record<string, string>) {
    this._filtradoMap = value;
    this.filtradoMapChange.emit(value);
  }
  get filtradoMap(): Record<string, string> {
    return this._filtradoMap;
  }

  selected: Record<number, boolean> = {}

  isAll = false

  @Output() selectedRows = new EventEmitter<any[]>();

  // Eventos output para two-way binding con componente padre
  @Output() crossTabConfigsChange = new EventEmitter<CrossTabConfig[]>();
  @Output() filterBasedConfigsChange = new EventEmitter<FilterBasedConfig[]>();
  @Output() finalViewsChange = new EventEmitter<FinalView[]>();
  @Output() filtradoMapChange = new EventEmitter<Record<string, string>>();
  @Output() currentViewChange = new EventEmitter<CurrentView>();
  @Output() showFilterBasedConfigChange = new EventEmitter<boolean>();

  public excel = inject(GeneradorExcelService)

  private tablaLocalUtils = inject(TablaLocalService)

  private changeDetector = inject(ChangeDetectorRef);

  public normalViewDataExcel() {
    const keys = (this.clusteredColumns.length ?
      this.clusteredColumns.flatMap(c => c.indices.filter(col => col.visible)) :
      this.visibleColumns).map(c => c.name);
    const data = this.filteredNormalViewData.map(row =>
      Object.fromEntries(keys.map(k => [k, row[k]]))
    );
    this.excel.exportToExcel(data, this.fileName);
  }

  public resetToNormalView() {
    this._currentView = 'normal';
    this.currentCrossTab = null;
    this.currentFinalView = null;
    this.currentViewChange.emit(this._currentView);
  }

  public setVisibleColumns(columns: visibleColumn[]) {
    this.visibleColumns = columns;
    this.viewPortWidth = columns.reduce((acc, c) => acc + c.width, 0)
    if (this.useCheckBox) {
      //width del checkbox
      this.viewPortWidth += 40
    }
  }

  public cleanSelected() {
    this.selected = {}
    this.selectedRows.emit([])
  }

  private dataFilteredDebounced = this.debounce(
    () => {
      this.setDataFiltered()
      this.resetSelected();
      this.resetPaginatedData(this.filteredNormalViewData);
      this.changeDetector.detectChanges();
    },
    800
  );

  public aplicarFiltrado() {
    if (this.filteredNormalViewData.length === this.normalViewData.length && Object.keys(this._filtradoMap).length === 0) {
      return;
    }
    this.dataFilteredDebounced();
  }

  private setDataFiltered() {
    const result = this.tablaLocalUtils.dataFiltered(this.normalViewData, this.filtradoMap);
    this.filteredNormalViewData = result;
  }

  setNormalViewData(data: any[]) {
    this.normalViewData = [...data]
    if (Object.values(this._filtradoMap).length) {
      this.setDataFiltered()
    }else{
      this.filteredNormalViewData= [...data]
    }

    this.resetSelected()
    this.resetPaginatedData(data)
    this.tablaLocalUtils.clearCache()
  }

  public limpiarFiltros() {
    this._filtradoMap = {}
    this.filtradoMapChange.emit(this._filtradoMap);
    this.filteredNormalViewData = [...this.normalViewData]
    this.resetSelected()
    this.resetPaginatedData(this.normalViewData)
  }

  public checkAll(value: boolean) {
    this.selected = {}
    if (value) {
      for (let i = 0; i < this.filteredNormalViewData.length; i++) {
        this.selected[i] = true
      }
      this.selectedRows.emit(this.filteredNormalViewData)
      return
    }
    this.selectedRows.emit([])
  }

  public onScrollIndexChanged(index: number) {
    // Verificar si estamos cerca del final
    const endIndex = index + Math.ceil(this.viewport.getViewportSize() / this.itemSize);

    if (endIndex >= this.paginatedNormalViewData.length - 5) {
      this.loadMoreData();
    }
  }

  public onRowSelected(i: number) {
    const value = this.selected[i]
    if (!value) {
      this.isAll = false
    }
    const keys = Object.keys(this.selected).filter((k) => this.selected[+k])
    this.selectedRows.emit(keys.map((key: string) => this.filteredNormalViewData[+key]))
  }

  public allColumnsChange(data: ColumnConfig[]) {
    this.allColumns = data
    this.changeDetector.detectChanges()
  }

  selectFromDiv(i: number) {
    this.selected[i] = !this.selected[i]
    this.onRowSelected(i)
  }

  private loadMoreData() {
    this.currentPage++
    this.paginatedNormalViewData.push(...this.filteredNormalViewData.slice(this.virtualChunkPaginate * (this.currentPage - 1), this.virtualChunkPaginate * this.currentPage))
  }

  private resetPaginatedData(data: any[]) {
    this.currentPage = 1
    this.paginatedNormalViewData = [...data.slice(0, this.virtualChunkPaginate)]
  }

  private resetSelected() {
    this.isAll = false
    this.selected = {}
    this.selectedRows.emit([])
  }

  // Métodos para manejar vistas filter-based
  public toggleShowFilterBasedConfig() {
    this.showFilterBasedConfig = !this.showFilterBasedConfig;
    this.showFilterBasedConfigChange.emit(this.showFilterBasedConfig);

    if (this.showFilterBasedConfig) {
      this.showCrossTabConfig = false;
      this.showFinalViewConfig = false;
      this.showColumnSelector = false;
    }
  }

  private debounce<T extends (...args: any[]) => any>(
    func: T,
    delay: number
  ): (...args: Parameters<T>) => void {
    let timeoutId: ReturnType<typeof setTimeout>;
    return function (this: any, ...args: Parameters<T>) {
      clearTimeout(timeoutId);
      timeoutId = setTimeout(() => func.apply(this, args), delay);
    };
  }

  ngOnDestroy() {
    this.limpiarFiltros()
  }
}
