import { Component, Input, Output, EventEmitter } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { FilterBasedRow } from '../../filter-based-view-config.component';
import { SimpleFieldComponent } from '../../../../../../shared/generic-form/simple-field/simple-field.component';
import { SelectFieldComponent } from '../../../../../../shared/generic-form/select-field/select-field.component';

export interface RowColumnConfig {
  name: string;
  dataType: 'string' | 'number' | 'date' | 'boolean';
}

export interface RowSelectItem {
  label: string;
  value: string;
}

@Component({
  selector: 'app-filter-based-row-config',
  standalone: true,
  imports: [
    FormsModule,
    SimpleFieldComponent,
    SelectFieldComponent
  ],
  templateUrl: './filter-based-row-config.component.html',
  styleUrl: './filter-based-row-config.component.css'
})
export class FilterBasedRowConfigComponent {
  @Input() row: FilterBasedRow | null = null;
  @Input() allColumns: RowColumnConfig[] = [];

  @Output() rowChange = new EventEmitter<FilterBasedRow | null>();

  newFilterColumn: string = '';
  newFilterCondition: string = '';

  constructor() { }

  /**
   * Obtiene la etiqueta de la fila de forma segura
   */
  getRowLabel(): string {
    return this.row?.label || '';
  }

  /**
   * Convierte las columnas disponibles en items para un componente SelectField
   */
  public columnsToSelectItem(): RowSelectItem[] {
    return this.allColumns.map(c => ({
      label: c.name.toUpperCase().replaceAll('_', ' '),
      value: c.name
    }));
  }

  /**
   * Actualiza la etiqueta de la fila
   */
  onLabelChange(label: string | number): void {
    if (this.row) {
      this.row.label = label.toString();
      this.emitChanges();
    }
  }

  /**
   * Actualiza un filtro específico
   */
  onFilterChange(column: string, condition: string | number): void {
    if (this.row) {
      if (condition.toString().trim()) {
        this.row.filters[column] = condition.toString();
      } else {
        delete this.row.filters[column];
      }
      this.emitChanges();
    }
  }

  /**
   * Obtiene el valor actual de un filtro
   */
  getFilterValue(column: string): string {
    return this.row?.filters?.[column]?.toString() || '';
  }

  /**
   * Agrega un nuevo filtro a la fila
   */
  addFilter(): void {
    if (this.row && this.newFilterColumn && this.newFilterCondition.trim()) {
      this.row.filters[this.newFilterColumn] = this.newFilterCondition;
      this.newFilterColumn = '';
      this.newFilterCondition = '';
      this.emitChanges();
    }
  }

  /**
   * Elimina un filtro de la fila
   */
  removeFilter(column: string): void {
    if (this.row?.filters) {
      delete this.row.filters[column];
      this.emitChanges();
    }
  }

  /**
   * Emite cambios al componente padre
   */
  private emitChanges(): void {
    this.rowChange.emit(this.row);
  }

  /**
   * Obtiene los filtros como un array para iteración
   */
  getFiltersArray(): Array<{ column: string, condition: string }> {
    if (!this.row?.filters) return [];

    return Object.entries(this.row.filters).map(([column, condition]) => ({
      column,
      condition
    }));
  }

  /**
   * Formatea el nombre de una columna para mostrar
   */
  formatColumnName(columnName: string): string {
    return columnName.replace(/_/g, ' ').toUpperCase();
  }
}