import { CurrencyPipe } from '@angular/common';
import {
  Component,
  Input,
  OnChanges,
  SimpleChanges,
  AfterViewInit,
  ViewChild,
  ElementRef,
  inject
} from '@angular/core';

import {
  Chart,
  ChartConfiguration,
  BarController,
  BarElement,
  CategoryScale,
  LinearScale,
  Tooltip,
  Legend,
  Title,
  SubTitle
} from 'chart.js';

Chart.register(BarController, BarElement, CategoryScale, LinearScale, Tooltip, Legend, Title, SubTitle);

Chart.defaults.font.size = 20;

interface BarChartDataItem {
  label: string;
  value: number;
  color?: string;
}

@Component({
    selector: 'app-bar-chart',
    imports: [],
    templateUrl: './bar-chart.component.html',
    styles: [`
    .chart-container {
      position: relative;
      width: 100%;
      height: 100%;
    }
    canvas {
      width: 100%;
      height: 100%;
    }
  `]
})
export class BarChartComponent implements OnChanges, AfterViewInit {
  @ViewChild('barCanvas') barCanvas!: ElementRef<HTMLCanvasElement>;

  @Input() title: string = '';
  @Input() subtitle: string = '';
  @Input() data: BarChartDataItem[] = [];
  @Input() maxValue = 100;
  @Input() interval = 10;
  @Input() orientation: 'horizontal' | 'vertical' = 'vertical';
  @Input() isCurrency=false
  @Input() currencySymbol: string = '$';

  private chart: Chart | undefined;
  private isViewInitialized = false;

  ngAfterViewInit(): void {
    this.isViewInitialized = true;
    if (this.data?.length > 0) {
      this.renderChart();
    }
  }

  ngOnChanges(changes: SimpleChanges): void {
    if (this.chart && changes['data']) {
      this.updateChart();
    } else if (this.isViewInitialized && this.data?.length > 0) {
      this.renderChart();
    }
  }

  private destroyChart() {
    if (this.chart) {
      this.chart.destroy();
      this.chart = undefined;
    }
  }

  private renderChart() {
    if (!this.barCanvas || !this.barCanvas.nativeElement || !this.data?.length) return;

    this.destroyChart(); // Ensure we don't double-initialize

    const ctx = this.barCanvas.nativeElement.getContext('2d');
    if (!ctx) return;

    const indexAxis = this.orientation === 'horizontal' ? 'y' : 'x';

    this.chart = new Chart(ctx, {
      type: 'bar',
      data: {
        labels: this.data.map(d => d.label),
        datasets: [{
          data: this.data.map(d => d.value),
          backgroundColor: this.data.map(d => d.color ?? '#6A1C32'),
          label: 'Total'
        }]
      },
      options: {
        responsive: true,
        indexAxis,
        plugins: {
          legend: { display: false },
          title: {
            display: !!this.title,
            text: this.title,
            font: { size: 25 },
            padding: { top: 10, bottom: 5 }
          },
          subtitle: {
            display: !!this.subtitle,
            text: this.subtitle,
            font: { size: 20 },
            color: '#6b7280',
            padding: { bottom: 10 }
          },
          tooltip: {
            bodyFont: { size: 16 },
            titleFont: { size: 16 },
            footerFont: { size: 18 },
            padding: 8,
            callbacks: {
              label: (context) => {
                const value = this.orientation==='horizontal' ? context.parsed.x : (context.parsed.y?? context.parsed.x);
                return this.isCurrency ? this.formatCurrency(value) : value.toString();
              }
            }
          }
        },
        scales: {
          [indexAxis === 'y' ? 'x' : 'y']: {
            beginAtZero: true,
            max: this.maxValue,
            ticks: {
              stepSize: this.interval,
              callback: (value: string | number) => {
                return this.isCurrency ? this.formatCurrency(value) : value.toString();
              }
            }
          }
        }
      }
    });
  }

  private updateChart() {
    if (!this.chart) return;

    const indexAxis = this.orientation === 'horizontal' ? 'y' : 'x';

    this.chart.data.labels = this.data.map(d => d.label);
    this.chart.data.datasets[0].data = this.data.map(d => d.value);
    this.chart.data.datasets[0].backgroundColor = this.data.map(d => d.color ?? '#6A1C32');

    this.chart.options.indexAxis = indexAxis;
    this.chart.options.scales = {
      [indexAxis === 'y' ? 'x' : 'y']: {
        beginAtZero: true,
        max: this.maxValue,
        ticks: {
          stepSize: this.interval,
          callback: (value: string | number) => {
            return value.toString();
          }
        }
      }
    };
    this.chart.update();
  }

    /**
 * Formatea un número como moneda con opciones configurables
 * @param value Valor numérico a formatear
 * @param options Opciones de formato (opcional)
 * @returns Cadena formateada como moneda
 * 
 * Ejemplos:
 * formatCurrency(1234567.89) → "$1,234,567.89"
 * formatCurrency(1234567.89, { currency: 'EUR', locale: 'de-DE' }) → "1.234.567,89 €"
 */
  formatCurrency(
    value: number | string,
    options: {
      currency?: string;
      locale?: string;
      minimumFractionDigits?: number;
      maximumFractionDigits?: number;
    } = {}
  ): string {
    // Configuración por defecto (USD)
    const {
      currency = 'USD',
      locale = 'en-US',
      minimumFractionDigits = 2,
      maximumFractionDigits = 2
    } = options;

    // Convertir a número si es string
    const numericValue = typeof value === 'string' ? parseFloat(value) : value;

    // Validar que sea un número válido
    if (isNaN(numericValue)) {
      console.warn('Valor no numérico proporcionado a formatCurrency');
      return 'NaN';
    }

    // Formatear como moneda
    return new Intl.NumberFormat(locale, {
      style: 'currency',
      currency,
      minimumFractionDigits,
      maximumFractionDigits
    }).format(numericValue);
  }
}
