import { Injectable } from '@angular/core';
import { Cell, CellObject, FooterObject, HeaderObject, Table, Row, RowObject, TFoot, THeader, TBody } from '../interfaces/table';

@Injectable({
    providedIn: 'root'
})
export class TableGuardService {

    // Cell guards
    isCellObject(cell: Cell): cell is CellObject {
        if (cell === undefined) {
            console.error('🚨 TablaGuardService: Se encontró una celda undefined. Esto no debería pasar.', {
                cell,
                stack: new Error().stack
            });
            throw new Error('Se encontró una celda undefined. Esto indica un error en la generación de la tabla.');
        }

        return (
            typeof cell !== 'string' &&
            cell !== null &&
            'text' in cell &&
            (typeof cell.text === 'string' || cell.text === null) &&
            (cell.colspan === undefined || typeof cell.colspan === 'number') &&
            (cell.style === undefined || typeof cell.style === 'string')
        );
    }

    isSimpleCell(cell: Cell): cell is string | null {
        return typeof cell === 'string' || cell === null;
    }

    // Row guards
    isRowArray(row: Row): row is Cell[] {
        return Array.isArray(row);
    }

    isRowObject(row: Row): row is RowObject {
        return (
            !Array.isArray(row) &&
            'cells' in row &&
            Array.isArray(row.cells) &&
            (row.style === undefined || typeof row.style === 'string')
        );
    }

    // Header guards
    isHeaderArray(header: THeader): header is Row[] {
        return Array.isArray(header);
    }

    isHeaderObject(header: THeader): header is HeaderObject {
        return (
            !Array.isArray(header) &&
            'rows' in header &&
            Array.isArray(header.rows) &&
            (header.style === undefined || typeof header.style === 'string')
        );
    }

    // Footer guards
    isFooterArray(footer: TFoot): footer is Row[] {
        return Array.isArray(footer);
    }

    isFooterObject(footer: TFoot): footer is FooterObject {
        return (
            !Array.isArray(footer) &&
            'rows' in footer &&
            Array.isArray(footer.rows) &&
            (footer.style === undefined || typeof footer.style === 'string')
        );
    }

    // Table guard
    isValidTable(table: any): table is Table {
        return (
            table &&
            'header' in table &&
            'body' in table &&
            (this.isHeaderArray(table.header) || this.isHeaderObject(table.header)) &&
            (Array.isArray(table.body) || typeof table.body === 'string') &&
            (table.footer === undefined ||
                this.isFooterArray(table.footer) ||
                this.isFooterObject(table.footer))
        );
    }

    // Validar TBody específicamente
    isValidTBody(body: any): body is TBody {
        return Array.isArray(body) || typeof body === 'string';
    }

    // Validar que todos los elementos de un array sean Rows válidos
    isValidRows(rows: any[]): rows is Row[] {
        return rows.every(row => this.isRowArray(row) || this.isRowObject(row));
    }

    // Validar que un Row sea válido
    isValidRow(row: any): row is Row {
        return this.isRowArray(row) || this.isRowObject(row);
    }

    // Validar Cell
    isValidCell(cell: any): cell is Cell {
        return this.isCellObject(cell) || this.isSimpleCell(cell);
    }

    // Validar que todos los elementos de un array sean Cells válidos
    isValidCells(cells: any[]): cells is Cell[] {
        return cells.every(cell => this.isValidCell(cell));
    }

    // Métodos auxiliares para extraer datos de celdas
    getCellText(cell: Cell): string {
        if (this.isCellObject(cell)) {
            // Mostrar "0" si es string "0", solo ocultar null/undefined/empty string
            return cell.text === '0' ? "0" : (cell.text ?? '');
        }
        // Mostrar "0" si es string "0", solo ocultar null/undefined/empty string
        return cell === '0' ? "0" : (cell ?? '');
    }

    getCellStyle(cell: Cell): string {
        if (this.isCellObject(cell)) {
            return cell.style || '';
        }
        return '';
    }

    getCellColspan(cell: Cell): number {
        if (this.isCellObject(cell)) {
            return cell.colspan || 1;
        }
        return 1;
    }

    // Métodos auxiliares para filas
    getRowCells(row: Row): Cell[] {
        if (this.isRowArray(row)) {
            return row;
        }
        if (this.isRowObject(row)) {
            return row.cells;
        }
        return [];
    }

    getRowStyle(row: Row): string {
        if (this.isRowObject(row)) {
            return row.style || '';
        }
        return '';
    }

    // Métodos auxiliares para headers
    getHeaderRows(header: THeader): Row[] {
        if (this.isHeaderArray(header)) {
            return header;
        }
        if (this.isHeaderObject(header)) {
            return header.rows;
        }
        return [];
    }

    getHeaderStyle(header: THeader): string {
        if (this.isHeaderObject(header)) {
            return header.style || '';
        }
        return '';
    }

    // Métodos auxiliares para footer
    getFooterRows(footer: TFoot): Row[] {
        if (this.isFooterArray(footer)) {
            return footer;
        }
        if (this.isFooterObject(footer)) {
            return footer.rows;
        }
        return [];
    }

    getFooterStyle(footer: TFoot): string {
        if (this.isFooterObject(footer)) {
            return footer.style || '';
        }
        return '';
    }

    // Métodos auxiliares para body
    getBodyRows(body: TBody): Row[] {
        if (this.isValidRows(body)) {
            return body;
        }

        return body
    }

    getBodyString(body: TBody): string {
        return typeof body === 'string' ? body : '';
    }

    hasFooter(table: Table): boolean {
        return table.footer !== undefined && table.footer !== null;
    }

    hasBody(table: Table): boolean {
        return table.body !== undefined && table.body !== null;
    }

    /**
     * Valida que toda la estructura de la tabla esté correcta y no tenga undefineds
     * Lanza errores descriptivos si encuentra problemas
     */
    validateTableStructure(table: Table): void {
        if (!table) {
            throw new Error('La tabla es null o undefined');
        }

        // Validar header
        if (table.header) {
            this.validateHeader(table.header, 'header');
        }

        // Validar body
        if (table.body) {
            this.validateBody(table.body, 'body');
        }

        // Validar footer
        if (table.footer) {
            this.validateFooter(table.footer, 'footer');
        }
    }

    private validateHeader(header: THeader, context: string): void {
        try {
            const rows = this.getHeaderRows(header);
            rows.forEach((row, rowIndex) => {
                this.validateRow(row, `${context}[rowIndex:${rowIndex}]`);
            });
        } catch (error) {
            console.error(`🚨 Error validando ${context}:`, error);
            throw error;
        }
    }

    private validateBody(body: TBody, context: string): void {
        if (!Array.isArray(body)) {
            throw new Error(`${context} no es un array válido`);
        }

        body.forEach((row, rowIndex) => {
            this.validateRow(row, `${context}[rowIndex:${rowIndex}]`);
        });
    }

    private validateFooter(footer: TFoot, context: string): void {
        try {
            const rows = this.getFooterRows(footer);
            rows.forEach((row, rowIndex) => {
                this.validateRow(row, `${context}[rowIndex:${rowIndex}]`);
            });
        } catch (error) {
            console.error(`🚨 Error validando ${context}:`, error);
            throw error;
        }
    }

    private validateRow(row: Row, context: string): void {
        try {
            const cells = this.getRowCells(row);
            cells.forEach((cell, cellIndex) => {
                this.validateCell(cell, `${context}[cellIndex:${cellIndex}]`);
            });
        } catch (error) {
            console.error(`🚨 Error validando fila en ${context}:`, error);
            throw error;
        }
    }

    private validateCell(cell: Cell, context: string): void {
        if (cell === undefined) {
            console.error(`🚨 CELDA UNDEFINED ENCONTRADA en ${context}:`, {
                cell,
                context,
                type: typeof cell
            });
            throw new Error(`Celda undefined encontrada en ${context}. Esto indica un error en la generación de datos.`);
        }

        if (this.isCellObject(cell)) {
            if (cell.text === undefined) {
                console.error(`🚨 CellObject con text undefined en ${context}:`, cell);
                throw new Error(`CellObject con text undefined en ${context}`);
            }
        }
    }
}