import { Component, EventEmitter, Input, Output } from '@angular/core';
import { ColumnConfig, FinalView, CurrentView } from '../informe-tabla-dinamica-local.component';
import { FormularioFlotanteComponent } from "../../../../shared/formulario-flotante/formulario-flotante.component";
import { CrossTabConfig } from '../cross-tab-view-config/cross-tab-view-config.component';
import { TablaDinamicaGuiaComponent } from "../tabla-dinamica-guia/tabla-dinamica-guia.component";


/**
 * Componente controlador principal para la gestión de vistas de tablas dinámicas.
 *
 * Este componente se encarga de:
 * - Manejar la visualización de selectores y configuradores
 * - Crear nuevas configuraciones de vistas cruzadas
 * - Crear nuevas vistas finales
 * - Emitir eventos para la comunicación con el componente padre
 *
 * @example
 * <app-controller-principales
 *   [allColumns]="columns"
 *   [crossTabConfigs]="configs"
 *   (currentCrossTabChange)="onCrossTabChange($event)">
 * </app-controller-principales>
 */
@Component({
  selector: 'app-controller-principales',
  imports: [FormularioFlotanteComponent, TablaDinamicaGuiaComponent],
  templateUrl: './controller-principales.component.html',
  styleUrls: ['./controller-principales.component.css']
})
export class ControllerPrincipalesComponent {
  //#region Input Properties

  /**
   * Lista de todas las columnas disponibles con su configuración
   */
  @Input() allColumns: ColumnConfig[] = [];

  /**
   * Indica si el selector de columnas debe mostrarse
   */
  @Input() showColumnSelector = false;

  /**
   * Vista actualmente activa (normal, cross o final)
   */
  @Input() currentView: CurrentView = 'normal';


  //#endregion

  //#region Output Events
  /**
   * Evento emitido cuando cambia la visibilidad del selector de columnas
   */
  @Output() showColumnSelectorChange = new EventEmitter<boolean>();


  @Output() currentViewChange = new EventEmitter<CurrentView>();

  @Output() limpiarFiltros = new EventEmitter<void>()

  /**
   * Evento emitido para solicitar un reset de la vista
   */
  @Output() reset = new EventEmitter<void>();

  @Input() showAyudaNormal = false

  //#endregion

  //#region Public Methods

  /**
   * Crea una nueva configuración de vista cruzada con valores por defecto
   * y la establece como la configuración actual.
   * 
   * @example
   * component.addCrossTabConfig();
   * // Crea una nueva configuración con las primeras dos columnas como dimensiones
   */
  public toggleShowCrossTabConfig(): void {
    this.currentView='cross'
    this.currentViewChange.emit('cross')
  }

  /**
   * Abre el configurador de vistas basadas en filtros
   */
  public toggleShowFilterBasedConfig(): void {
    this.currentView = 'filter-based'
    this.currentViewChange.emit('filter-based')
  }

  /**
   * Crea una nueva vista final con valores por defecto
   * y la establece como la vista actual.
   *
   * @example
   * component.createFinalView();
   * // Crea una nueva vista final que incluye todas las configuraciones visibles
   */
  public createFinalView(): void {
    this.currentView = 'final'
    this.currentViewChange.emit('final')
  }

  //#endregion
}