import { Component, Input, Output, EventEmitter, inject } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { GraphPreviewComponent } from '../../../shared/graph-preview/graph-preview.component';
import { GraphConfig, ColumnOption } from '../../../types/graph.types';

// Interfaces simples para no depender de archivos externos
export interface Table {
  header: any;
  body: any;
  footer?: any;
}

@Component({
  selector: 'app-graphs-config',
  standalone: true,
  imports: [
    FormsModule,
    GraphPreviewComponent,
],
  templateUrl: './graphs-config.component.html',
  styleUrl: './graphs-config.component.css'
})
export class GraphsConfigComponent {
  @Input() graphs: GraphConfig[] = [];
  @Input() availableColumns: ColumnOption[] = [];
  @Input() numericColumns: ColumnOption[] = [];
  @Input() table: Table | null = null;

  @Output() graphsChange = new EventEmitter<GraphConfig[]>();
  @Output() graphPreview = new EventEmitter<{ graph: GraphConfig; show: boolean }>();

  public currentGraph?: GraphConfig;
  public showGraphConfig = false;
  public showGraphPreview: boolean = false;

  // Variables para manejar selección de columnas múltiples
  public selectedColumnsState: { [key: string]: boolean } = {};
  public excludeColumnsState: { [key: string]: boolean } = {};

  /**
   * Obtiene los tipos de gráficas disponibles
   */
  public getGraphTypes(): Array<{ label: string; value: GraphConfig['graphType'] }> {
    return [
      { label: 'Barras', value: 'bar' },
      { label: 'Barras (Horizontal)', value: 'bar-horizontal' },
      { label: 'Circular (Pie)', value: 'pie' },
      { label: 'Donut', value: 'dougnut' },
      { label: 'Líneas', value: 'line' },
      { label: 'Polar', value: 'polar' },
      { label: 'Radar', value: 'radar' },
      { label: 'Barras Apiladas', value: 'stacked-bar' },
      { label: 'Barras Comparativas', value: 'comparison-bar' }
    ];
  }

  /**
   * Agrega una nueva gráfica
   */
  public addGraph(): void {
    const newGraph: GraphConfig = {
      id: 'graph-' + new Date().toISOString(),
      title: '',
      graphType: 'bar',
      labelColumn: '',
      valueColumn: '',
      operation: 'count',
      pipe: undefined,
      dataSourceType: 'row-based', // Valor por defecto para compatibilidad
      selectedColumns: [],
      excludeColumns: [],
      usePercentage: false
    };

    const updatedGraphs = [...this.graphs, newGraph];
    this.emitChanges(updatedGraphs);
    this.editGraph(newGraph);
  }

  /**
   * Edita una gráfica existente
   */
  public editGraph(graph: GraphConfig): void {
    this.currentGraph = graph;
    this.showGraphPreview = false;
    this.showGraphConfig=true;

    // Inicializar estados para columnas seleccionadas y excluidas
    this.initializeColumnStates();
  }

  /**
   * Elimina una gráfica
   */
  public removeGraph(graphId: string): void {
    const updatedGraphs = this.graphs.filter(g => g.id !== graphId);
    this.emitChanges(updatedGraphs);

    if (this.currentGraph?.id === graphId) {
      this.currentGraph = undefined;
      this.showGraphConfig=false
      this.showGraphPreview = false;
    }
  }

  /**
   * Previsualiza la gráfica actual
   */
  public previewGraph(graph?:GraphConfig): void {
    if(graph){
      this.currentGraph= graph
    }
    if (!this.currentGraph || !this.table) return;

    // Generar título automático si está vacío
    if (!this.currentGraph.title) {
      this.currentGraph.title = `${this.currentGraph.labelColumn} X ${this.currentGraph.valueColumn}`;
    }

    this.showGraphPreview = true;
    this.graphPreview.emit({ graph: this.currentGraph, show: true });
  }

  /**
   * Cierra la previsualización de la gráfica
   */
  public closeGraphPreview(): void {
    this.showGraphPreview = false;
    if (this.currentGraph) {
      this.graphPreview.emit({ graph: this.currentGraph, show: false });
    }
  }

  /**
   * Determina si el pipe seleccionado es de tipo currency
   */
  public isCurrencyPipe(pipe?: string): boolean {
    return pipe === 'currency';
  }

  
  /**
   * Emite cambios cuando se modifica la lista de gráficas
   */
  private emitChanges(graphs: GraphConfig[]): void {
    this.graphsChange.emit(graphs);
  }

  /**
   * Inicializa los estados de las columnas basados en la configuración actual
   */
  private initializeColumnStates(): void {
    if (!this.currentGraph) return;

    // Reiniciar estados
    this.selectedColumnsState = {};
    this.excludeColumnsState = {};

    // Establecer estados basados en la configuración guardada
    if (this.currentGraph.selectedColumns) {
      this.currentGraph.selectedColumns.forEach(col => {
        this.selectedColumnsState[col] = true;
      });
    }

    if (this.currentGraph.excludeColumns) {
      this.currentGraph.excludeColumns.forEach(col => {
        this.excludeColumnsState[col] = true;
      });
    }
  }

  /**
   * Maneja cambios en el tipo de fuente de datos
   */
  onDataSourceTypeChange(): void {
    if (this.currentGraph) {
      // Limpiar estados cuando cambia el tipo
      if (this.currentGraph.dataSourceType === 'row-based') {
        this.selectedColumnsState = {};
        this.excludeColumnsState = {};
        this.currentGraph.selectedColumns = [];
        this.currentGraph.excludeColumns = [];
      } else {
        // Inicializar estados para column-based
        this.initializeColumnStates();
      }
    }
  }

  /**
   * Maneja cambios en las columnas seleccionadas
   */
  onSelectedColumnsChange(): void {
    if (this.currentGraph) {
      // Convertir estados booleanos a array de valores seleccionados
      this.currentGraph.selectedColumns = Object.keys(this.selectedColumnsState).filter(key => this.selectedColumnsState[key]);
    }
  }

  /**
   * Maneja cambios en las columnas excluidas
   */
  onExcludeColumnsChange(): void {
    if (this.currentGraph) {
      // Convertir estados booleanos a array de valores excluidos
      this.currentGraph.excludeColumns = Object.keys(this.excludeColumnsState).filter(key => this.excludeColumnsState[key]);
    }
  }

  /**
   * Obtiene el número de columnas seleccionadas
   */
  getSelectedColumnsCount(): number {
    return Object.values(this.selectedColumnsState).filter(selected => selected).length;
  }

  /**
   * Obtiene el número de columnas excluidas
   */
  getExcludeColumnsCount(): number {
    return Object.values(this.excludeColumnsState).filter(excluded => excluded).length;
  }

  /**
   * Verifica si la configuración es basada en columnas
   */
  isColumnBased(): boolean {
    return this.currentGraph?.dataSourceType === 'column-based';
  }

  /**
   * Verifica si la gráfica está configurada correctamente
   */
  public isGraphConfigured(graph: GraphConfig): boolean {
    if (graph.dataSourceType === 'column-based') {
      // Para column-based, verificar que haya columnas seleccionadas o disponibles
      return !!(graph.selectedColumns && graph.selectedColumns.length > 0) ||
             !!(this.availableColumns && this.availableColumns.length > 0);
    } else {
      // Para row-based, mantener la lógica original
      return !!(graph.labelColumn && graph.valueColumn);
    }
  }

  /**
   * Prepara los datos para previsualización según el tipo de fuente de datos
   */
  preparePreviewData(): void {
    if (!this.currentGraph) return;

    // Actualizar configuración antes de previsualizar
    if (this.currentGraph.dataSourceType === 'column-based') {
      this.onSelectedColumnsChange();
      this.onExcludeColumnsChange();
    }

    this.previewGraph();
  }
}