import {
  Component,
  Input,
  OnChanges,
  AfterViewInit,
  ViewChild,
  ElementRef,
  SimpleChanges,
} from '@angular/core';

import {
  Chart,
  LineController,
  LineElement,
  PointElement,
  LinearScale,
  CategoryScale,
  Title,
  Tooltip,
  Legend,
  ChartConfiguration,
  SubTitle,
} from 'chart.js';

Chart.register(
  LineController,
  LineElement,
  PointElement,
  LinearScale,
  CategoryScale,
  Title,
  SubTitle,
  Tooltip,
  Legend
);

Chart.defaults.font.size = 20;

interface LineChartDataItem {
  label: string;
  value: number;
  color?: string;
}

@Component({
    selector: 'app-line-chart',
    imports: [],
    templateUrl: './time-chart.component.html',
    styles: [`
    .chart-container {
      position: relative;
      width: 100%;
      height: 100%;
    }
    canvas {
      width: 100%;
      height: 100%;
    }
  `]
})
export class TimeChartComponent implements OnChanges, AfterViewInit {
  @ViewChild('lineCanvas') lineCanvas!: ElementRef<HTMLCanvasElement>;

  @Input() title: string = '';
  @Input() subtitle: string = '';
  @Input() data: LineChartDataItem[] = [];

  private chart: Chart | undefined;

  ngAfterViewInit(): void {
    this.renderChart();
  }

  ngOnChanges(changes: SimpleChanges): void {
    if (this.chart) {
      this.updateChart();
    }
  }

  private renderChart() {
    const ctx = this.lineCanvas.nativeElement.getContext('2d');
    if (!ctx) return;

    const strokeColor = this.data.find(d => d.color)?.color ?? ( '#' + Math.floor(Math.random() * 16777215).toString(16) );

    this.chart = new Chart(ctx, {
      type: 'line',
      data: {
        labels: this.data.map(d => d.label),
        datasets: [
          {
            data: this.data.map(d => d.value),
            label: 'Monto por ciudad',
            borderColor: strokeColor,
            backgroundColor: strokeColor + '66',
            fill: true,
            tension: 0.4,
            borderWidth: 3,
            pointRadius: 5,
            pointHoverRadius: 7,
            pointBackgroundColor: '#fff',
            pointBorderWidth: 2,
          },
        ],
      },
      options: {
        responsive: true,
        plugins: {
          legend: {
            display: false,
          },
          title: {
            display: !!this.title,
            text: this.title,
            font: { size: 25 },
            padding: { top: 10, bottom: 5 }
          },
          subtitle: {
            display: !!this.subtitle,
            text: this.subtitle,
            font: { size: 20 },
            color: '#6b7280',
            padding: { bottom: 10 }
          },
          tooltip: {
            bodyFont: {
              size: 16
            },
            titleFont: {
              size: 16
            },
            footerFont: {
              size: 18
            },
            padding: 8
          }
        },
        scales: {
          x: {
            display: true,
            ticks: {
              autoSkip: false,
              maxRotation: 45,
              minRotation: 45,
            },
          },
          y: {
            display: true,
            title: {
              display: true,
              text: 'Monto',
            },
          },
        },
        onClick: (event, elements, chart) => {
          const points = chart.getElementsAtEventForMode(event as unknown as Event, 'nearest', { intersect: true }, true);
          if (points.length) {
            const firstPoint = points[0];
            const label = chart.data.labels?.[firstPoint.index];
            const value = chart.data.datasets[firstPoint.datasetIndex].data[firstPoint.index];
            alert(`Clicked: ${label} - ${value}`);
          }
        }
      },
    });
  }

  private updateChart() {
    if (!this.chart) return;

    const strokeColor = this.data.find(d => d.color)?.color ?? ( '#' + Math.floor(Math.random() * 16777215).toString(16) );

    this.chart.data.labels = this.data.map(d => d.label);
    this.chart.data.datasets[0].data = this.data.map(d => d.value);
    this.chart.data.datasets[0].borderColor = strokeColor;
    this.chart.data.datasets[0].backgroundColor = strokeColor + '66';

    this.chart.update();
  }
}
