import { Component, Input, Output, EventEmitter } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { FilterBasedColumn } from '../../filter-based-view-config.component';
import { MetricConfig } from '../../../cross-tab-view-config/components/metrics-config/metrics-config.component';
import { MetricsConfigComponent } from '../../../cross-tab-view-config/components/metrics-config/metrics-config.component';
import { SimpleFieldComponent } from '../../../../../../shared/generic-form/simple-field/simple-field.component';
import { SelectFieldComponent } from '../../../../../../shared/generic-form/select-field/select-field.component';

export interface ColumnSelectItem {
  label: string;
  value: string;
}

@Component({
  selector: 'app-filter-based-column-config',
  standalone: true,
  imports: [
    FormsModule,
    SimpleFieldComponent,
    MetricsConfigComponent,
    SelectFieldComponent
  ],
  templateUrl: './filter-based-column-config.component.html',
  styleUrl: './filter-based-column-config.component.css'
})
export class FilterBasedColumnConfigComponent {
  @Input() column: FilterBasedColumn | null = null;
  @Input() allColumns: any[] = [];

  @Output() columnChange = new EventEmitter<FilterBasedColumn | null>();

  newColumnFilterColumn: string = '';
  newColumnFilterCondition: string = '';

  constructor() { }

  /**
   * Convierte las columnas disponibles en items para SelectFieldComponent
   */
  public columnsToSelectItem(): ColumnSelectItem[] {
    return this.allColumns.map(c => ({
      label: c.name.toUpperCase().replaceAll('_', ' '),
      value: c.name
    }));
  }

  /**
   * Actualiza la etiqueta de la columna
   */
  onLabelChange(label: string | number): void {
    if (this.column) {
      this.column.label = label.toString();
      this.emitChanges();
    }
  }

  /**
   * Actualiza las métricas de la columna
   */
  onMetricsChange(metrics: MetricConfig[]): void {
    if (this.column) {
      this.column.metrics = metrics;
      this.emitChanges();
    }
  }

  /**
   * Obtiene las métricas de forma segura
   */
  getMetrics(): MetricConfig[] {
    return this.column?.metrics || [];
  }

  /**
   * Actualiza un filtro de columna específico
   */
  onColumnFilterChange(filterColumn: string, condition: string | number): void {
    if (this.column) {
      if (!this.column.columnFilters) {
        this.column.columnFilters = {};
      }

      if (condition.toString().trim()) {
        this.column.columnFilters[filterColumn] = condition.toString();
      } else {
        delete this.column.columnFilters[filterColumn];
      }

      this.emitChanges();
    }
  }

  /**
   * Obtiene los filtros de columna de forma segura
   */
  getColumnFilters(): Record<string, string> {
    return this.column?.columnFilters || {};
  }

  /**
   * Obtiene el valor actual de un filtro de columna
   */
  getColumnFilterValue(filterColumn: string): string {
    return this.column?.columnFilters?.[filterColumn] || '';
  }

  /**
   * Agrega un nuevo filtro de columna
   */
  addColumnFilter(): void {
    if (this.column && this.newColumnFilterColumn && this.newColumnFilterCondition.trim()) {
      if (!this.column.columnFilters) {
        this.column.columnFilters = {};
      }
      this.column.columnFilters[this.newColumnFilterColumn] = this.newColumnFilterCondition;
      this.newColumnFilterColumn = '';
      this.newColumnFilterCondition = '';
      this.emitChanges();
    }
  }

  /**
   * Elimina un filtro de columna
   */
  removeColumnFilter(filterColumn: string): void {
    if (this.column?.columnFilters) {
      delete this.column.columnFilters[filterColumn];
      this.emitChanges();
    }
  }

  /**
   * Agrega la primera métrica a la columna
   */
  public addFirstMetric(): void {
    if (this.column) {
      if (!this.column.metrics) {
        this.column.metrics = [];
      }
      this.column.metrics.push({
        calculation: 'count',
        label: 'Nueva métrica',
        percentageBase: 'filtered',
        
      });
      this.emitChanges();
    }
  }

  /**
   * Emite cambios al componente padre
   */
  private emitChanges(): void {
    this.columnChange.emit(this.column);
  }

  /**
   * Obtiene los filtros de columna como un array para iteración
   */
  getColumnFiltersArray(): Array<{ column: string, condition: string }> {
    if (!this.column?.columnFilters) return [];

    return Object.entries(this.column.columnFilters).map(([column, condition]) => ({
      column,
      condition: condition.toString()
    }));
  }

  /**
   * Formatea el nombre de una columna para mostrar
   */
  formatColumnName(columnName: string): string {
    return columnName.replace(/_/g, ' ').toUpperCase();
  }
}