import {
  Component,
  Input,
  OnChanges,
  SimpleChanges,
  AfterViewInit,
  ViewChild,
  ElementRef,
} from '@angular/core';

import {
  Chart,
  DoughnutController,
  ArcElement,
  Tooltip,
  Legend,
  Title,
  SubTitle
} from 'chart.js';

Chart.register(DoughnutController, ArcElement, Tooltip, Legend, Title, SubTitle);
Chart.defaults.font.size = 20;

interface DoughnutChartDataItem {
  label: string;
  value: number;
  color?: string;
}

@Component({
    selector: 'app-dougnut-chart',
    imports: [],
    templateUrl: './dougnut-chart.component.html',
    styles: [`
    .chart-container {
      position: relative;
      width: 100%;
      height: 100%;
    }
    canvas {
      width: 100%;
      height: 100%;
    }
  `]
})
export class DougnutChartComponent implements OnChanges, AfterViewInit {
  @ViewChild('dougnutCanvas') doughnutCanvas!: ElementRef<HTMLCanvasElement>;
  @Input() title: string = '';
  @Input() subtitle: string = '';
  @Input() data: DoughnutChartDataItem[] = [];
  @Input() currency ?:boolean = false

  private chart: Chart | undefined;

  ngAfterViewInit(): void {
    this.renderChart();
  }

  ngOnChanges(changes: SimpleChanges): void {
    if (this.chart) {
      this.updateChart();
    }
  }

  private renderChart() {
    const ctx = this.doughnutCanvas.nativeElement.getContext('2d');
    if (!ctx) return;

    this.chart = new Chart(ctx, {
      type: 'doughnut',
      data: {
        labels: this.data.map(d => d.label),
        datasets: [{
          data: this.data.map(d => d.value),
          backgroundColor: this.data.map(d => d.color ?? ( '#' + Math.floor(Math.random() * 16777215).toString(16) ) ),
          hoverOffset: 30
        }]
      },
      options: {
        responsive: true,
        cutout: '50%',
        plugins: {
          legend: {
            position: 'right',
          },
          title: {
            display: !!this.title,
            text: this.title,
            font: { size: 25 },
            padding: { top: 10, bottom: 5 }
          },
          subtitle: {
            display: !!this.subtitle,
            text: this.subtitle,
            font: { size: 20 },
            color: '#6b7280',
            padding: { bottom: 10 }
          },
          tooltip: {
            bodyFont: { size: 16 },
            titleFont: { size: 16 },
            footerFont: { size: 18 },
            padding: 8,
            callbacks: {
              label: (tooltipItem) => {
                const label = tooltipItem.label || '';
                const value = tooltipItem.raw as number;
                const valueString= this.currency ? "$"+ value.toLocaleString() : value
                return `${label}: ${valueString}`;
              }
            }
          }
        },
        onClick: (event, elements, chart) => {
          const points = chart.getElementsAtEventForMode(
            event as unknown as Event,
            'nearest',
            { intersect: true },
            true
          );
          if (points.length > 0) {
            const point = points[0];
            const label = chart.data.labels?.[point.index];
            const value = chart.data.datasets[point.datasetIndex].data[point.index];
            alert(`Clicked on:\nLabel: ${label}\nValue: $${value}`);
          }
        }
      }
    });
  }

  private updateChart() {
    if (!this.chart) return;

    this.chart.data.labels = this.data.map(d => d.label);
    this.chart.data.datasets[0].data = this.data.map(d => d.value);
    this.chart.data.datasets[0].backgroundColor = this.data.map(d => d.color ?? ( '#' + Math.floor(Math.random() * 16777215).toString(16)) );
    this.chart.update();
  }
}
