import { Component, EventEmitter, inject, Input, Output, SimpleChanges } from '@angular/core';
import { FinalView, CurrentView } from '../informe-tabla-dinamica-local.component';
import { FormsModule } from '@angular/forms';
import { CrossTabConfig, GraphConfig } from '../cross-tab-view-config/cross-tab-view-config.component';
import { CrossTabUtilsService } from '../services/cross-tab-utils.service';
import { FilterBasedConfig } from '../filter-based-view-config/filter-based-view-config.component';
import { FilterBasedUtilsService } from '../filter-based-view-config/services/filter-based-utils.service';
import { TablaDinamicaComponent } from "../shared/tabla-dinamica/tabla-dinamica.component";
import { Table, Cell, THeader, TFoot, TBody } from '../interfaces/table';
import { TableGuardService } from '../guards/tabla-guard.service';
import { GraphPreviewComponent } from "../shared/graph-preview/graph-preview.component";
import { NgClass } from '@angular/common';

@Component({
  selector: 'app-final-view-config',
  imports: [
    FormsModule,
    TablaDinamicaComponent,
    GraphPreviewComponent,
    NgClass,
  ],
  templateUrl: './final-view-config.component.html',
  styleUrl: './final-view-config.component.css'
})
export class FinalViewConfigComponent {
  @Input() data: any[] = [];

  @Input() showFinalViewConfig = false;
  @Output() showFinalViewConfigChange = new EventEmitter<boolean>();

  @Input() currentFinalView: FinalView | null = null;
  @Output() currentFinalViewChange = new EventEmitter<FinalView | null>();

  @Input() crossTabConfigs: CrossTabConfig[] = [];
  @Output() crossTabConfigsChange = new EventEmitter<CrossTabConfig[]>();

  @Input() filterBasedConfigs: FilterBasedConfig[] = [];
  @Output() filterBasedConfigsChange = new EventEmitter<FilterBasedConfig[]>();

  @Input() currentView: CurrentView = 'normal';
  @Output() currentViewChange = new EventEmitter<CurrentView>();

  @Input() finalViews: FinalView[] = [];
  @Output() finalViewsChange = new EventEmitter<FinalView[]>();

  @Output() reset = new EventEmitter<void>();

  @Input() showControllers = true

  // Suponiendo que guardas la rowDimension en una propiedad
  currentRowDimension: string = '';

  table: Table | null = null;

  showFinalView = false

  // Almacenar tablas individuales generadas para cada configuración
  generatedTables: { [configId: string]: Table } = {};

  // Array de gráficas con sus tablas correspondientes para evitar renderizados extras
  graphsWithTables: Array<{graph: GraphConfig, table: Table}> = [];

  //services

  public crossTabUtils = inject(CrossTabUtilsService)
  public filterBasedUtils = inject(FilterBasedUtilsService)
  public tableGuard = inject(TableGuardService)

  ngOnChanges(changes: SimpleChanges) {
    if ((changes['finalViews'] || changes['data']) && this.finalViews.length) {
      const find = this.finalViews.find(v => v.showInTable)
      if (find) {
        this.generateFinalView(find)
      }
    }
  }

  public newFinalView() {
    const newFinalView: FinalView = {
      name: '',
      crossConfigs: [],
      showInTable: false,
      visibleGraphs: [],
      displayMode: 'table'
    }

    this.showFinalViewConfig = true
    this.currentFinalView = newFinalView
    this.currentFinalViewChange.emit(this.currentFinalView)
    this.finalViews.push(this.currentFinalView)
    this.finalViewsChange.emit(this.finalViews)
  }


  public formatCombinedColumnHeader(key: string): string {
    if (key === this.currentRowDimension) return key;
    // Formato: "PROGRAMA_A__Monto" → "PROGRAMA_A (Monto)"
    const parts = key.split('__');
    if (parts.length === 2) {
      return `${parts[0]} (${parts[1].replace(/_/g, ' ')})`;
    }
    return key;
  }

  generateFinalView(view: FinalView) {
    if (view.crossConfigs.length === 0) return;

    // Limpiar arrays anteriores
    this.generatedTables = {};
    this.graphsWithTables = [];

    // Generar tablas individuales y guardarlas para las configuraciones seleccionadas
    const tables: Table[] = [];
    view.crossConfigs.forEach(configId => {
      let config: CrossTabConfig|FilterBasedConfig|undefined;
      let table: Table;

      // Buscar primero en CrossTab configs
      config = this.crossTabConfigs.find(cr => cr.id === configId);
      if (config) {
        table = this.crossTabUtils.generateTable(config, this.data);
      } else {
        // Buscar en FilterBased configs
        config = this.filterBasedConfigs.find(fb => fb.id === configId);
        if (config) {
          table = this.filterBasedUtils.generateFilterBasedTable(config, this.data);
        } else {
          console.warn('⚠️ Configuración no encontrada:', configId);
          return;
        }
      }

      this.generatedTables[configId] = table;
      tables.push(table);

      // Emparejar gráficas con sus tablas (solo las gráficas visibles)
      if (config.graphs) {
        config.graphs.forEach((graph: GraphConfig) => {
          if (view.visibleGraphs.includes(graph.id)) {
            this.graphsWithTables.push({ graph, table });
          }
        });
      }
    });

    // Generar tablas adicionales para gráficas de configuraciones NO seleccionadas
    this.generateAdditionalGraphTables(view);

    if (tables.length === 0) {
      console.error('❌ No se generaron tablas');
      return;
    }

    // Combinar las tablas generadas para la vista de tabla
    //console.log('🔗 Combinando', tables.length, 'tablas');
    this.table = this.combineTables(tables);

    this.currentView = 'final'
    this.currentViewChange.emit('final');

    this.currentFinalView = view
    this.currentFinalViewChange.emit(view);

    this.showFinalView = true
    //console.log('✅ Vista final generada exitosamente');
  }

  /**
   * Genera tablas adicionales para gráficas de configuraciones que no están seleccionadas
   * pero tienen gráficas visibles
   */
  private generateAdditionalGraphTables(view: FinalView): void {
    // Obtener todos los IDs de configuraciones que tienen gráficas visibles
    const visibleGraphConfigIds = view.visibleGraphs.map(graphId => {
      // Encontrar la configuración que contiene esta gráfica
      for (const config of this.crossTabConfigs) {
        if (config.graphs?.some(g => g.id === graphId)) {
          return config.id;
        }
      }
      for (const config of this.filterBasedConfigs) {
        if (config.graphs?.some(g => g.id === graphId)) {
          return config.id;
        }
      }
      return null;
    }).filter(id => id !== null);

    // Generar tablas para configuraciones con gráficas visibles que no están en crossConfigs
    visibleGraphConfigIds.forEach(configId => {
      if (configId && !view.crossConfigs.includes(configId)) {
        let config: CrossTabConfig|FilterBasedConfig|undefined;
        let table: Table;

        // Buscar en CrossTab configs
        config = this.crossTabConfigs.find(cr => cr.id === configId);
        if (config) {
          table = this.crossTabUtils.generateTable(config, this.data);
        } else {
          // Buscar en FilterBased configs
          config = this.filterBasedConfigs.find(fb => fb.id === configId);
          if (config) {
            table = this.filterBasedUtils.generateFilterBasedTable(config, this.data);
          } else {
            console.warn('⚠️ Configuración no encontrada para gráfica:', configId);
            return;
          }
        }

        // Guardar tabla adicional (no se usará para la tabla combinada)
        this.generatedTables[configId] = table;

        // Emparejar gráficas con sus tablas (evitar duplicados)
        if (config.graphs) {
          config.graphs.forEach((graph: GraphConfig) => {
            if (view.visibleGraphs.includes(graph.id) &&
                !this.graphsWithTables.some(item => item.graph.id === graph.id)) {
              this.graphsWithTables.push({ graph, table });
            }
          });
        }
      }
    });
  }

  /**
   * Combina múltiples tablas en una sola, mostrando solo la primera columna de la primera tabla
   * y fusionando todas las demás columnas de todas las tablas
   * @param tables Array de tablas generadas para combinar
   * @returns Tabla combinada con estructura unificada
   */
  private combineTables(tables: Table[]): Table {
    if (tables.length === 0) {
      throw new Error('No hay tablas para combinar');
    }

    if (tables.length === 1) {
      return tables[0];
    }

    const firstTable = tables[0];
    const remainingTables = tables.slice(1);

    // Combinar headers
    const combinedHeader = this.combineHeaders(firstTable, remainingTables);

    // Combinar body
    const combinedBody = this.combineBody(firstTable, remainingTables);

    // Combinar footer si existe
    const combinedFooter = this.combineFooters(firstTable, remainingTables);

    return {
      header: combinedHeader,
      body: combinedBody,
      footer: combinedFooter
    };
  }

  /**
   * Combina los headers de múltiples tablas
   * Mantiene la primera columna del header de la primera tabla y fusiona las demás
   */
  private combineHeaders(firstTable: Table, remainingTables: Table[]): THeader {
    const firstHeader = firstTable.header;
    const remainingHeaders = remainingTables.map(t => t.header);

    // Si el header es un HeaderObject, procesarlo como tal
    if (this.tableGuard.isHeaderObject(firstHeader)) {
      const firstRows = firstHeader.rows;
      const remainingRows = remainingHeaders.map(h =>
        this.tableGuard.isHeaderObject(h) ? h.rows : []
      );

      // Para cada fila del header, combinar las celdas
      const combinedRows = firstRows.map((firstRow: any, rowIndex: number) => {
        const combinedCells: Cell[] = [];

        // Obtener celdas de la primera fila
        const firstCells = this.tableGuard.getRowCells(firstRow);

        // Agregar la primera celda de la primera tabla (columna de dimensión de fila)
        combinedCells.push(firstCells[0]);

        // Agregar todas las demás celdas de la primera tabla (excepto la primera)
        for (let i = 1; i < firstCells.length; i++) {
          combinedCells.push(firstCells[i]);
        }

        // Agregar todas las celdas de las tablas restantes (excepto la primera columna)
        remainingRows.forEach(remainingRow => {
          if (remainingRow[rowIndex]) {
            const cells = this.tableGuard.getRowCells(remainingRow[rowIndex]);
            // Saltar la primera celda (columna de dimensión de fila)
            for (let i = 1; i < cells.length; i++) {
              combinedCells.push(cells[i]);
            }
          }
        });

        return combinedCells;
      });

      return {
        rows: combinedRows,
        style: firstHeader.style
      };
    }

    // Si el header es un array simple de Row[]
    const firstRows = Array.isArray(firstHeader) ? firstHeader : [];
    const remainingRows = remainingHeaders.map(h => Array.isArray(h) ? h : []);

    const combinedRows = firstRows.map((firstRow: any, rowIndex: number) => {
      const combinedCells: Cell[] = [];
      const firstCells = this.tableGuard.getRowCells(firstRow);

      // Agregar la primera celda de la primera tabla
      combinedCells.push(firstCells[0]);

      // Agregar las demás celdas de la primera tabla
      for (let i = 1; i < firstCells.length; i++) {
        combinedCells.push(firstCells[i]);
      }

      // Agregar celdas de las tablas restantes (excepto la primera columna)
      remainingRows.forEach(remainingRow => {
        if (remainingRow[rowIndex]) {
          const cells = this.tableGuard.getRowCells(remainingRow[rowIndex]);
          for (let i = 1; i < cells.length; i++) {
            combinedCells.push(cells[i]);
          }
        }
      });

      return combinedCells;
    });

    return combinedRows;
  }

  /**
   * Combina el body de múltiples tablas
   * Mantiene la primera columna del body de la primera tabla y fusiona las demás
   */
  private combineBody(firstTable: Table, remainingTables: Table[]): TBody {
    const firstBody = firstTable.body;
    const remainingBodies = remainingTables.map(t => t.body);

    return firstBody.map((firstRow, rowIndex) => {
      const combinedCells: Cell[] = [];
      const firstCells = this.tableGuard.getRowCells(firstRow);

      // Agregar la primera celda de la primera tabla (columna de dimensión de fila)
      combinedCells.push(firstCells[0]);

      // Agregar las demás celdas de la primera tabla
      for (let i = 1; i < firstCells.length; i++) {
        combinedCells.push(firstCells[i]);
      }

      // Agregar celdas de las tablas restantes (excepto la primera columna)
      remainingBodies.forEach(remainingBody => {
        if (remainingBody[rowIndex]) {
          const cells = this.tableGuard.getRowCells(remainingBody[rowIndex]);
          for (let i = 1; i < cells.length; i++) {
            combinedCells.push(cells[i]);
          }
        }
      });

      return combinedCells;
    });
  }

  /**
   * Combina los footers de múltiples tablas
   * Mantiene la primera columna del footer de la primera tabla y fusiona las demás
   * Agrega filas de totales vacías cuando algunas tablas no tienen totales pero otras sí
   */
  private combineFooters(firstTable: Table, remainingTables: Table[]): TFoot {
    const allTables = [firstTable, ...remainingTables];

    // Verificar si alguna tabla tiene footer (totales)
    const hasAnyFooter = allTables.some(t => t.footer &&
      (Array.isArray(t.footer) ? t.footer.length > 0 : t.footer.rows.length > 0));

    if (!hasAnyFooter) {
      return [];
    }

    const firstFooter = firstTable.footer;
    const remainingFooters = remainingTables.map(t => t.footer);

    // Si la primera tabla no tiene footer, buscar el primer footer disponible
    const availableFooter = firstFooter || remainingFooters.find(f => f !== undefined);

    if (!availableFooter) {
      return [];
    }

    if (this.tableGuard.isFooterObject(availableFooter)) {
      const firstRows = (firstFooter && this.tableGuard.isFooterObject(firstFooter)) ? firstFooter.rows : availableFooter.rows;
      const remainingRows = remainingFooters.map(f =>
        f && this.tableGuard.isFooterObject(f) ? f.rows : []
      );

      // Determinar el número máximo de filas de footer entre todas las tablas
      const maxFooterRows = Math.max(firstRows.length, ...remainingRows.map(r => r.length));

      // Crear filas combinadas para cada fila de footer
      const combinedRows: Cell[][] = [];

      for (let rowIndex = 0; rowIndex < maxFooterRows; rowIndex++) {
        const combinedCells: Cell[] = [];

        // Procesar la primera tabla
        if (firstRows[rowIndex]) {
          const firstCells = this.tableGuard.getRowCells(firstRows[rowIndex]);
          combinedCells.push(firstCells[0]); // Primera columna

          // Agregar las demás celdas de la primera tabla
          for (let i = 1; i < firstCells.length; i++) {
            combinedCells.push(firstCells[i]);
          }
        } else {
          // Si la primera tabla no tiene esta fila de footer, crear una fila vacía
          const firstCells = this.tableGuard.getRowCells(firstRows[0] || firstRows[firstRows.length - 1]);
          combinedCells.push(firstCells[0]); // Primera columna

          // Agregar celdas vacías para las demás columnas de la primera tabla
          for (let i = 1; i < firstCells.length; i++) {
            combinedCells.push('');
          }
        }

        // Procesar las tablas restantes
        remainingRows.forEach((remainingRow, tableIndex) => {
          const tableFooter = remainingFooters[tableIndex];

          if (remainingRow[rowIndex]) {
            const cells = this.tableGuard.getRowCells(remainingRow[rowIndex]);
            // Saltar la primera celda (columna de dimensión de fila)
            for (let i = 1; i < cells.length; i++) {
              combinedCells.push(cells[i]);
            }
          } else if (tableFooter && this.tableGuard.isFooterObject(tableFooter)) {
            // La tabla tiene footer pero no esta fila específica, agregar celdas vacías
            const referenceRow = tableFooter.rows[0] || tableFooter.rows[tableFooter.rows.length - 1];
            const cells = this.tableGuard.getRowCells(referenceRow);
            for (let i = 1; i < cells.length; i++) {
              combinedCells.push('');
            }
          } else {
            // La tabla no tiene footer, agregar celdas vacías basadas en el body
            const tableBody = allTables[tableIndex + 1].body;
            if (tableBody && tableBody.length > 0) {
              const referenceRow = tableBody[0];
              const cells = this.tableGuard.getRowCells(referenceRow);
              for (let i = 1; i < cells.length; i++) {
                combinedCells.push('');
              }
            }
          }
        });

        combinedRows.push(combinedCells);
      }

      return {
        rows: combinedRows,
        style: (firstFooter && this.tableGuard.isFooterObject(firstFooter)) ? firstFooter.style : availableFooter.style
      };
    }

    // Si el footer es un array simple de Row[]
    const firstRows = Array.isArray(firstFooter) ? firstFooter : (Array.isArray(availableFooter) ? availableFooter : []);
    const remainingRows = remainingFooters.map(f => Array.isArray(f) ? f : []);

    // Determinar el número máximo de filas de footer
    const maxFooterRows = Math.max(firstRows.length, ...remainingRows.map(r => r.length));

    const combinedRows: Cell[][] = [];

    for (let rowIndex = 0; rowIndex < maxFooterRows; rowIndex++) {
      const combinedCells: Cell[] = [];

      // Procesar la primera tabla
      if (firstRows[rowIndex]) {
        const firstCells = this.tableGuard.getRowCells(firstRows[rowIndex]);
        combinedCells.push(firstCells[0]); // Primera columna

        // Agregar las demás celdas de la primera tabla
        for (let i = 1; i < firstCells.length; i++) {
          combinedCells.push(firstCells[i]);
        }
      } else if (firstRows.length > 0) {
        // Si la primera tabla no tiene esta fila pero tiene otras filas, crear una vacía
        const referenceRow = firstRows[0];
        const firstCells = this.tableGuard.getRowCells(referenceRow);
        combinedCells.push(firstCells[0]); // Primera columna

        for (let i = 1; i < firstCells.length; i++) {
          combinedCells.push('');
        }
      }

      // Procesar las tablas restantes
      remainingRows.forEach((remainingRow, tableIndex) => {
        if (remainingRow[rowIndex]) {
          const cells = this.tableGuard.getRowCells(remainingRow[rowIndex]);
          for (let i = 1; i < cells.length; i++) {
            combinedCells.push(cells[i]);
          }
        } else if (remainingRow.length > 0) {
          // La tabla tiene footer pero no esta fila específica
          const referenceRow = remainingRow[0];
          const cells = this.tableGuard.getRowCells(referenceRow);
          for (let i = 1; i < cells.length; i++) {
            combinedCells.push('');
          }
        } else {
          // La tabla no tiene footer, agregar celdas vacías basadas en el body
          const tableBody = allTables[tableIndex + 1].body;
          if (tableBody && tableBody.length > 0) {
            const referenceRow = tableBody[0];
            const cells = this.tableGuard.getRowCells(referenceRow);
            for (let i = 1; i < cells.length; i++) {
              combinedCells.push('');
            }
          }
        }
      });

      combinedRows.push(combinedCells);
    }

    return combinedRows;
  }


  // En tu componente TypeScript
  scrollGraphs(direction: number) {
    const scrollContainer = document.querySelector('.graphs-scroll-wrapper') as HTMLElement;
    if (scrollContainer) {
      const scrollAmount = 500; // Cantidad de scroll en píxeles
      scrollContainer.scrollBy({
        left: scrollAmount * direction,
        behavior: 'smooth'
      });
    }
  }

  // Opcional: Auto-scroll basado en rueda del mouse
  enableWheelScroll() {
    const scrollContainer = document.querySelector('.graphs-scroll-wrapper') as HTMLElement;
    if (scrollContainer) {
      scrollContainer.addEventListener('wheel', (event) => {
        event.preventDefault();
        scrollContainer.scrollBy({
          left: event.deltaY * 2, // Multiplicador para hacer el scroll más sensible
          behavior: 'smooth'
        });
      });
    }
  }

  private canCombineConfigs(configs: CrossTabConfig[]): boolean {
    if (configs.length === 0) return false;
    const firstRowDim = configs[0].rowDimension;
    return configs.every(c => c.rowDimension === firstRowDim);
  }

  /**
   * Determina si alguna configuración en la vista final tiene totales habilitados
   * @returns boolean - True si alguna configuración tiene totales o porcentajes habilitados
   */
  public shouldShowFinalTotals(): boolean {
    if (!this.currentFinalView) return false;

    const configs = this.crossTabConfigs.filter(c => this.currentFinalView!.crossConfigs.includes(c.id));
    return configs.some(config => this.crossTabUtils.shouldShowTotales(config.totales));
  }

  /**
   * Obtiene todas las configuraciones disponibles (CrossTab y FilterBased)
   * @returns Array de configuraciones unificadas
   */
  public getAllAvailableConfigs(): Array<{ config: CrossTabConfig | FilterBasedConfig, type: 'cross' | 'filter' }> {
    const configs: Array<{ config: CrossTabConfig | FilterBasedConfig, type: 'cross' | 'filter' }> = [];

    // Agregar CrossTab configs
    this.crossTabConfigs.forEach(config => {
      configs.push({ config, type: 'cross' });
    });

    // Agregar FilterBased configs
    this.filterBasedConfigs.forEach(config => {
      configs.push({ config, type: 'filter' });
    });

    return configs;
  }

  /**
   * Busca una configuración por su ID en ambos tipos de configs
   * @param configId ID de la configuración a buscar
   * @returns Configuración encontrada o null
   */
  public getConfigById(configId: string): CrossTabConfig | FilterBasedConfig | null {
    // Buscar en CrossTab configs
    const crossConfig = this.crossTabConfigs.find(c => c.id === configId);
    if (crossConfig) return crossConfig;

    // Buscar en FilterBased configs
    const filterConfig = this.filterBasedConfigs.find(c => c.id === configId);
    if (filterConfig) return filterConfig;

    return null;
  }

  /**
   * Obtiene el nombre descriptivo de una configuración
   * @param config Configuración (CrossTab o FilterBased)
   * @returns Nombre descriptivo
   */
  public getConfigDisplayName(config: CrossTabConfig | FilterBasedConfig): string {
    if ('rowDimension' in config) {
      // Es CrossTab
      const crossConfig = config as CrossTabConfig;
      return `${crossConfig.rowDimension} × ${crossConfig.columnLabel ?? crossConfig.columnDimension}`;
    } else {
      // Es FilterBased
      const filterConfig = config as FilterBasedConfig;
      return `${filterConfig.name} (${filterConfig.rows.length} filas × ${filterConfig.columns.length} columnas)`;
    }
  }

  /**
   * Obtiene la descripción detallada de una configuración
   * @param config Configuración (CrossTab o FilterBased)
   * @returns Descripción detallada
   */
  public getConfigDescription(config: CrossTabConfig | FilterBasedConfig): { rows: string, columns: string, metrics: string } {
    if ('rowDimension' in config) {
      // Es CrossTab
      const crossConfig = config as CrossTabConfig;
      return {
        rows: `Filas: ${crossConfig.rowDimension || 'No definido'}`,
        columns: `Columnas: ${crossConfig.columnDimension || crossConfig.columnLabel || 'No definido'}`,
        metrics: `Métricas: ${crossConfig.metrics.length}`
      };
    } else {
      // Es FilterBased
      const filterConfig = config as FilterBasedConfig;
      const totalMetrics = filterConfig.columns.reduce((sum, col) => sum + col.metrics.length, 0);
      return {
        rows: `Filas: ${filterConfig.rows.length} configuraciones`,
        columns: `Columnas: ${filterConfig.columns.length} configuraciones`,
        metrics: `Métricas: ${totalMetrics}`
      };
    }
  }

  /**
   * Verifica si una configuración es CrossTab
   * @param config Configuración a verificar
   * @returns true si es CrossTab
   */
  public isCrossTabConfig(config: CrossTabConfig | FilterBasedConfig): config is CrossTabConfig {
    return 'rowDimension' in config;
  }

  /**
   * Verifica si una configuración es FilterBased
   * @param config Configuración a verificar
   * @returns true si es FilterBased
   */
  public isFilterBasedConfig(config: CrossTabConfig | FilterBasedConfig): config is FilterBasedConfig {
    return 'rows' in config && 'columns' in config;
  }

  /**
   * Obtiene el rowDimension de una CrossTab config
   * @param config Configuración
   * @returns rowDimension o string vacío
   */
  public getRowDimension(config: CrossTabConfig | FilterBasedConfig): string {
    return this.isCrossTabConfig(config) ? (config.rowDimension || 'No definido') : '';
  }

  /**
   * Obtiene el columnDimension/columnLabel de una CrossTab config
   * @param config Configuración
   * @returns columnDimension/columnLabel o string vacío
   */
  public getColumnDimension(config: CrossTabConfig | FilterBasedConfig): string {
    return this.isCrossTabConfig(config) ? (config.columnDimension || config.columnLabel || 'No definido') : '';
  }

  /**
   * Obtiene el número de métricas de una configuración
   * @param config Configuración
   * @returns número de métricas
   */
  public getMetricsCount(config: CrossTabConfig | FilterBasedConfig): number {
    if (this.isCrossTabConfig(config)) {
      return config.metrics.length;
    } else {
      return config.columns.reduce((sum, col) => sum + col.metrics.length, 0);
    }
  }

  /**
   * Obtiene el número de filas de una FilterBased config
   * @param config Configuración
   * @returns número de filas
   */
  public getRowsCount(config: CrossTabConfig | FilterBasedConfig): number {
    return this.isFilterBasedConfig(config) ? config.rows.length : 0;
  }

  /**
   * Obtiene el número de columnas de una FilterBased config
   * @param config Configuración
   * @returns número de columnas
   */
  public getColumnsCount(config: CrossTabConfig | FilterBasedConfig): number {
    return this.isFilterBasedConfig(config) ? config.columns.length : 0;
  }

  /**
   * Obtiene todas las gráficas disponibles de las configuraciones seleccionadas (CrossTab y FilterBased)
   * @returns Array de GraphConfig disponibles
   */
  public getAvailableGraphs(): GraphConfig[] {
    if (!this.currentFinalView) return [];

    const graphs: GraphConfig[] = [];
    this.currentFinalView.crossConfigs.forEach(configId => {
      const config = this.getConfigById(configId);
      if (config && config.graphs) {
        graphs.push(...config.graphs);
      }
    });

    return graphs;
  }

  /**
   * Obtiene todas las gráficas disponibles de TODAS las configuraciones (CrossTab y FilterBased)
   * sin importar si están seleccionadas o no
   * @returns Array de GraphConfig disponibles de todas las configuraciones
   */
  public getAllAvailableGraphs(): Array<{ graph: GraphConfig, configId: string, isSelected: boolean }> {
    const allGraphs: Array<{ graph: GraphConfig, configId: string, isSelected: boolean }> = [];

    // Agregar gráficas de todas las CrossTab configs
    this.crossTabConfigs.forEach(config => {
      if (config.graphs) {
        const isSelected = this.currentFinalView?.crossConfigs.includes(config.id) || false;
        config.graphs.forEach(graph => {
          allGraphs.push({ graph, configId: config.id, isSelected });
        });
      }
    });

    // Agregar gráficas de todas las FilterBased configs
    this.filterBasedConfigs.forEach(config => {
      if (config.graphs) {
        const isSelected = this.currentFinalView?.crossConfigs.includes(config.id) || false;
        config.graphs.forEach(graph => {
          allGraphs.push({ graph, configId: config.id, isSelected });
        });
      }
    });

    return allGraphs;
  }

  /**
   * Obtiene las gráficas con sus tablas correspondientes para mostrar en FinalView
   * @returns Array de gráficas emparejadas con sus tablas
   */
  public getGraphsWithTables(): Array<{graph: GraphConfig, table: Table}> {
    return this.graphsWithTables;
  }

  /**
   * Elimina una vista final
   * @param view Vista final a eliminar
   */
  public removeFinalView(view: FinalView): void {
    this.finalViewsChange.emit(this.finalViews.filter(v => v !== view))

    if (this.currentFinalView === view) {
      this.reset.emit()
    }
  }

  /**
 * Edita una vista final existente
 * @param view Vista final a editar
 */
  public editFinalView(view: FinalView): void {
    this.currentFinalView = view
    this.currentFinalViewChange.emit(view)
    this.showFinalViewConfig = true
    this.showFinalViewConfigChange.emit(true)
  }

  ngAfterViewInit() {
    this.enableWheelScroll();
  }

  toggleFinalConfig(configId: string): void {
    if (!this.currentFinalView) return;

    const exists = this.currentFinalView.crossConfigs.includes(configId);
    const newConfigs = exists
      ? this.currentFinalView.crossConfigs.filter(id => id !== configId)
      : [...this.currentFinalView.crossConfigs, configId];

    this.currentFinalView.crossConfigs= newConfigs
    this.currentFinalViewChange.emit(this.currentFinalView);
  }

  toggleGraphVisibility(graphId: string): void {
    if (!this.currentFinalView) return;

    const exists = this.currentFinalView.visibleGraphs.includes(graphId);
    const newGraphs = exists
      ? this.currentFinalView.visibleGraphs.filter(id => id !== graphId)
      : [...this.currentFinalView.visibleGraphs, graphId];

    this.currentFinalView.visibleGraphs = newGraphs
    this.currentFinalViewChange.emit(this.currentFinalView);
  }

  toggleDisplayMode(mode: 'table' | 'graphs'): void {
    if (!this.currentFinalView) {
      console.error('No hay vista final disponible');
      return;
    }

    this.currentFinalView.displayMode=mode
  }
}
