import { Component, Input, Output, EventEmitter } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { FilterBasedConfig } from '../../filter-based-view-config.component';
import { SimpleFieldComponent } from '../../../../../../shared/generic-form/simple-field/simple-field.component';
import { SelectFieldComponent } from '../../../../../../shared/generic-form/select-field/select-field.component';

export interface ColumnConfig {
  name: string;
  dataType: 'string' | 'number' | 'date' | 'boolean';
}

export interface SelectItem {
  label: string;
  value: string;
}

@Component({
  selector: 'app-filter-based-config-form',
  standalone: true,
  imports: [
    FormsModule,
    SimpleFieldComponent,
    SelectFieldComponent
  ],
  templateUrl: './filter-based-config-form.component.html',
  styleUrl: './filter-based-config-form.component.css'
})
export class FilterBasedConfigFormComponent {
  @Input() currentFilterBasedConfig: FilterBasedConfig | null = null;
  @Input() allColumns: ColumnConfig[] = [];

  @Output() currentFilterBasedConfigChange = new EventEmitter<FilterBasedConfig | null>();

  // Estados para la nueva UX
  isExpanded: boolean = false;
  isEditMode: boolean = false;
  showAddFilterInline: boolean = false;
  newFilterColumn: string = '';

  constructor() { }

  //#region Métodos de ayuda para templates

  getConfigName(): string {
    return this.currentFilterBasedConfig?.name || '';
  }

  hasGlobalFilters(): boolean {
    const filters = this.currentFilterBasedConfig?.globalFilters;
    return filters ? Object.keys(filters).length > 0 : false;
  }

  getGlobalFilterKeys(): string[] {
    const filters = this.currentFilterBasedConfig?.globalFilters;
    return filters ? Object.keys(filters) : [];
  }

  formatFilterColumnName(columnName: string): string {
    return columnName.replace(/_/g, ' ').toUpperCase();
  }

  //#endregion

  /**
   * Convierte las columnas disponibles en items para un componente SelectField
   */
  public columnsToSelectItem(): SelectItem[] {
    return this.allColumns.map(c => ({
      label: c.name.toUpperCase().replaceAll('_', ' '),
      value: c.name
    }));
  }

  /**
   * Actualiza el nombre de la configuración
   */
  onNameChange(name: string | number): void {
    if (this.currentFilterBasedConfig) {
      this.currentFilterBasedConfig.name = name.toString();
      this.emitChanges();
    }
  }

  /**
   * Actualiza un filtro global
   */
  onGlobalFilterChange(column: string, condition: string | number): void {
    if (this.currentFilterBasedConfig) {
      if (!this.currentFilterBasedConfig.globalFilters) {
        this.currentFilterBasedConfig.globalFilters = {};
      }

      const conditionStr = condition.toString();
      if (conditionStr.trim()) {
        this.currentFilterBasedConfig.globalFilters[column] = conditionStr;
      } else {
        delete this.currentFilterBasedConfig.globalFilters[column];
      }

      this.emitChanges();
    }
  }

  /**
   * Obtiene el valor actual de un filtro global
   */
  getGlobalFilterValue(column: string): string {
    return this.currentFilterBasedConfig?.globalFilters?.[column] || '';
  }

  /**
   * Agrega un nuevo filtro global (método antiguo actualizado)
   */
  addGlobalFilter(): void {
    // Mostrar sección inline para agregar filtro
    this.showAddFilterInline = true;
  }

  /**
   * Obtiene las columnas disponibles para agregar como filtro
   */
  getAvailableColumnsForFilter(): SelectItem[] {
    if (!this.currentFilterBasedConfig?.globalFilters) {
      return this.columnsToSelectItem();
    }

    const usedColumns = Object.keys(this.currentFilterBasedConfig.globalFilters);
    return this.columnsToSelectItem().filter(column => !usedColumns.includes(column.value));
  }

  /**
   * Agrega un nuevo filtro global con columna seleccionada (inline)
   */
  addNewGlobalFilter(): void {
    if (this.currentFilterBasedConfig && this.newFilterColumn) {
      if (!this.currentFilterBasedConfig.globalFilters) {
        this.currentFilterBasedConfig.globalFilters = {};
      }

      // Agregar el nuevo filtro con valor vacío
      this.currentFilterBasedConfig.globalFilters[this.newFilterColumn] = '';

      // Limpiar selección
      this.newFilterColumn = '';

      // Emitir cambios
      this.emitChanges();
    }
  }

  /**
   * Maneja el cambio en el SelectField de columna
   */
  onNewFilterColumnChange(): void {
    if (this.newFilterColumn) {
      // Auto-agregar filtro cuando se selecciona una columna
      this.addNewGlobalFilter();
    }
  }

  /**
   * Cambia el estado de expansión de la sección de filtros
   */
  toggleExpanded(): void {
    this.isExpanded = !this.isExpanded;
    if (!this.isExpanded) {
      this.isEditMode = false;
    }
  }

  /**
   * Activa el modo edición
   */
  enableEditMode(): void {
    this.isEditMode = true;
  }

  /**
   * Desactiva el modo edición
   */
  disableEditMode(): void {
    this.isEditMode = false;
  }

  /**
   * Elimina un filtro global
   */
  removeGlobalFilter(column: string): void {
    if (this.currentFilterBasedConfig?.globalFilters) {
      delete this.currentFilterBasedConfig.globalFilters[column];
      this.emitChanges();
    }
  }

  /**
   * Emite cambios al componente padre
   */
  private emitChanges(): void {
    this.currentFilterBasedConfigChange.emit(this.currentFilterBasedConfig);
  }
}