import {
  Component,
  Input,
  OnChanges,
  SimpleChanges,
  AfterViewInit,
  ViewChild,
  ElementRef,
} from '@angular/core';

import {
  Chart,
  ChartConfiguration,
  BarController,
  BarElement,
  CategoryScale,
  LinearScale,
  Tooltip,
  Legend,
  Title,
  SubTitle
} from 'chart.js';

Chart.register(BarController, BarElement, CategoryScale, LinearScale, Tooltip, Legend, Title, SubTitle);

Chart.defaults.font.size = 20;

interface ComparisonBarChartDataset {
  label: string;
  data: number[];
  backgroundColor?: string;
}

@Component({
    selector: 'app-comparison-bar-chart',
    imports: [],
    templateUrl: './comparison-bar-chart.component.html',
    styles: [`
    .chart-container {
      position: relative;
      width: 100%;
      height: 100%;
    }
    canvas {
      width: 100%;
      height: 100%;
    }
  `]
})
export class ComparisonBarChartComponent implements OnChanges, AfterViewInit {
  @ViewChild('barCanvas') barCanvas!: ElementRef<HTMLCanvasElement>;

  @Input() title: string = '';
  @Input() subtitle: string = '';
  @Input() labels: string[] = [];
  @Input() datasets: ComparisonBarChartDataset[] = [];
  @Input() currencySymbol: string = '$'; // ✅ New input

  private chart: Chart | undefined;

  ngAfterViewInit(): void {
    this.renderChart();
  }

  ngOnChanges(changes: SimpleChanges): void {
    if (this.chart) {
      this.updateChart();
    }
  }

  private renderChart() {
    const ctx = this.barCanvas.nativeElement.getContext('2d');
    if (!ctx) return;

    this.chart = new Chart(ctx, {
      type: 'bar',
      data: {
        labels: this.labels,
        datasets: this.datasets.map(ds => ({
          ...ds,
          backgroundColor: ds.backgroundColor ?? '#93c5fd',
        })),
      },
      options: {
        indexAxis: 'y',
        responsive: true,
        plugins: {
          legend: {
            position: 'right',
          },
          title: {
            display: !!this.title,
            text: this.title,
            font: { size: 25 },
            padding: { top: 10, bottom: 5 }
          },
          subtitle: {
            display: !!this.subtitle,
            text: this.subtitle,
            font: { size: 20 },
            color: '#6b7280',
            padding: { bottom: 10 }
          },
          tooltip: {
            bodyFont: {
              size: 16
            },
            titleFont: {
              size: 16
            },
            footerFont: {
              size: 18
            },
            padding: 8,
            callbacks: {
              label: (context) => {
                const value = context.parsed.x ?? context.raw;
                return `${this.currencySymbol}${value}`;
              }
            }
          }
        },
        scales: {
          x: {
            beginAtZero: true,
            ticks: {
              callback: (value: string | number) => {
                return `${this.currencySymbol}${value}`;
              }
            }
          }
        },
        onClick: (event, elements, chart) => {
          const points = chart.getElementsAtEventForMode(
            event as unknown as Event,
            'nearest',
            { intersect: true },
            true
          );
          if (points.length > 0) {
            const point = points[0];
            const label = chart.data.labels?.[point.index];
            const datasetLabel = chart.data.datasets[point.datasetIndex].label;
            const value = chart.data.datasets[point.datasetIndex].data[point.index];
            alert(`Clicked on:\nLabel: ${label}\nDataset: ${datasetLabel}\nValue: ${this.currencySymbol}${value}`);
          }
        }
      }
    });
  }

  private updateChart() {
    if (!this.chart) return;

    this.chart.data.labels = this.labels;
    this.chart.data.datasets = this.datasets.map(ds => ({
      ...ds,
      backgroundColor: ds.backgroundColor ?? '#93c5fd',
    }));

    // ✅ Re-apply formatting logic for currency
    this.chart.options.plugins!.tooltip!.callbacks = {
      label: (context) => {
        const value = context.parsed.x ?? context.raw;
        return `${this.currencySymbol}${value}`;
      }
    };

    this.chart.options.scales = {
      x: {
        beginAtZero: true,
        ticks: {
          callback: (value: string | number) => {
            return `${this.currencySymbol}${value}`;
          }
        }
      }
    };

    this.chart.update();
  }
}
