
import { Component, EventEmitter, Input, OnChanges, Output, SimpleChanges } from '@angular/core';
import { ColumnConfig, ColumnIndexGroup, visibleColumn } from '../informe-tabla-dinamica-local.component';
import { TitleCasePipe } from '@angular/common';
import { ColumnIndexString } from '../informe-tabla-dinamica-local-column-data';

/**
 * Componente selector de columnas para tablas dinámicas.
 * 
 * Permite mostrar/ocultar columnas individualmente mediante checkboxes.
 * 
 * @example
 * <app-column-selector
 *   [allColumns]="columnas"
 *   [visibleColumns]="columnasVisibles"
 *   (visibleColumnsChange)="actualizarColumnas($event)"
 *   [showColumnSelector]="mostrarSelector"
 *   (showColumnSelectorChange)="toggleSelector($event)">
 * </app-column-selector>
 */
@Component({
  selector: 'app-column-selector',
  imports: [
    TitleCasePipe
  ],
  templateUrl: './column-selector.component.html',
  styleUrl: './column-selector.component.css'
})
export class ColumnSelectorComponent implements OnChanges {
  @Input() data: Record<string, string | number>[] = []
  /**
   * Lista completa de configuraciones de columnas disponibles
   * @type {ColumnConfig[]}
   */
  @Input() allColumns: ColumnConfig[] = [];

  @Output() allColumnsChange = new EventEmitter<ColumnConfig[]>()

  /**
   * Indica si el selector de columnas debe mostrarse
   * @type {boolean}
   */
  @Input() showColumnSelector = false;

  /**
 * En caso de que se tenga que tener un formato agrupado, se debe instanciar en el componente.
 * @type {ColumnIndexGroup[]}
 */
  @Input() clusterColumns: ColumnIndexString[] = [];

  /**
   * Evento emitido cuando cambia la visibilidad del selector
   * @type {EventEmitter<boolean>}
   */
  @Output() showColumnSelectorChange = new EventEmitter<boolean>();

  @Output() visibleColumns = new EventEmitter<visibleColumn[]>()
  @Output() normalViewData = new EventEmitter<any>();


  /**
 * En caso de que se tenga que tener un formato agrupado, se debe instanciar en el componente.
 * @type {ColumnIndexGroup[]}
 */
  public clusteredColumns: ColumnIndexGroup[] = [];
  @Output() clusteredColumnsChange = new EventEmitter<ColumnIndexGroup[]>()

  private widthMap: Record<string, number> = {}

  ngOnChanges(changes: SimpleChanges) {
    if (changes['data']) {
      this.initializeColumns();
    }
  }

  private initializeColumns() {
    this.allColumns = [];
    const sampleItem = this.data[0];
    if (!sampleItem) return;
    const keys = Object.keys(sampleItem)

    this.allColumns = this.keysToColumnsConfig(keys)

    this.setWidthMap()

    if (this.clusterColumns.length) {
      this.setClusteredColumns()

      this.allColumns = this.clusteredColumns.flatMap(c => c.indices).map(c => ({
        name: c.name,
        visible: true,
        dataType: this.detectDataType(sampleItem[c.name]),
      }))
    }

    this.setVisibleColumns(this.allColumns)
    this.normalViewData.emit([...this.data])
    this.allColumnsChange.emit(this.allColumns)
    this.clusteredColumnsChange.emit(this.clusteredColumns)
  }

  public checkAll(value: boolean) {
    this.allColumns.forEach(c => c.visible = value)
    // Actualiza la lista de columnas visibles
    if (this.clusterColumns.length) {
      this.clusteredColumns.forEach(c => c.indices.forEach(c => c.visible = value))
      this.clusteredColumns.forEach(c => c.visibleColumns = c.indices.filter(c => c.visible).map(c => c.name))
      //this.clusteredColumnsChange.emit(this.clusteredColumns)
    }
    this.setVisibleColumns(this.allColumns.filter(c => c.visible))
  }

  /**
   * Alterna la visibilidad de una columna específica
   * @param {string} columnName - Nombre de la columna a mostrar/ocultar
   * 
   * @example
   * // Alternar visibilidad de la columna 'nombre'
   * toggleColumnVisibility('nombre');
   */
  public toggleColumnVisibility(columnName: string): void {
    // Busca la columna en la lista completa
    const column = this.allColumns.find(c => c.name === columnName);

    if (column) {
      // Invierte el estado de visibilidad
      column.visible = !column.visible;

      const cluster = this.clusteredColumns.find(c => c.indices.find(c => c.name === columnName))
      if (cluster) {
        cluster.visibleColumns = cluster.indices.filter(c => c.visible).map(c => c.name)
        cluster.style!.thWidth = this.clusterWidth(cluster)
      }
      
      column.visible = !column.visible

      // Actualiza la lista de columnas visibles
      this.setVisibleColumns(this.allColumns.filter(c => c.visible))
    }
  }

  private setVisibleColumns(columns: ColumnConfig[]) {
    this.visibleColumns.emit(columns.map(c => ({ name: c.name, width: this.widthMap[c.name]! })))
  }

  private keysToColumnsConfig(array: string[]): ColumnConfig[] {
    const sampleItem = this.data[0];

    return array.map((key) => ({
      name: key,
      visible: true,
      dataType: this.detectDataType(sampleItem[key]),
    }));
  }

  private setClusteredColumns() {
    const sampleItem = this.data[0];

    this.clusteredColumns = this.clusterColumns.map(group => {
      const matchedIndices: ColumnConfig[] = group.columns.map(gCol => {
        return {
          name: gCol,
          visible: true,
          dataType: this.detectDataType(sampleItem?.[gCol]),
        };
      });

      const indicesWidths: Record<string, number> = {};
      let clusterWidth = 0;

      matchedIndices.forEach(column => {
        indicesWidths[column.name] = this.widthMap[column.name]
        clusterWidth += this.widthMap[column.name]
      });

      group.style = {
        ...group.style,
        thWidth: clusterWidth,
      };

      return {
        name: group.name,
        cluster: group.name,
        style: group.style,
        visible: true,
        visibleColumns: matchedIndices.map(c => c.name),
        indices: matchedIndices,
        indicesWidth: indicesWidths,
      };
    });
  }

  private clusterWidth(cluster: ColumnIndexGroup) {
    if (!cluster.indicesWidth) return 0;
    return cluster.indices
      .filter(column => column.visible)
      .reduce((sum, column) => sum + (this.widthMap[column.name] || 0), 0);
  }

  private detectDataType(value: string | number | boolean | Date): ColumnConfig['dataType'] {
    if (typeof value === 'string') {
      if (!isNaN(Date.parse(value))) return 'date';
      return 'string';
    }
    if (typeof value === 'number') return 'number';
    if (typeof value === 'boolean') return 'boolean';
    return 'string';
  }

  private setWidthMap() {
    const indicesWidths: Record<string, number> = {};

    // Configuración de anchos
    const config = {
      minWidth: 50,    // Ancho mínimo
      maxWidth: 250,   // Ancho máximo
      avgCharWidth: 7, // Píxeles promedio por carácter
      padding: 24,     // Padding + bordes
      sampleSize: 500  // Máximo de filas a muestrear
    };

    this.allColumns.forEach(column => {
      const headerLength = column.name.length;

      // Si hay muchos datos, usamos muestra
      // Longitud máxima de los valores en los datos
      const maxLength = this.data.reduce((max, item) => {
        const value = item[column.name];
        const valueStr = value == null ? '' : String(value);
        return Math.max(max, valueStr.length);
      }, headerLength); // empezamos con headerLength como mínimo

      // Calcular ancho
      let width = Math.max(headerLength, maxLength) * config.avgCharWidth + config.padding;

      // Aplicar límites
      width = Math.max(config.minWidth, Math.min(width, config.maxWidth));

      indicesWidths[column.name] = Math.round(width);
    });

    this.widthMap = indicesWidths;
  }
}