import { inject, Injectable } from '@angular/core';
import { FilterBasedConfig, FilterBasedRow, FilterBasedColumn } from '../filter-based-view-config.component';
import { Cell, Row, Table, TBody, TFoot, THeader } from '../../interfaces/table';
import { MetricConfig } from '../../cross-tab-view-config/components/metrics-config/metrics-config.component';
import { TablaLocalService } from '../../../../../services/tabla-local.service';
import { HashUtilsService } from '../../../../../services/hash-utils.service';

@Injectable({
  providedIn: 'any',
})
export class FilterBasedUtilsService {
  private cache: Record<string, Table> = {}
  private hashUtils = inject(HashUtilsService)
  private tablaLocalService = inject(TablaLocalService)
  /**
   * Aplica filtros a los datos usando TablaLocalService
   * @param data Datos originales
   * @param filters Objeto de filtros {columna: 'condición'}
   * @returns Datos filtrados
   */
  public applyFiltersToData(data: any[], filters: Record<string, string>): any[] {
    if (!filters || Object.keys(filters).length === 0) {
      return data;
    }

    const result = this.tablaLocalService.dataFiltered(data, filters);

    if (result.length === 0) {
      console.warn('⚠️ Ningún registro coincide con los filtros');
    }

    return result;
  }


  /**
   * Genera una tabla basada en configuración de filtros
   * @param config Configuración filter-based
   * @param data Datos originales
   * @returns Objeto Table generado
   */
  public generateFilterBasedTable(config: FilterBasedConfig, data: any[]): Table {
    const cacheKey = this.generateCacheKey(data, config)
    if (this.cache[cacheKey]) {
      return this.cache[cacheKey]
    }

    // Validar configuración
    const validation = this.validateFilterBasedConfig(config);
    if (!validation.isValid) {
      console.error('❌ Error de validación:', validation.errors);
      throw new Error(`Configuración inválida: ${validation.errors.join(', ')}`);
    }

    // Aplicar filtros globales primero
    const globallyFilteredData = this.applyFiltersToData(data, config.globalFilters || {});

    // Generar estructura de encabezados
    const header = this.generateHeader(config);

    // Generar cuerpo de la tabla
    const body = this.generateBody(config, globallyFilteredData);

    // Generar footer si es necesario
    const footer = this.generateFooter(config, globallyFilteredData);

    const table: Table = {
      header: header,
      body: body,
      footer: footer
    }
    this.cache[cacheKey] = table

    return table
  }

  /**
   * Genera la estructura del encabezado
   * @param config Configuración filter-based
   * @returns Estructura de encabezado
   */
  private generateHeader(config: FilterBasedConfig): THeader {
    const firstRow: Array<{ text: string, colspan: number }> = [
      { text: '', colspan: 1 } // Espacio para la columna de etiquetas de filas
    ];

    const secondRow = ['']; // Primera celda vacía para etiquetas

    // Agregar columnas al encabezado
    for (const column of config.columns) {
      firstRow.push({
        text: column.label || 'Columna sin nombre',
        colspan: column.metrics.length
      });

      // Agregar cada métrica como subcolumna
      for (const metric of column.metrics) {
        const metricLabel = this.getMetricLabel(metric);
        secondRow.push(metricLabel);
      }
    }

    return [firstRow, secondRow];
  }

  /**
   * Genera el cuerpo de la tabla
   * @param config Configuración filter-based
   * @param data Datos filtrados globalmente
   * @returns Cuerpo de la tabla
   */
  private generateBody(config: FilterBasedConfig, data: any[]): TBody {
    const body: Row[] = [];

    for (let rowIndex = 0; rowIndex < config.rows.length; rowIndex++) {
      const row = config.rows[rowIndex];
      const rowCells: Cell[] = [];

      // Primera celda: etiqueta de la fila
      rowCells.push(row.label || 'Fila sin nombre');

      // Aplicar filtros específicos de la fila
      const rowFilteredData = this.applyFiltersToData(data, row.filters);

      // Para cada columna, calcular métricas sobre los datos filtrados de la fila
      for (let colIndex = 0; colIndex < config.columns.length; colIndex++) {
        const column = config.columns[colIndex];

        // Aplicar filtros de columna si existen
        const columnFilteredData = column.columnFilters
          ? this.applyFiltersToData(rowFilteredData, column.columnFilters)
          : rowFilteredData;

        // Calcular cada métrica
        for (let metricIndex = 0; metricIndex < column.metrics.length; metricIndex++) {
          const metric = column.metrics[metricIndex];
          const metricFilteredData = metric.metricFilters ? this.applyFiltersToData(columnFilteredData, metric.metricFilters) : columnFilteredData
          const metricValue = this.calculateMetric(metricFilteredData, metric);
          rowCells.push(this.formatCellForTable(this.formatMetricValue(metricValue, metric)));
        }
      }

      body.push({
        cells: rowCells
      });
    }

    return body;
  }

  /**
   * Genera el footer de la tabla (totales)
   * @param config Configuración filter-based
   * @param data Datos
   * @returns Footer de la tabla
   */
  private generateFooter(config: FilterBasedConfig, data: any[]): TFoot {
    const footer: Row[] = [];

    // Fila de totales generales
    const totalRow: Cell[] = [
      'Total General'
    ];

    // Calcular totales para cada métrica en cada columna
    for (const column of config.columns) {
      for (const metric of column.metrics) {
        let totalValue = 0;

        // Sumar valores de todas las filas para esta métrica
        for (const row of config.rows) {
          const rowFilteredData = this.applyFiltersToData(data, row.filters);
          const columnFilteredData = column.columnFilters
            ? this.applyFiltersToData(rowFilteredData, column.columnFilters)
            : rowFilteredData;

          const metricValue = this.calculateMetric(columnFilteredData, metric);
          totalValue += this.parseNumericValue(metricValue) || 0;
        }

        totalRow.push(this.formatCellForTable(this.formatMetricValue(totalValue, metric)));
      }
    }

    footer.push({
      cells: totalRow
    });

    return footer;
  }

  /**
   * Calcula una métrica sobre un conjunto de datos
   * @param data Datos para calcular
   * @param metric Configuración de la métrica
   * @returns Valor calculado
   */
  private calculateMetric(data: any[], metric: MetricConfig): string | number | null {
    if (!data.length) {
      return 0;
    }

    // Aplicar filtros de la métrica si existen
    const filteredData = metric.metricFilters
      ? this.applyFiltersToData(data, metric.metricFilters)
      : data;

    switch (metric.calculation) {
      case 'count':
        return filteredData.length;

      case 'sum':
        if (!metric.valueField) return 0;
        return filteredData.reduce((sum, item) => {
          const value = parseFloat(item[metric.valueField!] || 0);
          return sum + value;
        }, 0);

      case 'average':
        if (!metric.valueField) return 0;
        const sum = filteredData.reduce((sum, item) => {
          const value = parseFloat(item[metric.valueField!] || 0);
          return sum + value;
        }, 0);
        return filteredData.length ? sum / filteredData.length : 0;

      default:
        return filteredData.length;
    }
  }

  /**
   * Obtiene la etiqueta de una métrica
   * @param metric Configuración de la métrica
   * @returns Etiqueta formateada
   */
  private getMetricLabel(metric: MetricConfig): string {
    if (metric.label) {
      return metric.label;
    }

    let label = metric.calculation;
    if (metric.valueField) {
      label += ` (${metric.valueField.replace(/_/g, ' ')})`;
    }
    return label;
  }

  /**
   * Formatea el valor de una métrica según su configuración
   * @param value Valor a formatear
   * @param metric Configuración de la métrica
   * @returns Valor formateado
   */
  formatMetricValue(value: string | number | null | undefined, metric: MetricConfig): string {
    if (!value) return '0';

    // Convertir a número y formatear
    const numValue = Number(value);
    if (isNaN(numValue)) {
      return String(value); // Si no es número, retornar original
    }
    switch (metric.pipe) {
      case 'currency':
        return "$" + numValue.toLocaleString()

      case 'number':
        return new Intl.NumberFormat('es-ES', {
          minimumFractionDigits: metric.minFractionDigits || 0,
          maximumFractionDigits: metric.maxFractionDigits || 2
        }).format(numValue);

      case 'percent':
        return numValue.toFixed(2) + "%"

      default:
        // Para cualquier otro caso, retornar el valor como string
        return String(value);
    }
  }

  /**
   * Formatea un valor para ser usado en una celda de tabla
   * @param value Valor a formatear
   * @returns Valor formateado como Cell
   */
  private formatCellForTable(value: string | number | null | undefined): Cell {
    if (value === null || value === undefined) {
      return '0';
    }
    return value.toString();
  }

  /**
   * Convierte un valor a numérico si es posible
   * @param value Valor a convertir
   * @returns Valor numérico o null
   */
  private parseNumericValue(value: string | number | null | undefined): number | null {
    if (typeof value === 'number') {
      return value;
    }

    if (typeof value === 'string') {
      const parsed = parseFloat(value.replace(/[^\d.-]/g, ''));
      return isNaN(parsed) ? null : parsed;
    }

    return null;
  }

  /**
   * Valida que una configuración filter-based sea correcta
   * @param config Configuración a validar
   * @returns {isValid: boolean, errors: string[]} Resultado de validación
   */
  public validateFilterBasedConfig(config: FilterBasedConfig): { isValid: boolean, errors: string[] } {
    const errors: string[] = [];

    if (!config.name?.trim()) {
      errors.push('La configuración debe tener un nombre');
    }

    if (!config.rows.length) {
      errors.push('La configuración debe tener al menos una fila');
    } else {
      // Validar cada fila
      config.rows.forEach((row, index) => {
        if (!row.label?.trim()) {
          errors.push(`Fila ${index + 1}: La fila debe tener una etiqueta`);
        }
        if (!row.filters || Object.keys(row.filters).length === 0) {
          errors.push(`Fila ${index + 1}: La fila debe tener al menos un filtro`);
        }
      });
    }

    if (!config.columns.length) {
      errors.push('La configuración debe tener al menos una columna');
    } else {
      // Validar cada columna
      config.columns.forEach((column, index) => {
        if (!column.label?.trim()) {
          errors.push(`Columna ${index + 1}: La columna debe tener una etiqueta`);
        }
        if (!column.metrics.length) {
          errors.push(`Columna ${index + 1}: La columna debe tener al menos una métrica`);
        } else {
          // Validar cada métrica
          column.metrics.forEach((metric, metricIndex) => {
            if (!metric.calculation) {
              errors.push(`Columna ${index + 1}, Métrica ${metricIndex + 1}: La métrica debe tener un tipo de cálculo`);
            }
            if (metric.calculation !== 'count' && !metric.valueField) {
              errors.push(`Columna ${index + 1}, Métrica ${metricIndex + 1}: Las métricas de sum/promedio necesitan un campo de valor`);
            }
          });
        }
      });
    }

    return {
      isValid: errors.length === 0,
      errors
    };
  }

  /**
   * Valida que una configuración filter-based sea correcta (método legacy para compatibilidad)
   * @param config Configuración a validar
   * @returns true si es válida, false si no
   */
  public validateFilterBasedConfigLegacy(config: FilterBasedConfig): boolean {
    const result = this.validateFilterBasedConfig(config);
    if (!result.isValid) {
      console.error('❌ Errores de validación:', result.errors);
    }
    return result.isValid;
  }

  private generateCacheKey(dataSource: any[], config: FilterBasedConfig): string {
    const dataHash = this.hashUtils.generateArrayHash(dataSource);
    const configHash = this.hashUtils.generateDataHash(config)
    return `d-${dataHash}-f-${configHash}`;
  }
}