import { Component, Input, Output, EventEmitter } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { TitleCasePipe } from '@angular/common';
import { SelectFieldComponent } from "../../../../../../shared/generic-form/select-field/select-field.component";
import { SimpleFieldComponent } from "../../../../../../shared/generic-form/simple-field/simple-field.component";

// Importar tipos del componente principal
export interface CrossTabConfig {
  id: string;
  rowDimension: string;
  columnDimension?: string;
  columnLabel?: string;
  metrics: any[];
  showInTable: boolean;
  totales: {
    sum?: boolean;
    percent?: boolean;
  };
  graphs?: any[];
  // Filtros globales que se aplican a todas las métricas antes de sus filtros específicos
  globalFilters?: Record<string, string>;
}

export interface ColumnConfig {
  name: string;
  dataType: 'string' | 'number' | 'date' | 'boolean';
}

export interface SelectItem {
  label: string;
  value: string;
}

@Component({
  selector: 'app-cross-tab-config-form',
  standalone: true,
  imports: [
    FormsModule,
    TitleCasePipe,
    SelectFieldComponent,
    SimpleFieldComponent
],
  templateUrl: './cross-tab-config-form.component.html',
  styleUrl: './cross-tab-config-form.component.css'
})
export class CrossTabConfigFormComponent {
  @Input() currentCrossTab: CrossTabConfig | null = null;
  @Input() allColumns: ColumnConfig[] = [];

  @Output() currentCrossTabChange = new EventEmitter<CrossTabConfig>();

  // Variables para manejar filtros globales
  newGlobalFilterColumn: string = '';
  newGlobalFilterCondition: string = '';
  expandedGlobalFilters: boolean = false;

  constructor() { }

  /**
   * Convierte las columnas disponibles en items para un componente SelectField
   */
  public columnsToSelectItem(type?: 'string' | 'number' | 'date' | 'boolean'): SelectItem[] {
    if (!type) {
      return this.allColumns.map(c => ({
        label: c.name.toUpperCase().replaceAll('_', ' '),
        value: c.name
      }));
    }
    return this.columnsByType(type).map(c => ({
      label: c.name.toUpperCase().replaceAll('_', ' '),
      value: c.name
    }));
  }

  /**
   * Emite cambios cuando se modifica el currentCrossTab
   */
  private emitChanges(): void {
    if (this.currentCrossTab) {
      this.currentCrossTabChange.emit(this.currentCrossTab);
    }
  }

  /**
   * Filtra columnas por tipo de dato
   */
  private columnsByType(type: 'string' | 'number' | 'date' | 'boolean') {
    return this.allColumns.filter(c => c.dataType === type);
  }

  /**
   * Alterna la visibilidad de la sección de filtros globales
   */
  toggleGlobalFilters(): void {
    this.expandedGlobalFilters = !this.expandedGlobalFilters;
  }

  updateFilter(filter : {column:string; condition:string;}){
    if(!this.currentCrossTab?.globalFilters) return;
    this.currentCrossTab.globalFilters[filter.column] = filter.condition
  }

  /**
   * Agrega un filtro global
   */
  addGlobalFilter(): void {
    if (!this.currentCrossTab || !this.newGlobalFilterColumn || !this.newGlobalFilterCondition) {
      return;
    }

    if (!this.currentCrossTab.globalFilters) {
      this.currentCrossTab.globalFilters = {};
    }

    this.currentCrossTab.globalFilters[this.newGlobalFilterColumn] = this.newGlobalFilterCondition;

    // Reiniciar inputs
    this.newGlobalFilterColumn = '';
    this.newGlobalFilterCondition = '';

    this.emitChanges();
  }

  /**
   * Elimina un filtro global
   */
  removeGlobalFilter(column: string): void {
    if (!this.currentCrossTab?.globalFilters) {
      return;
    }

    delete this.currentCrossTab.globalFilters[column];

    // Si no quedan filtros, eliminar el objeto
    if (Object.keys(this.currentCrossTab.globalFilters).length === 0) {
      delete this.currentCrossTab.globalFilters;
    }

    this.emitChanges();
  }

  /**
   * Obtiene los filtros globales formateados para visualización
   */
  getFormattedGlobalFilters(): Array<{column: string, condition: string}> {
    if (!this.currentCrossTab?.globalFilters) return [];

    return Object.entries(this.currentCrossTab.globalFilters).map(([column, condition]) => ({
      column,
      condition
    }));
  }

  /**
   * Obtiene columnas disponibles para filtros globales (excluye ya usadas)
   */
  getAvailableColumnsForGlobalFilters(): string[] {
    const usedColumns = Object.keys(this.currentCrossTab?.globalFilters || {});
    return this.allColumns
      .map(col => col.name)
      .filter(col => !usedColumns.includes(col));
  }

  /**
   * Obtiene la cantidad de filtros globales aplicados
   */
  getGlobalFilterCount(): number {
    return this.currentCrossTab?.globalFilters ? Object.keys(this.currentCrossTab.globalFilters).length : 0;
  }
}