import { inject, Injectable } from '@angular/core';
import { CrossTabConfig, MetricConfig } from '../cross-tab-view-config/cross-tab-view-config.component';
import { Cell, CellObject, Row, Table, TBody, TFoot, THeader } from '../interfaces/table';
import { TablaLocalService } from '../../../../services/tabla-local.service';
import { HashUtilsService } from '../../../../services/hash-utils.service';

export interface MetricTotals {
  columnTotals: { [key: string]: number };
  rowTotals: { [key: string]: number };
  grandTotal: number;
  columnPercentages: { [key: string]: number };
  rowPercentages: { [key: string]: number };
}

export interface TotalsData {
  [metricLabel: string]: MetricTotals;
}

export interface CrossViewColumnStructure {
  rowDimension: string;
  columnValues: string[];
  metrics: MetricConfig[];
}

// Interfaz para representar un elemento de datos genérico
export interface DataItem {
  [key: string]: string | number | boolean | null | undefined;
}

// Interfaz para representar filtros
export interface FilterCondition {
  [column: string]: string;
}

// Interfaz para representar una fila de datos cruzados
export interface CrossViewRow {
  [key: string]: string | number | null | undefined;
}

// Interfaz para representar la estructura de encabezados
export interface HeaderStructure {
  firstRow: Array<{ text: string; colspan: number }>;
  secondRow: Array<{ text: string }>;
}

// Interfaz para representar el resultado de generateCrossTab
export interface CrossTabResult {
  crossViewData: CrossViewRow[];
  crossViewColumns: string[];
  crossViewColumnStructure: CrossViewColumnStructure;
  headerStructure: HeaderStructure | null;
}

@Injectable({
  providedIn: 'root',
})
export class CrossTabUtilsService {
  private cache: Record<string, Table> = {}
  private hashUtils = inject(HashUtilsService)
  private tablaLocalService = inject(TablaLocalService)

  /**
   * Aplica filtros específicos de una métrica a los datos
   * @param items Datos originales
   * @param metricFilters Filtros de la métrica
   * @returns Datos filtrados
   */
  private applyMetricFilters(items: DataItem[], metricFilters?: FilterCondition): DataItem[] {
    if (!metricFilters || Object.keys(metricFilters).length === 0) {
      return items;
    }

    return items.filter(item =>
      Object.entries(metricFilters).every(([column, condition]) =>
        this.tablaLocalService.matchFilter(item, column, condition)
      )
    );
  }

  /**
   * Aplica filtros globales a los datos antes de procesar las métricas
   * @param items Datos originales
   * @param globalFilters Filtros globales de la configuración CrossTab
   * @returns Datos filtrados globalmente
   */
  private applyGlobalFilters(items: DataItem[], globalFilters?: FilterCondition): DataItem[] {
    if (!globalFilters || Object.keys(globalFilters).length === 0) {
      return items;
    }

    return items.filter(item =>
      Object.entries(globalFilters).every(([column, condition]) =>
        this.tablaLocalService.matchFilter(item, column, condition)
      )
    );
  }

  public generateTable(config: CrossTabConfig, data: DataItem[]): Table {
    const cacheKey = this.generateCacheKey(data, config)
    if (this.cache[cacheKey]) {
      return this.cache[cacheKey]
    }

    // Aplicar filtros globales para obtener los datos filtrados
    const globallyFilteredData = this.applyGlobalFilters(data, config.globalFilters);
    const crossData = this.generateCrossTab(config, data)

    const header: THeader = [
      ['', ...(crossData.headerStructure?.firstRow ?? [])], 
      [this.titleFormat(config.rowDimension), ...(crossData.headerStructure?.secondRow ?? [])]
    ]
    const body: TBody = crossData.crossViewData.map(cross => 
      this.generateRowCellsAsRow(config, cross, crossData.crossViewColumnStructure.columnValues, config.metrics, globallyFilteredData)
    )
    let footer: TFoot = []

    // Agregar filas de footer si están habilitados los totales
    if (this.shouldShowTotales(config.totales)) {
      footer = this.generateFooterRows(config, crossData, globallyFilteredData, data)
    }

    const table: Table = {
      header: header,
      body: body,
      footer: footer
    }
    this.cache[cacheKey] = table
  
    return table
  }

  public generateCrossTab(config: CrossTabConfig, data: DataItem[]): CrossTabResult {
    const { rowDimension, columnDimension, metrics, globalFilters } = config;

    // Paso 1: Aplicar filtros globales a todo el dataset
    const globallyFilteredData = this.applyGlobalFilters(data, globalFilters);

    const rowValues = [...new Set(
      data.map(item => item[rowDimension])
        .filter(val => val != null && val !== '')
    )];

    // Determinar valores de columna (si hay columnDimension) o usar un solo valor para totales generales
    const columnValues = columnDimension
      ? [...new Set(data.map(item => item[columnDimension] as string))]
      : [config.columnLabel || 'Total General']; // Usar etiqueta personalizada o valor por defecto

    // Generar datos cruzados con múltiples métricas
    const crossViewData = rowValues.map(rowValue => {
      const row: CrossViewRow = { [rowDimension]: rowValue as string | number | null | undefined };

      columnValues.forEach(colValue => {
        let filteredItems: DataItem[];

        if (columnDimension) {
          // Con columna de cruce: filtrar por ambos valores (usando datos ya filtrados globalmente)
          filteredItems = globallyFilteredData.filter(
            item => item[rowDimension] === rowValue && item[columnDimension] === colValue
          );
        } else {
          // Sin columna de cruce: filtrar solo por dimensión de fila (usando datos ya filtrados globalmente)
          filteredItems = globallyFilteredData.filter(item => item[rowDimension] === rowValue);
        }

        // Por cada métrica, calcular su valor
        metrics.forEach(metric => {
          // Paso 2: Aplicar filtros específicos de la métrica sobre los datos ya filtrados globalmente
          const filteredItemsForMetric = this.applyMetricFilters(filteredItems, metric.metricFilters);

          if (metric.calculation === 'cross') {
            if (metric.crossField) {
              // Para métricas de cruce con campo, crear múltiples columnas por cada valor del campo cruzado
              const crossResult = this.calculateValue(
                filteredItemsForMetric, 
                metric.calculation, 
                globallyFilteredData, 
                metric.valueField, 
                metric.crossField, 
                metric.metricFilters
              ) as Record<string, number>;
              
              Object.keys(crossResult).forEach(crossValue => {
                const key = this.crossItemKey(colValue, metric, crossValue);
                row[key] = crossResult[crossValue];
              });
            } else {
              // Para métricas de cruce sin campo (totales generales), crear una sola columna
              const key = this.crossItemKey(colValue, metric, metric.label || 'Total');
              row[key] = this.calculateValue(
                filteredItemsForMetric, 
                metric.calculation, 
                globallyFilteredData, 
                metric.valueField, 
                undefined, 
                metric.metricFilters
              ) as number;
            }
          } else {
            // Para métricas normales, mantener el comportamiento existente pero con filtros aplicados
            const key = this.crossItemKey(colValue, metric);
            row[key] = this.calculateValue(
              filteredItemsForMetric, 
              metric.calculation, 
              globallyFilteredData, 
              metric.valueField, 
              undefined, 
              metric.metricFilters
            ) as number;
          }
        });
      });

      return row;
    });

    // Construir columnas: primero la dimensión de fila, luego cada columna con sus métricas
    // Para métricas cross, crear columnas adicionales por cada valor del campo cruzado
    const crossViewColumns = [rowDimension];

    columnValues.forEach(colValue => {
      metrics.forEach(metric => {
        if (metric.calculation === 'cross') {
          if (metric.crossField) {
            // Para métricas cross con campo, obtener los valores únicos del campo cruzado
            const crossValues = this.getCrossValuesForMetric(data, metric);

            crossValues.forEach(crossValue => {
              const key = this.crossItemKey(colValue, metric, crossValue);
              crossViewColumns.push(key);
            });
          } else {
            // Para métricas cross sin campo (totales generales), crear una sola columna
            const key = this.crossItemKey(colValue, metric, metric.label || 'Total');
            crossViewColumns.push(key);
          }
        } else {
          // Para métricas normales, mantener el comportamiento existente
          const key = this.crossItemKey(colValue, metric);
          crossViewColumns.push(key);
        }
      });
    });

    // Guardar también los metadatos para renderizar encabezados
    const crossViewColumnStructure: CrossViewColumnStructure = {
      rowDimension,
      columnValues,
      metrics
    };

    let totalsData: TotalsData | null;

    // Calcular totales y percentajes si están habilitados
    if (this.shouldShowTotales(config.totales)) {
      totalsData = this.calculateTotalsAndPercentages(config, crossViewData, columnValues, globallyFilteredData, data);
    } else {
      totalsData = null;
    }

    // Generar estructura de encabezados para el HTML
    const headerStructure = this.generateHeaderStructure(crossViewColumnStructure, data);

    return {
      crossViewData,
      crossViewColumns,
      crossViewColumnStructure,
      headerStructure,
    }
  }

  crossItemKey(col: string, metric: MetricConfig, crossValue?: string): string {
    if (crossValue) {
      return `${col}__${metric.label?.replace(/\s+/g, '_') || 'cross'}__${crossValue.replace(/\s+/g, '_')}__${metric.calculation}`;
    }
    return `${col}__${metric.label?.replace(/\s+/g, '_') || 'metric'}__${metric.calculation}`;
  }

  isMetricConfig(value: unknown): value is MetricConfig {
    if (value === null || typeof value !== 'object') {
      return false;
    }

    const config = value as Record<string, unknown>;

    if (typeof config['calculation'] !== 'string' ||
      !['count', 'sum', 'average', 'cross', 'percent'].includes(config['calculation'])) {
      return false;
    }

    // Para cross y percent, el label es opcional, para otros cálculos es requerido
    if (!['cross', 'percent'].includes(config['calculation']) && typeof config['label'] !== 'string') {
      return false;
    }

    const optionalValidations = [
      ['valueField', 'string'],
      ['crossField', 'string'],
      ['pipe', 'string'],
      ['minFractionDigits', 'number'],
      ['maxFractionDigits', 'number']
    ] as const;

    for (const [prop, expectedType] of optionalValidations) {
      if (Object.hasOwn(config, prop) && typeof config[prop] !== expectedType) {
        return false;
      }
    }

    return true;
  }

  calculateTotalsAndPercentages(
    config: { metrics: MetricConfig[], rowDimension: string, globalFilters?: FilterCondition },
    crossData: CrossViewRow[],
    columnValues: string[],
    filteredData: DataItem[],
    originalData?: DataItem[] // ← Datos originales sin filtrar para bases de porcentaje
  ): TotalsData {
    const { metrics } = config;
    const totalsData: TotalsData = {};

    metrics.forEach(metric => {
      const baseLabel = metric.label?.replace(/\s+/g, '_') || metric.calculation;
      const metricLabel = `${baseLabel}_${metric.calculation}`;
      const columnTotals: { [key: string]: number } = {};
      const rowTotals: { [key: string]: number } = {};
      const columnPercentages: { [key: string]: number } = {};
      const rowPercentages: { [key: string]: number } = {};
      let metricGrandTotal = 0;

      // Para métricas cross, necesitamos obtener los valores únicos del campo cruzado
      if (metric.calculation === 'cross') {
        // Obtener los valores únicos del campo cruzado directamente de los datos filtrados
        const crossFieldValues = this.getCrossValuesForMetric(filteredData, metric);

        // Inicializar columnTotals para todas las combinaciones
        columnValues.forEach(colValue => {
          crossFieldValues.forEach(crossValue => {
            const key = this.crossItemKey(colValue, metric, crossValue);
            columnTotals[key] = 0;
          });
        });

        // Calcular totales
        crossData.forEach(row => {
          let rowMetricTotal = 0;
          columnValues.forEach(colValue => {
            crossFieldValues.forEach(crossValue => {
              const key = this.crossItemKey(colValue, metric, crossValue);
              const value = (row[key] as number) || 0;
              columnTotals[key] += value;
              rowMetricTotal += value;
              metricGrandTotal += value;
            });
          });
          const rowKey = `${row[config.rowDimension]}_${metricLabel}`;
          rowTotals[rowKey] = rowMetricTotal;
        });
      } else {
        // Para métricas normales, mantener el comportamiento existente
        columnValues.forEach(colValue => {
          const key = this.crossItemKey(colValue, metric);
          columnTotals[key] = 0;
        });

        crossData.forEach(row => {
          let rowMetricTotal = 0;
          columnValues.forEach(colValue => {
            const key = this.crossItemKey(colValue, metric);
            const value = (row[key] as number) || 0;
            columnTotals[key] += value;
            rowMetricTotal += value;
            metricGrandTotal += value;
          });
          const rowKey = `${row[config.rowDimension]}_${metricLabel}`;
          rowTotals[rowKey] = rowMetricTotal;
        });
      }

      // LÓGICA PARA BASES DE PORCENTAJE SEGÚN CONFIGURACIÓN
      let percentBase: number;

      if (metric.calculation === 'count') {
        // PARA COUNT: Usar configuración percentageBase
        if (metric.percentageBase === 'unfiltered' && originalData) {
          // Porcentaje sobre datos originales (sin filtros globales)
          percentBase = originalData.length;
        } else {
          // Porcentaje sobre datos filtrados (comportamiento default)
          percentBase = filteredData.length;
        }
      } else if (metric.calculation === 'percent') {
        // Los porcentajes no deberían tener porcentajes again
        percentBase = 100; // O podrías omitirlos completamente
      } else {
        // Para sum, average, cross: usar metricGrandTotal (comportamiento tradicional)
        percentBase = metricGrandTotal;
      }

      if (percentBase > 0) {
        Object.keys(columnTotals).forEach(key => {
          columnPercentages[key] = (columnTotals[key] / percentBase) * 100;
        });

        Object.keys(rowTotals).forEach(key => {
          rowPercentages[key] = (rowTotals[key] / percentBase) * 100;
        });
      }

      totalsData[metricLabel] = {
        columnTotals,
        rowTotals,
        grandTotal: metricGrandTotal,
        columnPercentages,
        rowPercentages,
      };
    });

    return totalsData;
  }

  formatMetricValue(value: string | number | null | undefined, metric: MetricConfig): string {
    if (value === undefined) {
      console.error('🚨 formatMetricValue: Recibió undefined - esto no debería pasar', {
        value,
        metric,
        metricLabel: metric.label,
        calculation: metric.calculation
      });
      throw new Error(`formatMetricValue recibió undefined para métrica '${metric.label}' (${metric.calculation})`);
    }

    if (value === null || value === '') return '0';

    // Convertir a número y formatear
    const numValue = Number(value);
    if (isNaN(numValue)) {
      console.warn('⚠️ formatMetricValue: Valor no es número', {
        value,
        metric,
        metricLabel: metric.label,
        typeofValue: typeof value
      });
      return String(value); // Si no es número, retornar original
    }
    switch (metric.pipe) {
      case 'currency':
        return "$" + numValue.toLocaleString()

      case 'number':
        return new Intl.NumberFormat('es-ES', {
          minimumFractionDigits: metric.minFractionDigits || 0,
          maximumFractionDigits: metric.maxFractionDigits || 2
        }).format(numValue);

      case 'percent':
        return numValue.toFixed(2) + "%"

      default:
        // Para cualquier otro caso, retornar el valor como string
        return String(value);
    }
  }

  getTotalCell(col: string, metric: MetricConfig, totalsData: TotalsData | null): string {
    if (!totalsData) {
      console.error('🚨 getTotalCell: totalsData es null', { col, metric });
      return '';
    }

    // Usar la misma lógica que calculateTotalsAndPercentages para generar el label único
    const baseLabel = metric.label?.replace(/\s+/g, '_') || metric.calculation;
    const metricLabel = `${baseLabel}_${metric.calculation}`;
    const metricTotals = totalsData[metricLabel];

    if (!metricTotals) {
      console.error('🚨 getTotalCell: metricTotals no encontrado', {
        metricLabel,
        baseLabel,
        metric,
        availableLabels: Object.keys(totalsData),
        col
      });
      return '';
    }

    const key = this.crossItemKey(col, metric);
    const value = metricTotals.columnTotals[key];

    if (value === undefined) {
      console.error('🚨 getTotalCell: columnTotal key no encontrada', {
        key,
        col,
        metric,
        metricLabel,
        availableKeys: Object.keys(metricTotals.columnTotals),
        columnTotals: metricTotals.columnTotals
      });
      return '0'; // Devolver 0 en lugar de undefined
    }

    return this.formatMetricValue(value, metric);
  }

  getPercentageCell(col: string, metric: MetricConfig, totalsData: TotalsData | null): string {
    if (!totalsData) return '';

    // Usar la misma lógica que calculateTotalsAndPercentages para generar el label único
    const baseLabel = metric.label?.replace(/\s+/g, '_') || metric.calculation;
    const metricLabel = `${baseLabel}_${metric.calculation}`;
    const metricTotals = totalsData[metricLabel];
    if (!metricTotals || metricTotals.grandTotal === 0) return '0';

    const key = this.crossItemKey(col, metric);
    const percentage = metricTotals.columnPercentages[key] || 0;

    return percentage.toFixed(2) + "%";
  }

  getGrandTotalCell(metric: MetricConfig, totalsData: TotalsData | null): string {
    if (!totalsData) return '';

    // Usar la misma lógica que calculateTotalsAndPercentages para generar el label único
    const baseLabel = metric.label?.replace(/\s+/g, '_') || metric.calculation;
    const metricLabel = `${baseLabel}_${metric.calculation}`;
    const metricTotals = totalsData[metricLabel];
    if (!metricTotals) return '';

    return this.formatMetricValue(metricTotals.grandTotal, metric);
  }

  shouldShowTotales(totales?: { sum?: boolean, percent?: boolean }): boolean {
    return totales?.sum === true || totales?.percent === true;
  }

  // Métodos reutilizables para componentes de tablas

  /**
   * Obtiene los valores únicos para un campo de cruce en una métrica
   * @param data Datos originales
   * @param metric Configuración de la métrica
   * @returns Array con valores únicos del campo de cruce
   */
  getCrossValuesForMetric(data: DataItem[], metric: MetricConfig): string[] {
    if (metric.calculation !== 'cross' || !metric.crossField) {
      return [];
    }
    return [...new Set(data.map(item => item[metric.crossField!] as string))].filter(r => r);
  }

  /**
   * Genera una fila de celdas en formato compatible con `Row` (Cell[])
   * @param item Fila de datos procesada del crosstab
   * @param columnValues Valores únicos de la dimensión de columna
   * @param metrics Lista de métricas configuradas
   * @param allData Todos los datos originales (para obtener valores de cruce)
   * @returns Row (es decir: Cell[] = (string | null | CellObject)[])
   */
  private generateRowCellsAsRow(
    config: CrossTabConfig,
    item: CrossViewRow,
    columnValues: string[],
    metrics: MetricConfig[],
    data: DataItem[]
  ): Cell[] {
    const cells: Cell[] = [];

    // Validar la dimensión de fila
    const rowValue = item[config.rowDimension];
    if (rowValue === undefined) {
      console.error('🚨 generateRowCellsAsRow: Dimensión de fila no encontrada', {
        rowDimension: config.rowDimension,
        item,
        availableKeys: Object.keys(item)
      });
      throw new Error(`Dimensión de fila '${config.rowDimension}' no encontrada en los datos`);
    }
    cells.push(rowValue as string)

    columnValues.forEach(col => {
      metrics.forEach(metric => {
        if (metric.calculation === 'cross' && metric.crossField) {
          const crossValues = this.getCrossValuesForMetric(data, metric).filter(v => v != null);

          crossValues.forEach(crossValue => {
            const key = this.crossItemKey(col, metric, crossValue);
            const rawValue = item[key];

            if (rawValue === undefined) {
              console.error('🚨 generateRowCellsAsRow: Key no encontrada en item (métrica cross)', {
                key,
                column: col,
                metric: metric.label,
                crossValue,
                item,
                availableKeys: Object.keys(item),
                generatedKey: this.crossItemKey(col, metric, crossValue)
              });
              throw new Error(`Key '${key}' no encontrada en los datos para métrica cross '${metric.label}'`);
            }

            const value = rawValue == null ? null : rawValue;
            const cellValue = this.formatMetricValue(value, metric)
            cells.push(cellValue);
          });
        } else {
          const key = this.crossItemKey(col, metric);
          const rawValue = item[key];

          if (rawValue === undefined) {
            console.error('🚨 generateRowCellsAsRow: Key no encontrada en item', {
              key,
              column: col,
              metric: metric.label,
              metricConfig: metric,
              item,
              availableKeys: Object.keys(item),
              generatedKey: this.crossItemKey(col, metric),
              rowDimension: config.rowDimension,
              columnDimension: config.columnDimension
            });
            throw new Error(`Key '${key}' no encontrada en los datos para métrica '${metric.label}' en columna '${col}'`);
          }

          const value = rawValue == null ? null : rawValue;
          const cellValue = this.formatMetricValue(value, metric)
          cells.push(cellValue);
        }
      });
    });

    return cells;
  }

  /**
   * @deprecated quitar proximamente
   * Genera las celdas de datos para una fila específica
   * @param item Fila de datos
   * @param columnValues Valores de columna
   * @param metrics Lista de métricas
   * @param allData Todos los datos disponibles para obtener valores de cruce
   * @returns Array de celdas con datos pre-procesados
   * 
   */
  generateRowCells(item: CrossViewRow, columnValues: string[], metrics: MetricConfig[], allData: DataItem[]): Array<{ value: any, metric: MetricConfig, col: string, crossValue?: string }> {
    const cells: Array<{ value: any, metric: MetricConfig, col: string, crossValue?: string }> = [];

    columnValues.forEach(col => {
      metrics.forEach(metric => {
        if (metric.calculation === 'cross') {
          const crossValues = this.getCrossValuesForMetric(allData, metric);
          crossValues.forEach(crossValue => {
            const key = this.crossItemKey(col, metric, crossValue);
            cells.push({
              value: item[key],
              metric,
              col,
              crossValue
            });
          });
        } else {
          const key = this.crossItemKey(col, metric);
          cells.push({
            value: item[key],
            metric,
            col
          });
        }
      });
    });

    return cells;
  }

  /**
   * Genera las celdas de totales para el footer
   * @param columnValues Valores de columna
   * @param metrics Lista de métricas
   * @param totalsData Datos de totales
   * @param data Datos originales para obtener valores de cruce
   * @returns Array de celdas con valores de totales
   */
  generateTotalCells(columnValues: string[], metrics: MetricConfig[], totalsData: TotalsData | null, data: DataItem[]): Array<{ value: string }> {
    const cells: Array<{ value: string }> = [];

    columnValues.forEach(col => {
      metrics.forEach(metric => {
        if (metric.calculation === 'cross') {
          const crossValues = this.getCrossValuesForMetric(data, metric);
          crossValues.forEach(crossValue => {
            cells.push({
              value: this.getTotalCrossCell(col, metric, crossValue, totalsData)
            });
          });
        } else {
          cells.push({
            value: this.getTotalCell(col, metric, totalsData)
          });
        }
      });
    });

    return cells;
  }

  /**
   * Genera las celdas de percentajes para el footer
   * @param columnValues Valores de columna
   * @param metrics Lista de métricas
   * @param totalsData Datos de totales
   * @param data Datos originales para obtener valores de cruce
   * @returns Array de celdas con valores de percentajes
   */
  generatePercentageCells(columnValues: string[], metrics: MetricConfig[], totalsData: TotalsData | null, data: DataItem[]): Array<{ value: string }> {
    const cells: Array<{ value: string }> = [];

    columnValues.forEach(col => {
      metrics.forEach(metric => {
        if (metric.calculation === 'cross') {
          const crossValues = this.getCrossValuesForMetric(data, metric);
          crossValues.forEach(crossValue => {
            cells.push({
              value: this.getPercentageCrossCell(col, metric, crossValue, totalsData)
            });
          });
        } else {
          cells.push({
            value: this.getPercentageCell(col, metric, totalsData)
          });
        }
      });
    });

    return cells;
  }

  /**
   * Genera los gran totales para el footer
   * @param metrics Lista de métricas
   * @param totalsData Datos de totales
   * @param data Datos originales para obtener valores de cruce
   * @returns Array de totales agrupados por métrica
   */
  generateGrandTotals(metrics: MetricConfig[], totalsData: TotalsData | null, data: DataItem[]): Array<{ label: string, value: string }> {
    const totals: Array<{ label: string, value: string }> = [];

    metrics.forEach(metric => {
      const label = metric.label || metric.calculation;

      if (metric.calculation === 'cross') {
        const crossValues = this.getCrossValuesForMetric(data, metric);
        crossValues.forEach(crossValue => {
          totals.push({
            label: `${crossValue}`,
            value: this.getGrandTotalCrossCell(metric, crossValue, totalsData)
          });
        });
      } else {
        totals.push({
          label,
          value: this.getGrandTotalCell(metric, totalsData)
        });
      }
    });

    return totals;
  }

  /**
   * Calcula el número total de columnas en la tabla
   * @param columnValues Valores de columna
   * @param metrics Lista de métricas
   * @param data Datos originales para obtener valores de cruce
   * @returns Número total de columnas
   */
  getTotalColumnsCount(columnValues: string[], metrics: MetricConfig[], data: DataItem[]): number {
    return columnValues.reduce((total, colValue) => {
      return total + metrics.reduce((metricTotal, metric) => {
        if (metric.calculation === 'cross') {
          const crossValues = this.getCrossValuesForMetric(data, metric);
          return metricTotal + crossValues.length;
        } else {
          return metricTotal + 1;
        }
      }, 0);
    }, 0);
  }

  /**
   * Obtiene el valor de total para una celda de métrica cross
   * @param col Valor de la columna
   * @param metric Configuración de la métrica
   * @param crossValue Valor del campo de cruce
   * @param totalsData Datos de totales
   * @returns Valor formateado del total
   */
  getTotalCrossCell(col: string, metric: MetricConfig, crossValue: string, totalsData: TotalsData | null): string {
    if (!totalsData) {
      console.error('🚨 getTotalCrossCell: totalsData es null', { col, metric, crossValue });
      return '';
    }

    // Usar la misma lógica que calculateTotalsAndPercentages para generar el label único
    const baseLabel = metric.label?.replace(/\s+/g, '_') || metric.calculation;
    const metricLabel = `${baseLabel}_${metric.calculation}`;
    const metricTotals = totalsData[metricLabel];

    if (!metricTotals) {
      console.error('🚨 getTotalCrossCell: metricTotals no encontrado', {
        metricLabel,
        baseLabel,
        metric,
        crossValue,
        availableLabels: Object.keys(totalsData),
        col
      });
      return '';
    }

    const key = this.crossItemKey(col, metric, crossValue);
    const value = metricTotals.columnTotals[key];

    if (value === undefined) {
      console.error('🚨 getTotalCrossCell: columnTotal key no encontrada', {
        key,
        col,
        metric,
        crossValue,
        metricLabel,
        availableKeys: Object.keys(metricTotals.columnTotals),
        columnTotals: metricTotals.columnTotals,
        generatedKey: this.crossItemKey(col, metric, crossValue)
      });
      return '0'; // Devolver 0 en lugar de undefined
    }

    return this.formatMetricValue(value, metric);
  }

  /**
   * Obtiene el valor de percentaje para una celda de métrica cross
   * @param col Valor de la columna
   * @param metric Configuración de la métrica
   * @param crossValue Valor del campo de cruce
   * @param totalsData Datos de totales
   * @returns Valor del percentaje formateado
   */
  getPercentageCrossCell(col: string, metric: MetricConfig, crossValue: string, totalsData: TotalsData | null): string {
    if (!totalsData) return '';

    // Usar la misma lógica que calculateTotalsAndPercentages para generar el label único
    const baseLabel = metric.label?.replace(/\s+/g, '_') || metric.calculation;
    const metricLabel = `${baseLabel}_${metric.calculation}`;
    const metricTotals = totalsData[metricLabel];
    if (!metricTotals || metricTotals.grandTotal === 0) return '0';

    const key = this.crossItemKey(col, metric, crossValue);
    const percentage = metricTotals.columnPercentages[key] || 0;

    return percentage.toFixed(2) + "%";
  }

  /**
   * Obtiene el gran total para una métrica cross específica y valor de cruce
   * @param metric Configuración de la métrica
   * @param crossValue Valor del campo de cruce
   * @param totalsData Datos de totales
   * @returns Gran total formateado
   */
  getGrandTotalCrossCell(metric: MetricConfig, crossValue: string, totalsData: TotalsData | null): string {
    if (!totalsData) return '';

    // Usar la misma lógica que calculateTotalsAndPercentages para generar el label único
    const baseLabel = metric.label?.replace(/\s+/g, '_') || metric.calculation;
    const metricLabel = `${baseLabel}_${metric.calculation}`;
    const metricTotals = totalsData[metricLabel];
    if (!metricTotals) return '';

    // Sumar todos los valores para este valor de cruce específico
    let total = 0;
    Object.keys(metricTotals.columnTotals).forEach(key => {
      if (crossValue && key.includes(`__${crossValue.replace(/\s+/g, '_')}`)) {
        total += metricTotals.columnTotals[key];
      }
    });

    return this.formatMetricValue(total, metric);
  }

  /**
   * Genera la estructura de encabezados para el HTML
   */
  private generateHeaderStructure(
    crossViewColumnStructure: CrossViewColumnStructure | null | undefined,
    data: DataItem[],
  ): HeaderStructure | null {
    if (!crossViewColumnStructure) {
      return null;
    }

    const firstRow: Array<{ text: string; colspan: number }> = [];
    const secondRow: Array<{ text: string }> = [];

    // Contar cuántas métricas usan el mismo valueField para detectar duplicados
    const valueFieldCounts: Record<string, number> = {};
    crossViewColumnStructure.metrics.forEach(metric => {
      if (metric.valueField) {
        valueFieldCounts[metric.valueField] = (valueFieldCounts[metric.valueField] || 0) + 1;
      }
    });

    crossViewColumnStructure.columnValues.forEach(col => {
      crossViewColumnStructure.metrics.forEach(metric => {
        if (metric.calculation === 'cross') {
          const crossValues = this.getCrossValuesForMetric(data, metric).filter(r => r);
          this.addColHeaderFirstRow(col, firstRow, crossValues.length);
          crossValues.forEach(crossValue => {
            secondRow.push({ text: crossValue });
          });
        } else {
          this.addColHeaderFirstRow(col, firstRow);

          // Si hay múltiples métricas para el mismo valueField, incluir el tipo de cálculo
          let displayText = metric.label || metric.calculation;
          secondRow.push({ text: displayText });
        }
      });
    });

    return { firstRow, secondRow };
  }

  private addColHeaderFirstRow(
    col: string,
    firstRow: Array<{ text: string; colspan: number }>,
    colspan: number = 1
  ): void {
    const find = firstRow.find(r => r.text === col)
    if (find) {
      find.colspan += colspan
      return;
    }
    firstRow.push({ text: col, colspan });
  }

  /**
   * Genera las filas de footer (totales, porcentajes y gran total) para la tabla
   * @param config Configuración de la tabla cruzada
   * @param crossData Datos procesados del crosstab
   * @param filteredData Datos filtrados (para bases de porcentaje)
   * @param originalData Datos originales sin filtrar (para bases de porcentaje)
   * @returns Array de filas de footer con estilos aplicados
   */
  private generateFooterRows(config: CrossTabConfig, crossData: CrossTabResult, filteredData: DataItem[], originalData: DataItem[]): TFoot {
    const footerRows: Row[] = []
    const totalsData = this.calculateTotalsAndPercentages(config, crossData.crossViewData, crossData.crossViewColumnStructure.columnValues, filteredData, originalData)

    // Fila de totales (table-primary fw-bold)
    if (config.totales?.sum) {
      const totalsRow = this.generateTotalsRow(crossData.crossViewColumnStructure, config.metrics, totalsData, originalData)
      footerRows.push(totalsRow)
    }

    // Fila de porcentajes (table-info fw-bold)
    if (config.totales?.percent) {
      const percentagesRow = this.generatePercentagesRow(crossData.crossViewColumnStructure, config.metrics, totalsData, originalData)
      footerRows.push(percentagesRow)
    }

    // Fila de gran total (table-secondary fw-bold)
    if (config.totales?.sum || config.totales?.percent) {
      const grandTotalRow = this.generateGrandTotalRow(crossData.crossViewColumnStructure, config.metrics, totalsData, originalData)
      footerRows.push(grandTotalRow)
    }

    return footerRows
  }

  /**
   * Genera la fila de totales con estilo table-primary
   */
  private generateTotalsRow(columnStructure: CrossViewColumnStructure, metrics: MetricConfig[], totalsData: TotalsData | null, data: DataItem[]): Cell[] {
    const row: Cell[] = []

    // Primera celda: etiqueta "Totales"
    row.push({ text: 'Totales', style: 'table-primary fw-bold' })

    // Agregar celdas de totales para cada columna/métrica
    columnStructure.columnValues.forEach(col => {
      metrics.forEach(metric => {
        if (metric.calculation === 'cross' && metric.crossField) {
          const crossValues = this.getCrossValuesForMetric(data, metric)
          crossValues.forEach(crossValue => {
            const value = this.getTotalCrossCell(col, metric, crossValue, totalsData)
            row.push({ text: value, style: 'table-primary fw-bold' })
          })
        } else {
          const value = this.getTotalCell(col, metric, totalsData)
          row.push({ text: value, style: 'table-primary fw-bold' })
        }
      })
    })

    return row
  }

  /**
   * Genera la fila de porcentajes con estilo table-info
   */
  private generatePercentagesRow(columnStructure: CrossViewColumnStructure, metrics: MetricConfig[], totalsData: TotalsData | null, data: DataItem[]): Cell[] {
    const row: Cell[] = []

    // Primera celda: etiqueta "Porcentajes"
    row.push({ text: 'Porcentajes', style: 'table-info fw-bold' })

    // Agregar celdas de porcentajes para cada columna/métrica
    columnStructure.columnValues.forEach(col => {
      metrics.forEach(metric => {
        if (metric.calculation === 'cross' && metric.crossField) {
          const crossValues = this.getCrossValuesForMetric(data, metric)
          crossValues.forEach(crossValue => {
            const value = this.getPercentageCrossCell(col, metric, crossValue, totalsData)
            row.push({ text: value, style: 'table-info fw-bold' })
          })
        } else {
          const value = this.getPercentageCell(col, metric, totalsData)
          row.push({ text: value, style: 'table-info fw-bold' })
        }
      })
    })

    return row
  }

  /**
   * Genera la fila de gran total con estilo table-secondary
   */
  private generateGrandTotalRow(columnStructure: CrossViewColumnStructure, metrics: MetricConfig[], totalsData: TotalsData | null, data: DataItem[]): Cell[] {
    const row: CellObject[] = []

    // Primera celda: etiqueta "Gran Total"
    row.push({ text: 'Gran Total', style: 'table-secondary fw-bold' })

    // Agregar celdas de gran total para cada métrica
    columnStructure.columnValues.forEach(col => {
      metrics.forEach(metric => {
        if (metric.calculation === 'cross' && metric.crossField) {
          const crossValues = this.getCrossValuesForMetric(data, metric)
          crossValues.forEach(crossValue => {
            const value = this.getGrandTotalCrossCell(metric, crossValue, totalsData)
            const displayText = this.titleFormat((metric.label ?? metric.valueField)) + (" (" + this.titleFormat(crossValue) + ")") + ": " + value
            const find = row.find(i => i.text === displayText)
            if (find) {
              find.colspan = (find.colspan ?? 1) + 1
              return;
            }
            row.push({ text: displayText, style: 'table-secondary fw-bold' })
          })
        } else {
          const value = this.getGrandTotalCell(metric, totalsData)
          const displayText = this.titleFormat(metric.label ?? metric.valueField) + ": " + value
          const find = row.find(i => i.text === displayText)
          if (find) {
            find.colspan = (find.colspan ?? 1) + 1
            return;
          }
          row.push({ text: displayText, style: 'table-secondary fw-bold' })
        }
      })
    })

    return row
  }

  /**
   * Crea un objeto temporal para usar con el pipe metricvalue
   * @param key Clave del objeto
   * @param value Valor del objeto
   * @returns Objeto temporal con la estructura esperada por el pipe
   */
  public createRowObject(key: string, value: number): Record<string, number> {
    const obj: Record<string, number> = {};
    obj[key] = value;
    return obj;
  }

  /**
   * Formatea el label de una métrica para usar como clave
   * @param label Label de la métrica
   * @returns Label formateado
   */
  public formatMetricLabel(label: string): string {
    return label.replace(/\s+/g, '_');
  }

  private titleFormat(value: string | number | null | undefined): string {
    if (value == null || value === '') {
      return '';
    }

    return value
      .toString()
      .toLowerCase()
      .replace(/[_-]+/g, ' ')        // Reemplaza _ o - por espacios
      .split(' ')
      .filter(word => word.length > 0) // Elimina palabras vacías (por si hay espacios múltiples)
      .map(word => word.charAt(0).toUpperCase() + word.slice(1))
      .join(' ');
  }

  /**
   * Calcula el valor según el tipo de operación
   * @private
   * @param {DataItem[]} items - Elementos a calcular (ya filtrados por filtros de métrica)
   * @param {string} calculation - Tipo de cálculo (count, sum, average)
   * @param {DataItem[]} data - Datos completos para cálculos de porcentaje
   * @param {string} [valueField] - Campo a calcular (para sum y average)
   * @param {string} [crossField] - Campo de cruce (para cross)
   * @param {FilterCondition} [metricFilters] - Filtros aplicados a esta métrica
   * @returns {number | Record<string, number>} Resultado del cálculo
   */
  private calculateValue(
    items: DataItem[], 
    calculation: string, 
    data: DataItem[], 
    valueField?: string, 
    crossField?: string, 
    metricFilters?: FilterCondition
  ): number | Record<string, number> {
    switch (calculation) {
      case 'count':
        return items.length;
      case 'sum':
        return valueField ? items.reduce((sum, item) => sum + (Number(item[valueField]) || 0), 0) : 0;
      case 'average':
        const sum = valueField ? items.reduce((sum, item) => sum + (Number(item[valueField]) || 0), 0) : 0;
        return items.length > 0 ? sum / items.length : 0;
      case 'percent':
        if (!valueField) return 0;

        // Para cálculos de porcentaje, aplicar los mismos filtros al total general
        // para mantener consistencia en el cálculo
        let totalValue: number;
        if (metricFilters && Object.keys(metricFilters).length > 0) {
          // Aplicar filtros de métrica al total de datos
          const filteredTotalData = this.applyMetricFilters(data, metricFilters);
          totalValue = filteredTotalData.reduce((total, item) => total + (Number(item[valueField]) || 0), 0);
        } else {
          // Sin filtros, usar todos los datos
          totalValue = data.reduce((total, item) => total + (Number(item[valueField]) || 0), 0);
        }

        if (totalValue === 0) return 0;

        // Calcular el subtotal para los items ya filtrados
        const subTotal = items.reduce((sum, item) => sum + (Number(item[valueField]) || 0), 0);

        // Calcular el porcentaje
        return (subTotal / totalValue) * 100;
      case 'cross':
        if (!crossField || !valueField) return {};

        // Agrupar por los valores del campo de cruce
        const crossValues = [...new Set(items.map(item => item[crossField] as string))].filter(r => r);

        const result: Record<string, number> = {};

        crossValues.forEach(crossValue => {
          const filteredItems = items.filter(item => item[crossField] === crossValue);
          result[crossValue] = valueField ?
            filteredItems.reduce((sum, item) => sum + (Number(item[valueField]) || 0), 0) :
            filteredItems.length;
        });

        return result;
      default:
        return 0;
    }
  }

  private generateCacheKey(dataSource: DataItem[], config: CrossTabConfig): string {
    const dataHash = this.hashUtils.generateArrayHash(dataSource);
    const configHash = this.hashUtils.generateDataHash(config)
    return `d-${dataHash}-f-${configHash}`;
  }
}