import { Component, Input, Output, EventEmitter } from '@angular/core';
import { NgClass, TitleCasePipe } from '@angular/common';
import { MetricConfig, MetricConfigCalculation } from '../metrics-config/metrics-config.component';

// Reutilizar interfaces del componente principal
export interface CrossTabConfig {
  id: string;
  rowDimension: string;
  columnDimension?: string;
  columnLabel?: string;
  metrics: MetricConfig[];
  showInTable: boolean;
  totales: {
    sum?: boolean;
    percent?: boolean;
  };
  graphs?: any[];
}

@Component({
  selector: 'app-cross-tab-list-preview',
  standalone: true,
  imports: [
    NgClass,
    TitleCasePipe
  ],
  templateUrl: './cross-tab-list-preview.component.html',
  styleUrl: './cross-tab-list-preview.component.css'
})
export class CrossTabListPreviewComponent {
  @Input() crossTabConfigs: CrossTabConfig[] = [];
  @Input() currentCrossTab: CrossTabConfig | null = null;

  @Output() edit = new EventEmitter<CrossTabConfig>();
  @Output() remove = new EventEmitter<string>();
  @Output() generate = new EventEmitter<CrossTabConfig>();
  @Output() add = new EventEmitter<void>();
  @Output() clone = new EventEmitter<CrossTabConfig>();

  constructor() { }

  /**
   * Emite evento para editar una configuración
   */
  public onEdit(config: CrossTabConfig): void {
    this.edit.emit(config);
  }

  /**
   * Emite evento para eliminar una configuración
   */
  public onRemove(configId: string): void {
    this.remove.emit(configId);
  }

  /**
   * Emite evento para generar/activar una configuración
   */
  public onGenerate(config: CrossTabConfig): void {
    this.generate.emit(config);
  }

  /**
   * Emite evento para agregar una nueva configuración
   */
  public onAdd(): void {
    this.add.emit();
  }

  /**
   * Emite evento para clonar una configuración existente
   */
  public onClone(config: CrossTabConfig): void {
    this.clone.emit(config);
  }

  /**
   * Verifica si una configuración está activa actualmente
   */
  public isCurrentConfig(config: CrossTabConfig): boolean {
    return this.currentCrossTab?.id === config.id;
  }

  /**
   * Obtiene el display formateado para una métrica
   */
  public getMetricDisplay(metric: MetricConfig): string {
    if (metric.label) {
      return metric.label;
    }

    let display = metric.calculation;

    if (metric.valueField && !metric.label) {
      display += ` (${metric.valueField.replaceAll('_', ' ')}`;
      if (metric.crossField) {
        display += ` X ${metric.crossField.replaceAll('_', ' ')}`;
      }
      display += ')';
    }

    return display;
  }
}